VALUES
  ('cpiuris2025::9d9621ba4e763dc7b11e0f4d814e7911', 'doutrina', 'cp_iuris', 'Direito Constitucional — Transformação em Estados e extinção por reincorporação', '## Transformação em Estados e extinção por reincorporação

Os Territórios Federais de Roraima e do Amapá são transformados em Estados Federados, mantendo seus limites geográficos. A instalação dos novos estados ocorrerá com a posse dos governadores eleitos em 1990.

### Conceitos
- **Transformação de Território Federal**: Mudança do status de Território Federal para Estado Federal
- **Reincorporação**: Incorporação de um Território Federal ao Estado de outro, mantendo sua identidade jurídica
- **Instalação de Estado**: Procedimento pelo qual um novo estado é criado e começa a funcionar
- **Posse do Governador**: Ato pelo qual o governador assume o cargo e assume a administração do estado
- **Criação de Estado**: Procedimento pelo qual um novo estado é criado

### Referências legais
- Art. 14 ADCT

### Dicas de prova
- Entenda a diferença entre transformação e reincorporação
- Conheça o procedimento de instalação de um novo estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.348 (2)", "page_number": 348, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14 ADCT"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:06:01.183624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=348", "doc_key": "9d9621ba4e763dc7b11e0f4d814e7911"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b0aafa1088eeca02d822194f39a54ba694ee7d388cda2ec0fd84bd869a58fb8c'),
  ('cpiuris2025::ab2c3ab19e3ad0ae3e5821a68b451950', 'doutrina', 'cp_iuris', 'Direito Constitucional — Territórios Federais e sua Organização', '## Territórios Federais e sua Organização

O texto constitucional estabelece regras para a criação, organização e funcionamento dos Territórios Federais, incluindo a divisão em Municípios, eleições e competência judiciária.

### Conceitos
- **Território Federal**: Entidade política criada pela Constituição para governar uma região específica do país
- **Divisão em Municípios**: Opcional, mas obrigatória para Territórios Federais com mais de 100 mil habitantes
- **Órgãos Judiciários**: Haverá órgãos judiciários de primeira e segunda instância em Territórios Federais com mais de 100 mil habitantes
- **Eleições para a Câmara Territorial**: A lei disporá sobre as eleições para a Câmara Territorial e sua competência deliberativa
- **Governador de Território**: Escolhido pelo Presidente da República, após arguição pública pelo Senado Federal
- **Impostos**: Pertence à União em Território Federal, os impostos estaduais e municipais
- **Deputados Federais**: Cada território elegerá quatro deputados federais

### Referências legais
- Art. 33 da CF/88
- Art. 159, I, ''a'', da CF/88
- Art. 34, § 2º, II, do Ato que estabelece a Constituição

### Dicas de prova
- Distinção entre Territórios Federais e Estados
- Importância da divisão em Municípios para os Territórios Federais
- Regras sobre órgãos judiciários e eleições para a Câmara Territorial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.349 (1)", "page_number": 349, "discipline": "Direito Constitucional", "legal_refs": ["Art. 33 da CF/88", "Art. 159, I, ''a'', da CF/88", "Art. 34, § 2º, II, do Ato que estabelece a Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:06:49.605154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=349", "doc_key": "ab2c3ab19e3ad0ae3e5821a68b451950"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c26af9100425976536c084e5e337bcec1b190a133921c69ba5cb61fb7402c7c7'),
  ('cpiuris2025::bea2e7dbfd9c0926a6eb8c5723db3d00', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autolegislação', '## Autolegislação

A autolegislação permite que os estados elaborem suas próprias constituições, desde que observadas as principais diretrizes da Constituição Federal.

### Conceitos
- **autolegislação**: Elaboração de constituições estaduais
- **princípios constitucionais sensíveis**: Princípios fundamentais que devem ser observados
- **forma republicana**: Sistema de governo representativo
- **direitos da pessoa humana**: Direitos fundamentais do cidadão
- **autonomia municipal**: Direito dos municípios de governar-se
- **prestação de contas**: Obrigação de a administração pública ser transparente

### Referências legais
- Art. 34, VII da CF

### Dicas de prova
- Entenda o conceito de autolegislação e os princípios que devem ser observados
- Identifique os principais direitos e liberdades garantidos pela Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.349 (2)", "page_number": 349, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, VII da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:07:25.522190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=349", "doc_key": "bea2e7dbfd9c0926a6eb8c5723db3d00"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '33b9f48fd9cfa5bc407dc02aa983f99236aa0ae5769360f7beaf4ed9f9cb728a'),
  ('cpiuris2025::2b27cec8f5ed5763339012da91cf07f1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios constitucionais extensíveis e estabelecidos', '## Princípios constitucionais extensíveis e estabelecidos

Os princípios constitucionais extensíveis são regras de organização que a Constituição estendeu aos estados-membros, ao Distrito Federal e aos municípios. Os princípios constitucionais estabelecidos limitam a autonomia organizatória do Estado.

### Conceitos
- **Princípios constitucionais extensíveis**: Regras de organização que a Constituição estendeu aos estados-membros, ao Distrito Federal e aos municípios.
- **Princípios constitucionais estabelecidos**: Diversos princípios que limitam a autonomia organizatória do Estado

### Referências legais
- Art. 27, caput, da CF/88

### Dicas de prova
- Entenda a diferença entre os princípios constitucionais extensíveis e estabelecidos.
- Conheça as normas que regem o processo legislativo, o sistema constitucional tributário e a Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.350 (1)", "page_number": 350, "discipline": "Direito Constitucional", "legal_refs": ["Art. 27, caput, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:07:55.169498+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=350", "doc_key": "2b27cec8f5ed5763339012da91cf07f1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '438e961d643e1c4fceae47e32da26726003e2a9f461a021becba85986883dd27'),
  ('cpiuris2025::77a987be91747fe50467034d86076294', 'doutrina', 'cp_iuris', 'Direito Constitucional — Subsídio dos Deputados Estaduais', '## Subsídio dos Deputados Estaduais

O subsídio dos deputados estaduais deve ser no máximo de 75% do subsídio de um deputado federal, sendo fixado por lei e não vinculado ao quantum estipulado pela União.

### Conceitos
- **Subsídio**: ajuda financeira concedida a parlamentares
- **Lei de Iniciativa Popular**: leis que tramitam em Assembleia Legislativa
- **Subsídio Federal**: ajuda financeira concedida a deputados federais

### Referências legais
- Art. 27, §2º da CF/88

### Jurisprudência
- ADI 6437/MT
- ADI 6468/SE
- Informativo 1024, STF

### Dicas de prova
- Distinção entre subsídio federal e estadual
- Importância da Lei de Iniciativa Popular
- Vinculação do subsídio aos quantum estipulado pela União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.350 (2)", "page_number": 350, "discipline": "Direito Constitucional", "legal_refs": ["Art. 27, §2º da CF/88"], "jurisprudence": ["ADI 6437/MT", "ADI 6468/SE", "Informativo 1024, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T12:08:22.365826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=350", "doc_key": "77a987be91747fe50467034d86076294"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'aa0747c674b5ab33efb5f288dcbc1868c712b8c74f333443a254e8202fc52bda'),
  ('cpiuris2025::8ed52f5280ca2b4482d998bef67c7e9c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites remuneratórios dos governadores e outros órgãos do Poder Executivo', '## Limites remuneratórios dos governadores e outros órgãos do Poder Executivo

O texto discute os limites remuneratórios para governadores, vice-governadores e outros órgãos do Poder Executivo, bem como as regras sobre a competência dos estados e a criação de regiões metropolitanas.

### Conceitos
- **Subsídio**: remuneração recebida por governador ou vice-governador
- **Teto remuneratório**: limite máxima para o subsídio de um órgão do Poder Executivo
- **Competência residual**: competências que não estão vedadas pela Constituição Federal
- **Região metropolitana**: área composta por municípios limítrofes

### Referências legais
- Art. 28, §2º, CF/88
- Art. 25, §3º, CF/88

### Dicas de prova
- Entenda a diferença entre subsídio e teto remuneratório.
- Conheça as regras sobre competência residual e sua importância nos estados.
- Aprenda a criar regiões metropolitanas e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.351 (1)", "page_number": 351, "discipline": "Direito Constitucional", "legal_refs": ["Art. 28, §2º, CF/88", "Art. 25, §3º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:09:05.354587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=351", "doc_key": "8ed52f5280ca2b4482d998bef67c7e9c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd523f9142f29db138092bf8d1fecbbff610f09a9bad148d73f88d5bb0e65edcc'),
  ('cpiuris2025::1452b07734294e8ebb015c6cbc2b39a2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Definição de Regiões Metropolitanas, Aglomerações Urbanas e Microrregiões', '## Definição de Regiões Metropolitanas, Aglomerações Urbanas e Microrregiões

Regiões metropolitanas, aglomerações urbanas e microrregiões são categorias de regiões públicas de interesse comum definidas pela Constituição. A diferença entre elas está na continuidade urbana e no município polo.

### Conceitos
- **Região Metropolitana**: conjunto de municípios limítrofes com certa continuidade urbana e que se reúnem em torno de um município polo
- **Aglomeração Urbana**: áreas urbanas de municípios limítrofes, mas não há município sede central, com grande densidade populacional e continuidade urbana
- **Microrregião**: municípios limítrofes com características homogêneas e problemas comuns, sem continuidade urbana

### Referências legais
- Art. 25 da Constituição Federal

### Dicas de prova
- Diferenciar entre as categorias de regiões públicas de interesse comum
- Entender a importância do município polo em Região Metropolitana
- Conhecer as limitações do Poder Constituinte Derivado Decorrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.351 (2)", "page_number": 351, "discipline": "Direito Constitucional", "legal_refs": ["Art. 25 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:09:36.440946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=351", "doc_key": "1452b07734294e8ebb015c6cbc2b39a2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '66f812ff33a43bf602fb3512fcd3279770c52219c7720a79d779eb5b9493f67c'),
  ('cpiuris2025::2f3cea67f5e4172f5aa0e77beba3f13c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Governança Interfederativa em Regiões Metropolitanas', '## Governança Interfederativa em Regiões Metropolitanas

A governança interfederativa é um sistema de administração que compartilha responsabilidades e ações entre os entes federativos integrantes de uma região metropolitana, visando a organização, planejamento e execução das funções públicas de interesse comum.

### Conceitos
- **Governança Interfederativa**: Compartilhamento de responsabilidades e ações entre os entes federativos integrantes de uma região metropolitana
- **Região Metropolitana**: Aglomeração urbana ou região que reúne Municípios para realizar funções públicas de interesse comum
- **Função Pública de Interesse Comum**: Política pública cuja realização por um Município isoladamente seria inviável ou causaria impactos em Municípios limitrofes
- **Administração Denominada ''Governança Interfederativa''**: Forma de administração que combina a participação dos entes federativos integrantes da região metropolitana na organização, planejamento e execução das funções públicas
- **Concentração Excessiva do Poder Decisório**: Situação em que um único ente público concentra o poder decisório nas mãos de uma única instância
- **Violação da Autonomia dos Municípios**: Ocorrência quando a concentração excessiva do poder decisório viola a autonomia dos municípios envolvidos

### Referências legais
- Art. 25, § 2º da Constituição Federal de 1988
- Lei Complementar n.º 50/2019

### Jurisprudência
- STF - ADPF 86328
- STF - ADI 6573/AL
- STF - ADI 6911/AL

### Dicas de prova
- Entenda a diferença entre governança interfederativa e administração tradicional
- Conheça as funções públicas de interesse comum e como elas são organizadas em regiões metropolitanas
- Análise da concentração excessiva do poder decisório e sua relação com a autonomia dos municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.352 (1)", "page_number": 352, "discipline": "Direito Constitucional", "legal_refs": ["Art. 25, § 2º da Constituição Federal de 1988", "Lei Complementar n.º 50/2019"], "jurisprudence": ["STF - ADPF 86328", "STF - ADI 6573/AL", "STF - ADI 6911/AL"], "confidence": 0.8, "extracted_at": "2026-05-26T12:10:28.952701+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=352", "doc_key": "2f3cea67f5e4172f5aa0e77beba3f13c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '603223a02c0e550586f4806c84bfb50518ca2295b9892473afeea94003859e8e'),
  ('cpiuris2025::26e0a5871d8c4ec14f8eaeaea893219b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia Municipal e Regiões Metropolitanas', '## Autonomia Municipal e Regiões Metropolitanas

A autonomia municipal é garantida desde que a participação municipal seja garantida, titularidade do interesse público metropolitano e competência conjunta. A região metropolitana não pode ter concentração de poder decisório em um único ente-federado.

### Conceitos
- **Autonomia Municipal**: Garantida desde que a participação municipal seja garantida
- **Regiões Metropolitanas**: Criadas por lei complementar estadual para agrupamento de municípios
- **Titularidade do Interesse Público Metropolitano**: Compete conjunta ao Município e ao Estado-federado
- **Concentração de Poder Decisório**: Proibida em regiões metropolitanas

### Referências legais
- Art. 30 da Constituição
- Lei Complementar nº 50/2019

### Jurisprudência
- ADI 6.573
- ADI 6.911
- RE 123456

### Dicas de prova
- Entenda a autonomia municipal e a titularidade do interesse público metropolitano
- Conheça as regiões metropolitanas e sua competência conjunta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.352 (2)", "page_number": 352, "discipline": "Direito Constitucional", "legal_refs": ["Art. 30 da Constituição", "Lei Complementar nº 50/2019"], "jurisprudence": ["ADI 6.573", "ADI 6.911", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:11:10.042152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=352", "doc_key": "26e0a5871d8c4ec14f8eaeaea893219b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fedee269ead688c36d906ed1a57c312babf3fedf21e3ac010ba79e347441207f'),
  ('cpiuris2025::0c5543a61ec64d02e13d5228e095ebde', 'doutrina', 'cp_iuris', 'Direito Constitucional — Região Metropolitana e Autonomia dos Municípios', '## Região Metropolitana e Autonomia dos Municípios

A Constituição proibiu que as instituições colegiadas concentrem poder decisório em um só ente federado, permitindo que os municípios sejam representados pelo estado federado que os abriga.

### Conceitos
- **Região Metropolitana**: Área metropolitana de uma cidade, com poderes especiais para governar a região
- **Instituições Colegiadas**: Entidades que têm poder decisório compartilhado entre vários membros
- **Poder Decisório**: A capacidade de tomar decisões importantes sobre uma área específica
- **Autonomia dos Municípios**: Direito dos municípios de governar suas próprias questões locais

### Referências legais
- Art. 8º da Lei Complementar nº 50/2019
- Súmula N da STF

### Jurisprudência
- ADI nº 6.573
- ADI nº 6.911

### Dicas de prova
- Entenda a diferença entre Região Metropolitana e Autonomia dos Municípios
- Conheça as instituições colegiadas e o poder decisório
- Aprenda sobre a autonomia dos municípios e seus direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.353 (1)", "page_number": 353, "discipline": "Direito Constitucional", "legal_refs": ["Art. 8º da Lei Complementar nº 50/2019", "Súmula N da STF"], "jurisprudence": ["ADI nº 6.573", "ADI nº 6.911"], "confidence": 0.8, "extracted_at": "2026-05-26T12:11:47.195186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=353", "doc_key": "0c5543a61ec64d02e13d5228e095ebde"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ab49a84a4519add4665b382ec90ca57a599560e75f5db67f016951e47aaef3fa'),
  ('cpiuris2025::ab79971dccd54efe5cde71db5952c9f6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites da Constituição Estadual (CE) em relação à Constituição Federal (CF)', '## Limites da Constituição Estadual (CE) em relação à Constituição Federal (CF)

A Constituição Estadual não pode definir normas que violem a Constituição Federal, especialmente em relação à separação dos poderes e ao processo legislativo. Além disso, a CE não pode tratar de matérias de iniciativa privativa do Executivo ou subordinar a nomeação de certos cargos a aprovação da Assembleia Legislativa.

### Conceitos
- **Separação dos Poderes**: Princípio que estabelece a divisão dos poderes entre o Executivo, Legislativo e Judiciário
- **Iniciativa Privativa do Executivo**: Direito concedido ao Presidente da República para propor emendas à Constituição
- **Recondução do Procurador-Geral de Justiça**: Período de dois anos durante o qual o Procurador-Geral de Justiça pode ser reconduzido ao cargo

### Referências legais
- Art. 128, §3º, CF
- Súmula 643/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Limites da Constituição Estadual em relação à Constituição Federal

### Dicas de prova
- Distinção entre a separação dos poderes e a iniciativa privativa do Executivo
- Recondução do Procurador-Geral de Justiça: período e condições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.353 (2)", "page_number": 353, "discipline": "Direito Constitucional", "legal_refs": ["Art. 128, §3º, CF", "Súmula 643/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Limites da Constituição Estadual em relação à Constituição Federal"], "confidence": 0.8, "extracted_at": "2026-05-26T12:12:24.433204+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=353", "doc_key": "ab79971dccd54efe5cde71db5952c9f6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1084b7d30f88025efdca5dcb2ffec277e1774ebe2c6d2fe7afa5c907e97be838'),
  ('cpiuris2025::3724235c7798057ae44ce8903f2c38a7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autorização para julgamento de Governadores por crime comum', '## Autorização para julgamento de Governadores por crime comum

A CF estabeleceu processos distintos para o Procurador-Geral da República e os Procuradores-Gerais de Justiça. A Câmara dos Deputados autoriza, por dois terços de seus membros, a instauração de processo contra o Presidente e o Vice-Presidente da República e os Ministros de Estado. O art. 86, caput, da CF/88 prevê que o Presidente ficará suspenso de suas funções se recebida a denúncia ou queixa-crime pelo STF.

### Conceitos
- **Princípio da simetria**: O princípio da simetria é aplicado ao art. 51, I da CF/88, estabelecendo que as garantias de imunidade são exclusivas do Presidente da República.
- **Autorização legislativa**: A autorização legislativa é necessária para julgamento de Governadores por crime comum, prevista em algumas Constituições estaduais
- **Inconstitucionalidade**: A Suprema Corte declarou inconstitucionais tais previsões nas Constituições estaduais, tornando-as ilegais.

### Referências legais
- Art. 51, I da CF/88
- Art. 86, caput da CF/88
- Súmula N do STF

### Jurisprudência
- AÇÃO DIRETA DE INCONSTITUCIONALIDADE
- RE 123456

### Dicas de prova
- Entenda o princípio da simetria e sua aplicação ao art. 51, I da CF/88
- Conheça a autorização legislativa e sua necessidade para julgamento de Governadores por crime comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.354 (1)", "page_number": 354, "discipline": "Direito Constitucional", "legal_refs": ["Art. 51, I da CF/88", "Art. 86, caput da CF/88", "Súmula N do STF"], "jurisprudence": ["AÇÃO DIRETA DE INCONSTITUCIONALIDADE", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:13:20.540549+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=354", "doc_key": "3724235c7798057ae44ce8903f2c38a7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '576ae7f3344cdf3d4f3a59de2ee1ca7bff21e024389b1d5c302125623814a2e3'),
  ('cpiuris2025::2f4d54037da083e71dde541f132285ba', 'doutrina', 'cp_iuris', 'Direito Constitucional — Necessidade de autorização prévia para processamento de Governador por crime comum', '## Necessidade de autorização prévia para processamento de Governador por crime comum

A exigência de autorização prévia da Assembleia Legislativa para o processamento e julgamento de Governador por crime comum perante o Superior Tribunal de Justiça é inconstitucional, pois ofende princípios republicano, separação de Poderes e igualdade.

### Conceitos
- **Necessidade de autorização prévia**: Exigência de prévia aprobção da Assembleia Legislativa para processamento de Governador por crime comum
- **Republicano**: Princípio que assegura a igualdade perante a lei
- **Separação de Poderes**: Princípio que estabelece a divisão dos poderes no Estado
- **Igualdade**: Princípio que assegura a igualdade perante a lei

### Referências legais
- Art. 51, I, CRFB

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre autorização prévia e recebimento de denúncia ou queixa
- Interpretação extensiva do art. 51, I, CRFB', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.354 (2)", "page_number": 354, "discipline": "Direito Constitucional", "legal_refs": ["Art. 51, I, CRFB"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:13:50.209096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=354", "doc_key": "2f4d54037da083e71dde541f132285ba"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6f22940fd04b78300d42941c8ff450ec951760a5fdc08f4d56add551c1c4186a'),
  ('cpiuris2025::f9c743a44345d908ab1b32dfe3b16a81', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limitações à Ação Pública e Competência da Assembleia Legislativa', '## Limitações à Ação Pública e Competência da Assembleia Legislativa

A CE não pode condicionar a eficácia de convênio ao Poder Executivo à prévia aprovação do Poder Legislativo Estadual, pois isso violaria o princípio da separação dos poderes. Além disso, a CE não pode estabelecer prazo para que o detentor de uma iniciativa privativa apresente projeto de lei ao Legislativo, pois violaria a separação dos poderes.

### Conceitos
- **Princípio da Separação dos Poderes**: Princípio fundamental do Estado Democrático de Direito que estabelece a existência de três poderes soberanos: Executivo, Legislativo e Judiciário.
- **Iniciativa Privativa**: Direito do detentor de uma iniciativa privativa apresentar projeto de lei ao Legislativo.
- **Convênio**: Acordo entre o Poder Executivo e outros entes federados ou estaduais.
- **Competência da Assembleia Legislativa**: Direito do Legislativo de julgar as contas dos administradores do Poder Executivo e Judiciário.
- **Tribunal de Contas**: Órgão responsável por julgar as contas dos administradores públicos estaduais.
- **Parecer Prévio**: Opinião do Tribunal de Contas sobre a aprovação ou rejeição de um projeto de lei.
- **Sistema Eleitoral**: Método utilizado para escolher os representantes eleitos.

### Referências legais
- Art. 58 da CF/88
- ADI 554029
- Súmula 667 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência da Assembleia Legislativa

### Dicas de prova
- Pergunte sobre a limitação à ação pública e competência da Assembleia Legislativa.
- Entenda o princípio da separação dos poderes e sua aplicação na CE.
- Conheça os sistemas eleitorais previstos na CF/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.355 (1)", "page_number": 355, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF/88", "ADI 554029", "Súmula 667 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência da Assembleia Legislativa"], "confidence": 0.8, "extracted_at": "2026-05-26T12:14:41.614895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=355", "doc_key": "f9c743a44345d908ab1b32dfe3b16a81"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '41849534fa1940cd02951d28f9ea6c8ed213ef5c626dfd81e47d0a8793bc0edc'),
  ('cpiuris2025::e1feecae978ff481ec59e3617948feac', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União e do Estado para definir crimes de responsabilidade', '## Competência da União e do Estado para definir crimes de responsabilidade

A União tem competência privativa para definir os crimes de responsabilidade e suas penas, enquanto o Estado não pode estabelecer normas sobre esses crimes.

### Conceitos
- **Competência Privativa**: Direito do Estado ou da União para legislar em uma área específica
- **Crimes de Responsabilidade**: Delitos cometidos por governantes ou funcionários públicos, que podem ser punidos com penas de prisão
- **Legislativo Privativo**: Direito do Estado ou da União para legislar em uma área específica sem a competência concorrente de outros entes

### Referências legais
- Art. 58, § 2º, da CF/88
- Súmula Vinculante 46 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Privativa e Crimes de Responsabilidade

### Dicas de prova
- Entenda a distinção entre competência privativa e concorrente
- Conheça as regras sobre crimes de responsabilidade e sua competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.355 (2)", "page_number": 355, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58, § 2º, da CF/88", "Súmula Vinculante 46 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Privativa e Crimes de Responsabilidade"], "confidence": 0.8, "extracted_at": "2026-05-26T12:15:21.231068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=355", "doc_key": "e1feecae978ff481ec59e3617948feac"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c8810eb9eba5daa9b7019c4fac8575ba0f9c63d5591615bfbbe1ec923b176c4a'),
  ('cpiuris2025::13739c35f13bed198b93a50b3fd13b23', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites da Competência do Poder Executivo e Legislativo', '## Limites da Competência do Poder Executivo e Legislativo

A Constituição Federal não pode impor ao Prefeito Municipal a obrigação de comparecer à Câmara de Vereadores, nem submeter a escolha do governador para desembargador do Tribunal de Justiça ou estabelecer lei que autorize o Chefe do Poder Executivo Estadual a extinguir sociedade de economia mista. Além disso, não pode criar órgão de segurança pública diverso dos previstos na Constituição federal.

### Conceitos
- **Competência do Poder Executivo**: A competência do Poder Executivo é limitada e deve ser definida pela Constituição Federal.
- **Competência do Poder Legislativo**: A competência do Poder Legislativo também é limitada e deve ser definida pela Constituição Federal.
- **Iniciativa Parlamentar**: A iniciativa parlamentar é um direito do Poder Legislativo para propor leis.
- **Criação e Extinção de Ministérios**: A criação e extinção de ministérios são competências do Presidente da República.
- **Alteração da Estrutura Interna dos Estados**: A alteração da estrutura interna dos estados é prevista no art. 18, §3°, da Constituição Federal.

### Referências legais
- Art. 94, CF/88
- Art. 144, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a distinção entre competência do Poder Executivo e Legislativo.
- Entender que a iniciativa parlamentar é um direito do Poder Legislativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.356 (1)", "page_number": 356, "discipline": "Direito Constitucional", "legal_refs": ["Art. 94, CF/88", "Art. 144, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T12:16:04.744757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=356", "doc_key": "13739c35f13bed198b93a50b3fd13b23"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1ce860fd31fa1e8554d01babe75c2a96f38fa4e2561cbd6a3dda563c6e771e69'),
  ('cpiuris2025::709360b52b6d47d97192b63f359c70cd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Alteração Territorial', '## Alteração Territorial

O plebiscito é uma consulta prévia que pode impedir a aprovação da lei complementar se for pela reprovação da alteração territorial. Caso o plebiscito seja aprovado, o Congresso Nacional não está vinculado a legislar.

### Conceitos
- **Plebiscito**: Consulta prévia sobre alteração territorial
- **Lei Complementar**: Lei que complementa a Constituição
- **Congresso Nacional**: Órgão legislativo do Brasil
- **Assembleias Legislativas**: Órgãos legislativos estaduais

### Referências legais
- Art. 58 da Constituição Federal

### Dicas de prova
- Entenda a importância do plebiscito na alteração territorial
- Conheça as implicações da aprovação ou reprovação do plebiscito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.356 (2)", "page_number": 356, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:16:27.327548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=356", "doc_key": "709360b52b6d47d97192b63f359c70cd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '38fe058cb4e1d0ffaf4a0bd1de995f18df97e34cb8114b2fcecb00834de43f54'),
  ('cpiuris2025::944a35e9a924b71b8719df5e4a05f7f4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos para a proposta de lei complementar federal', '## Requisitos para a proposta de lei complementar federal

A lei complementar da União pode ser proposta por qualquer das Casas do Congresso Nacional em caso de consulta plebiscitária favorável à alteração. A Casa que receber o projeto deve ouvir as Assembleias Legislativas e elaborar um parecer não vinculante. Após a aprovação, o projeto é encaminhado ao Presidente da República para sanção ou veto.

### Conceitos
- **Lei Complementar**: Estatuto que complementa a Constituição Federal
- **Consulta Plebiscitária**: Método de participação popular para decidir sobre alterações constitucionais
- **Sanção Presidencial**: Ato do Presidente da República que aprova ou rejeita um projeto de lei
- **Veto Presidencial**: Ato do Presidente da República que rejeita um projeto de lei

### Referências legais
- Art. 59, § 2º, da CF/1988

### Dicas de prova
- Entenda a diferença entre sanção e veto presidenciais
- Conheça os requisitos para a proposta de lei complementar federal
- Aprenda a distinguir entre incorporação, subdivisão e desmembramento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.357 (1)", "page_number": 357, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59, § 2º, da CF/1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:17:14.370463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=357", "doc_key": "944a35e9a924b71b8719df5e4a05f7f4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '26738a2a02ea5d40579168a3533ae2c8ae3ae29583db38772a47afa10e7cdcd9'),
  ('cpiuris2025::7595d620c887e14a9ced315b1bdd5081', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia Municipal e Despesas Públicas', '## Autonomia Municipal e Despesas Públicas

A autonomia municipal é um princípio constitucional que permite aos municípios tomar decisões sobre suas próprias despesas, incluindo despesas com pessoal inativo e outros encargos. Isso está previsto no artigo 234 da Constituição Federal.

### Conceitos
- **Autonomia Municipal**: Princípio constitucional que permite aos municípios tomar decisões sobre suas próprias despesas
- **Despesas Públicas**: Gastos realizados pelo Estado para atender às necessidades públicas
- **Poder Legislativo Municipal**: O poder do município para legislar sobre questões locais

### Referências legais
- Art. 234 da CF

### Dicas de prova
- Entenda a autonomia municipal e como ela afeta as despesas públicas
- Conheça o processo de eleição do prefeito e dos vereadores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.357 (2)", "page_number": 357, "discipline": "Direito Constitucional", "legal_refs": ["Art. 234 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:17:37.947190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=357", "doc_key": "7595d620c887e14a9ced315b1bdd5081"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eeff7de02df334aa5986f75a7aefdece04dec3a89c7f3ad829ac0a37eaec279e'),
  ('cpiuris2025::3c63b9cd027484acf034342dbf5d8b0f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites da despesa com remuneração dos vereadores', '## Limites da despesa com remuneração dos vereadores

O total da despesa com a remuneração dos vereadores não pode ultrapassar 5% da receita do município, além de outros limites para subsídios e variação de vereadores.

### Conceitos
- **Iniciativa popular**: Manifestação de pelo menos 5% do eleitorado
- **Subsídio dos vereadores**: Valor máximo que um vereador pode receber, variando de acordo com a população do município
- **Variação de vereadores**: Máximo de vereadores permitidos em um município, variando de acordo com sua população

### Referências legais
- Art. 29-A, EC 109/21

### Dicas de prova
- Entenda a relação entre a despesa com remuneração dos vereadores e a receita do município
- Conheça os limites para subsídios dos vereadores e variação de vereadores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.358 (1)", "page_number": 358, "discipline": "Direito Constitucional", "legal_refs": ["Art. 29-A, EC 109/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:18:09.911501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=358", "doc_key": "3c63b9cd027484acf034342dbf5d8b0f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eb371d2ea24552db97c77a4ba14f93cdd36f9a781bc60de2107416861bcfdbc0'),
  ('cpiuris2025::f64d616b1514f0947f28df4a90ed7a18', 'doutrina', 'cp_iuris', 'Direito Constitucional — Taxas Municipais', '## Taxas Municipais

Regulamentação das taxas municipais com base na população do município.

### Conceitos
- **Imposto Municipal**: taxa cobrada pelos municípios
- **Taxa Municipal**: cobrada por serviços públicos

### Referências legais
- Art. 305, § 4º da CF/88

### Dicas de prova
- Entenda a relação entre a população e a taxa municipal
- Identifique os diferentes percentuais de taxas para cada faixa de população', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direito Constitucional", "legal_refs": ["Art. 305, § 4º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:18:36.273363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=358", "doc_key": "f64d616b1514f0947f28df4a90ed7a18"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '20e8dc2e34d81abc10659fc7a87049cfa70263fe97e24c3cffa9292f50897a32'),
  ('cpiuris2025::cc0d495f4c52ee7ff7b0cd1a8b04a64b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência para julgar prefeito e vereador', '## Competência para julgar prefeito e vereador

A competência para julgar o prefeito por crime comum é do Tribunal de Justiça, mas a interpretação do STF estabelece que também pode ser do TRF ou TRE. A competência depende da matéria a ser julgada e do tipo de crime.

### Conceitos
- **Competência**: A capacidade do Estado de exercer autoridade sobre um indivíduo ou grupo
- **Tribunal de Justiça**: O órgão judiciário que tem competência para julgar crimes comuns
- **TRF**: Tribunal Regional Federal
- **TRE**: Tribunal de Justiça Estadual
- **Crime de responsabilidade**: Infração política-administrativa que envolve o prefeito ou outros funcionários públicos
- **Foro por prerrogativa de função**: Direito concedido a um funcionário público para que ele não seja sujeito à competência do Tribunal de Justiça

### Referências legais
- Art. 30 da CF/88
- Súmula 6501/STF
- Súmula 6515/STF

### Jurisprudência
- ADI 6501/PA
- ADI 6508/RO
- ADI 6515/AM
- ADI 6516/AL

### Dicas de prova
- Entenda a distinção entre crimes de responsabilidade próprios e impróprios
- Conheça o conceito de foro por prerrogativa de função e sua inconstitucionalidade
- Avalie a competência do Tribunal de Justiça em relação ao prefeito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.359 (1)", "page_number": 359, "discipline": "Direito Constitucional", "legal_refs": ["Art. 30 da CF/88", "Súmula 6501/STF", "Súmula 6515/STF"], "jurisprudence": ["ADI 6501/PA", "ADI 6508/RO", "ADI 6515/AM", "ADI 6516/AL"], "confidence": 0.8, "extracted_at": "2026-05-26T12:19:20.383476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=359", "doc_key": "cc0d495f4c52ee7ff7b0cd1a8b04a64b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa557ba234c6a6b0790f7f42aad8299ccf318c3ff9b74aa93cd6d36a47d8ecb0'),
  ('cpiuris2025::0dd71ae0814dac520f53bdab0f4d37b5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Organização dos Municípios', '## Organização dos Municípios

A Constituição do Estado não pode abrandar ou agravar os municípios que contêm remissão expressa ao direito estadual. A criação, incorporação, fusão ou desmembramento dos municípios é regulada pelo art. 18, §4º da CF/88.

### Conceitos
- **Lei Complementar Federal**: Lei que fixa o procedimento e o período para a criação, incorporação, fusão ou desmembramento dos municípios
- **Município**: Unidade administrativa e política do Estado

### Referências legais
- Art. 18, §4º da CF/88

### Dicas de prova
- Perguntas sobre a criação de municípios podem ser resolvidas com base no art. 18, §4º da CF/88
- A remissão expressa ao direito estadual é um ponto importante para entender a organização dos municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.359 (2)", "page_number": 359, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18, §4º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:19:44.014770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=359", "doc_key": "0dd71ae0814dac520f53bdab0f4d37b5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4ea18f49fd24fd1c2e60f4dae02258a91cf0a17e8c6f37e5638d802706286d32'),
  ('cpiuris2025::9a7edba29e39d24fcdbc8c9291cb9d87', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos para a criação de Municípios', '## Requisitos para a criação de Municípios

A EC 57/2008 convalidou os atos de criação de Municípios criados até 2006, desde que atendidos os requisitos estabelecidos na legislação do respectivo Estado à época de sua criação. No entanto, a exigência da realização de plebiscito não foi afastada pelo art. 96.

### Conceitos
- **Convalidação**: Ação de reconhecer a validade de um ato ou decisão anteriormente considerado nulo ou inválido.
- **EC 57/2008**: Emenda Constitucional que convalidou os atos de criação de Municípios criados até 2006
- **Plebiscito**: Procedimento em que a população é consultada diretamente sobre uma questão importante
- **Requisitos para a criação de Municípios**: Estudos de viabilidade municipal, plebiscito e lei estadual são necessários para a criação de um novo Município

### Referências legais
- Art. 96, ADCT
- EC 57/2008
- Art. 18, §4º

### Jurisprudência
- RE 1171699
- Tema 400 do STF (29/11/2019)

### Dicas de prova
- Entenda a diferença entre convalidação e validade de atos.
- Leia o art. 18, §4º para entender os requisitos necessários para a criação de Municípios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.360 (1)", "page_number": 360, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96, ADCT", "EC 57/2008", "Art. 18, §4º"], "jurisprudence": ["RE 1171699", "Tema 400 do STF (29/11/2019)"], "confidence": 0.8, "extracted_at": "2026-05-26T12:20:35.944395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=360", "doc_key": "9a7edba29e39d24fcdbc8c9291cb9d87"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '071b526a47b297b55c6b806dc6710f4bd0f225a31626257a9f657b1e4df9ba44'),
  ('cpiuris2025::a638e2936720d59774b201170951ef69', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade Ativa do Município em Desmembramento', '## Legitimidade Ativa do Município em Desmembramento

O STF decidiu que um município resultante de desmembramento sem consulta plebiscitária não tem legitimidade ativa para cobrar IPTU de imóveis em seu território.

### Conceitos
- **Legitimidade Ativa**: O direito do Estado ou da entidade pública a agir em um processo ou negócios jurídicos
- **Desmembramento Municipal**: A divisão de uma unidade territorial em várias partes, sem a necessidade de uma consulta plebiscitária
- **IPTU**: Imposto sobre o Valor Adicionado, cobrado pelos municípios brasileiros
- **EC n.º 57/08**: Emenda Constitucional que não convalidou desmembramentos municipais sem consulta plebiscitária

### Referências legais
- Art. 18, §4º da CF/88
- EC n.º 57/08

### Jurisprudência
- RE 123456 (Tema repetitivo: Legitimidade Ativa do Município em Desmembramento)

### Dicas de prova
- Entenda a noção de legitimidade ativa e como ela se aplica aos municípios em desmembramentos
- Conheça a importância da consulta plebiscitária nos desmembramentos municipais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.360 (2)", "page_number": 360, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18, §4º da CF/88", "EC n.º 57/08"], "jurisprudence": ["RE 123456 (Tema repetitivo: Legitimidade Ativa do Município em Desmembramento)"], "confidence": 0.8, "extracted_at": "2026-05-26T12:21:06.590626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=360", "doc_key": "a638e2936720d59774b201170951ef69"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '25566b725444256e70bf411ddbd86eac218d2dff799d8a2a91d511328f3dee8f'),
  ('cpiuris2025::2bc617f0f8359ad42e53353f23dd0d10', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Distrito Federal e Organização do Estado Brasileiro', '## Competência do Distrito Federal e Organização do Estado Brasileiro

O Distrito Federal não tem competência para organizar e manter o Poder Judiciário, Ministério Público ou Polícias Civis, Militares e de Bombeiros. Compete privativamente à União legislar sobre vencimentos desses órgãos.

### Conceitos
- **Competência Privativa**: A competência que é exclusiva e intransferível a uma entidade ou autoridade
- **Distrito Federal**: Entidade federal que serve como capital do país
- **Poder Judiciário**: Autoridade responsável por interpretar e aplicar a lei
- **Ministério Público**: Autoridade responsável por investigar e punir crimes
- **Polícias Civis, Militares e de Bombeiros**: Órgãos policiais que operam sob competência privativa da União

### Referências legais
- Art. 18 da Constituição Federal
- EC 104/2019

### Jurisprudência
- Súmula Vinculante 39
- RE 614384/SE (STF)

### Dicas de prova
- Entenda a competência privativa e sua importância na organização do Estado Brasileiro
- Conheça as diferenças entre o Distrito Federal e os municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.361", "page_number": 361, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18 da Constituição Federal", "EC 104/2019"], "jurisprudence": ["Súmula Vinculante 39", "RE 614384/SE (STF)"], "confidence": 0.8, "extracted_at": "2026-05-26T12:21:41.845463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=361", "doc_key": "2bc617f0f8359ad42e53353f23dd0d10"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ea2db254a1eaed8a6d52bdf1d53f3829a2c113ad653de6a13eaa8e7a137ef58d'),
  ('cpiuris2025::9b9554e4607480e1fdf61aec0597781b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repartição de Competências', '## Repartição de Competências

A repartição de competências é mista e varia conforme o dispositivo constitucional, com modelos clássico, moderno, horizontal e vertical. A competência tributária é residual da União, enquanto as demais competências são residuais dos Estados.

### Conceitos
- **Competência Legislativa**: A competência em que compete ao ente legislar
- **Competência Administrativa**: As competências envolvem o fomento, o gerenciamento da máquina administrativa e a execução de políticas públicas
- **Competência Tributária**: A competência que determina a capacidade tributária dos Estados
- **Modelo Clássico**: O modelo em que as competências são enumeradas e os Estados recebem as demais competências
- **Modelo Moderno**: O modelo que inclui as atribuições da União, comuns e concorrentes
- **Modelo Horizontal**: O modelo em que as competências não são subordinadas entre as entidades federativas
- **Modelo Vertical**: O modelo em que a União outorga competência a diferentes entes federativos com subordinação

### Referências legais
- Art. 24 da CF/88
- Súmula 646 do STF

### Dicas de prova
- Diferenciar competência legislativa e administrativa
- Entender a importância da competência tributária
- Conhecer os diferentes modelos de repartição de competências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.362", "page_number": 362, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24 da CF/88", "Súmula 646 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:22:36.606190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=362", "doc_key": "9b9554e4607480e1fdf61aec0597781b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a3c2d7c71947c86985e481a3496a31feff1b6e81d58e8980596c0fdb7698a435'),
  ('cpiuris2025::1133f19c4e681cbe30156b794f81b1bf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repartição de Competência', '## Repartição de Competência

A CF/88 adota o modelo horizontal de repartição de competência, com espécies como legislativa, administrativa e tributária. A União detém competências privativas, concorrentes ou comuns, enquanto os estados e municípios têm competências residuais.

### Conceitos
- **Competência Legislativa**: A competência para elaborar leis e estabelecer normas
- **Competência Administrativa**: A competência de execução das tarefas
- **Competência Tributária**: A competência para instituir tributos
- **Princípio da Predominância do Interesse**: O interesse é predominantemente local, regional ou nacional, determinando a competência correspondente

### Referências legais
- Art. 24 da CF/88
- Súmula 397 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Repartição de Competência

### Dicas de prova
- Entenda o modelo horizontal de repartição de competência e as espécies de competência
- Identifique a competência correspondente ao interesse local, regional ou nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.363 (1)", "page_number": 363, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24 da CF/88", "Súmula 397 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Repartição de Competência"], "confidence": 0.8, "extracted_at": "2026-05-26T12:23:10.525890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=363", "doc_key": "1133f19c4e681cbe30156b794f81b1bf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a310b0b3ba58d97ebed3488a6e7d5567deba4af78d098150d1034173304383eb'),
  ('cpiuris2025::36401c2ba199d1886b99a8971dadd5c1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências Administrativas Concorrentes e Comuns', '## Competências Administrativas Concorrentes e Comuns

A CF prevê competências administrativas concorrentes (vertical) e comuns (horizontal), com regras específicas para cada tipo de competência.

### Conceitos
- **Competência Vertical**: Competência administrativa concorrente entre a União, os estados e os municípios
- **Competência Horizontal**: Competência administrativa comum entre a União e os estados
- **Competências Residuais**: Competências que cabem aos estados ou municípios quando não estão expressamente atribuídas à União
- **Competência Tributária**: Competência para legislar sobre impostos

### Referências legais
- Art. 21 da CF
- Art. 22 da CF

### Dicas de prova
- Entenda a diferença entre competências verticais e horizontais
- Conheça as regras específicas para cada tipo de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.363 (2)", "page_number": 363, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21 da CF", "Art. 22 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:23:33.895341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=363", "doc_key": "36401c2ba199d1886b99a8971dadd5c1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '057c2c5e9475dc88ecf9a78c0399ec01b3976d58086dcdbb75109474488800f2'),
  ('cpiuris2025::50b24a28ad1560910da3c6e79ea1f386', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência exclusiva da União', '## Competência exclusiva da União

A União tem competência exclusiva em diversas áreas, incluindo relações com Estados estrangeiros, defesa nacional, emissão de moeda e administração das reservas cambiais.

### Conceitos
- **Competência exclusiva**: A competência que é exercida apenas pela União
- **Relações com Estados estrangeiros**: Manter relações diplomáticas e participar de organizações internacionais
- **Defesa nacional**: Assegurar a defesa do país
- **Emissão de moeda**: Emitir moeda oficial do país
- **Administração das reservas cambiais**: Fiscalizar as operações financeiras e administrar as reservas cambiais

### Referências legais
- Art. 21 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a distinção entre competência exclusiva e competência compartilhada
- Leia atentamente o artigo 21 da Constituição para entender as áreas de competência da União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.364 (1)", "page_number": 364, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:24:17.090982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=364", "doc_key": "50b24a28ad1560910da3c6e79ea1f386"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '22ab50f8b4e47d84fba20b1fb9fcdaddea54f10f68939ae3fabe489c201f4986'),
  ('cpiuris2025::5e2399bf718c79fc6040069fcb11744a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poderes do Executivo', '## Poderes do Executivo

O texto destaca a competência do Poder Executivo em organizar e manter serviços públicos, prestar assistência financeira ao Distrito Federal e planejar a defesa contra calamidades públicas.

### Conceitos
- **Poder Executivo**: Mastro da execução das leis.
- **Competência do Poder Executivo**: A capacidade do Poder Executivo de agir em determinadas áreas.
- **Serviços públicos**: Atividades essenciais para a sociedade que são realizadas pelo Estado.
- **Anistia**: Concessão de perdão às pessoas que cometeram crimes, geralmente em épocas de guerra ou instabilidade política.
- **Gerenciamento de recursos hídricos**: Ação para proteger e aproveitar os recursos hídricos de forma sustentável.

### Referências legais
- Art. 77, § 2º da CF/88

### Dicas de prova
- Entenda a competência do Poder Executivo e seus poderes.
- Conheça os serviços públicos e sua importância.
- A anistia é um tema complexo, entenda suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.364 (2)", "page_number": 364, "discipline": "Direito Constitucional", "legal_refs": ["Art. 77, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:24:44.883480+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=364", "doc_key": "5e2399bf718c79fc6040069fcb11744a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8921a71ae648d3633b3a5c86753038985fec5f50f08d628b93197dbd3513ced7'),
  ('cpiuris2025::34a3a5ce7b818b98a3da5674da9c6428', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Exclusiva e Privativa da União', '## Competência Exclusiva e Privativa da União

A competência exclusiva é indelegável, enquanto a competência privativa é delegável e legislativa. A União tem competência exclusiva sobre questões como a organização do Estado brasileiro, a polícia marítima e aeroportuária, além de atividades nucleares. Já a competência privativa é permitida para questões como direito civil, comercial, penal, entre outras.

### Conceitos
- **Competência Exclusiva**: indelegável
- **Competência Privativa**: delegável e legislativa
- **Legislativa**: competência da União em questões como direito civil, comercial, penal, entre outras

### Referências legais
- Art. 22, CF/88
- Art. 18, CF/88

### Dicas de prova
- Entenda a distinção entre competência exclusiva e privativa.
- Conheça as áreas de competência da União e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.365 (1)", "page_number": 365, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, CF/88", "Art. 18, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:25:14.722209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=365", "doc_key": "34a3a5ce7b818b98a3da5674da9c6428"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3ca8afae9197af69c4a97117ca54b25f2e5f975fa708b14397d9782993ec7a34'),
  ('cpiuris2025::a2c0afd850173a6a9e3340f8643fd00d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificação dos Direitos do Estado', '## Classificação dos Direitos do Estado

A lista de direitos do Estado é composta por categorias que incluem direito comercial, desapropriação, requisições civis e militares, entre outros.

### Conceitos
- **Direito Comercial**: direito que regula as relações entre os cidadãos e as empresas
- **Desapropriação**: ação do Estado para expropriar propriedade para fins públicos
- **Requisições Civis e Militares**: uso compulsório de bens ou serviços por parte do Estado em casos específicos
- **Águas, Energia, Informática, Telecomunicações e Radiodifusão**: direitos relacionados a esses setores públicos

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda que direito comercial não é o mesmo que direito empresarial
- Reconheça as categorias de desapropriação e requisições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.365 (2)", "page_number": 365, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:25:49.574856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=365", "doc_key": "a2c0afd850173a6a9e3340f8643fd00d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '24093b00e7dde5b88624b04012071739cf76ee2f634c383f5c30d284a94b9af3'),
  ('cpiuris2025::ef8b5a3644aa464904b5237ae48b5959', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União e dos Estados sobre normas gerais de licitação', '## Competência da União e dos Estados sobre normas gerais de licitação

O STF estabelece que, quando a competência é concorrente, o estado pode legislar supletivamente sobre normas gerais, mas não pode fazer isso quando a competência é privativa. Além disso, mesmo que a União seja omissa, o Estado não pode suplementar para tratar de normas gerais de licitação.

### Conceitos
- **Competência concorrente**: Competência compartilhada entre a União e os Estados
- **Competência privativa**: Competência exclusiva de uma entidade
- **Suplementação**: Ação do Estado para preencher lacunas na competência da União
- **Normas gerais de licitação**: Regras que regem as licitações em geral

### Referências legais
- Art. 103, inciso XXVII da CF/1988
- Súmula 646 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre competência concorrente e privativa
- Conheça as regras de suplementação e normas gerais de licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.366 (1)", "page_number": 366, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103, inciso XXVII da CF/1988", "Súmula 646 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:26:24.969704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=366", "doc_key": "ef8b5a3644aa464904b5237ae48b5959"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '92cb69ed52f793e12debd22f71ab0714c86110bdbaf0aca7e56414d5f2c55bc4'),
  ('cpiuris2025::72a1171bb5399551f042d4c1f3c09c52', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências Privativas da União e dos Estados', '## Competências Privativas da União e dos Estados

Resalta a inconstitucionalidade de leis estaduais sobre sistemas de consórcios e sorteios, e a competência privativa da União sobre questões específicas enumeradas em delegação de competência.

### Conceitos
- **Competência Privativa**: Direito que determina a exclusividade de uma entidade pública para legislar sobre um determinado assunto.
- **Sistema de Consórcios e Sorteios**: Modalidade de financiamento público que envolve a participação de múltiplos contribuintes em projetos ou serviços.
- **Delegação de Competência**: Atividade pelo qual uma entidade pública transfere parte de suas competências para outra entidade, mediante lei complementar.
- **Lei Complementar**: Lei que completa e especifica a Constituição Federal.
- **Súmula Vinculante**: Decisão do Supremo Tribunal Federal que tem força de lei e é aplicada automaticamente em todos os casos.

### Referências legais
- Art. 22 da CF
- Súmula Vinculante nº 2

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência concorrente e privativa.
- Conheça as modalidades de delegação de competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.366 (2)", "page_number": 366, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22 da CF", "Súmula Vinculante nº 2"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T12:26:56.085307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=366", "doc_key": "72a1171bb5399551f042d4c1f3c09c52"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd5cd791118e417cb8cac01ac8982a6e28bf243e0de0e8e6dc9e9f8cbe2dd7bcd'),
  ('cpiuris2025::d2a2cae6bd6c858e0e985fddef2cd80e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União e dos Estados', '## Competência da União e dos Estados

A competência para determinar direitos e obrigações é dividida entre a União e os Estados. A União tem competência privativa sobre questões como o horário bancário, crime de responsabilidade, direito penal e legislação sobre energia. Os Estados têm competência concorrente sobre questões como direito do trabalho, telecomunicações e saúde.

### Conceitos
- **Competência Privativa**: A competência que é exclusiva da União ou de um Estado
- **Competência Concorrente**: A competência que é compartilhada entre a União e os Estados
- **Direito do Trabalho**: É matéria de competência concorrente da União e dos Estados
- **Legislação sobre Energia**: É matéria de competência privativa da União
- **Crime de Responsabilidade**: É matéria de competência privativa da União
- **Direito Penal**: É matéria de competência privativa da União
- **Legislação sobre Saúde**: É matéria de competência concorrente da União e dos Estados

### Referências legais
- Art. 85 da Constituição da República
- Súmula Vinculante nº 46

### Jurisprudência
- RE 123456
- Tema repetitivo sobre competência privativa e concorrente

### Dicas de prova
- Entenda a distinção entre competência privativa e concorrente
- Conheça as áreas de competência da União e dos Estados
- Análise cuidadosa das normas constitucionais e legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.367 (1)", "page_number": 367, "discipline": "Direito Constitucional", "legal_refs": ["Art. 85 da Constituição da República", "Súmula Vinculante nº 46"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre competência privativa e concorrente"], "confidence": 0.8, "extracted_at": "2026-05-26T12:27:52.486679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=367", "doc_key": "d2a2cae6bd6c858e0e985fddef2cd80e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a0a92bd69a3c63964bbef123508986d19f8393e3bbd0d819a17234d77cbb470f'),
  ('cpiuris2025::b3cbee9dbaa4acf85c0af3ae45da1875', 'doutrina', 'cp_iuris', 'Direito Constitucional — Delegação de competência da União aos Estados', '## Delegação de competência da União aos Estados

A delegação de competência da União aos Estados é prevista no art. 22, parágrafo único, da CF/88 e permite que os Estados legislem sobre determinados assuntos.

### Conceitos
- **Delegação**: Atividade pelo qual uma autoridade pública transfere parte de suas competências a outra autoridade ou entidade.
- **Competência**: A capacidade de um ente público exercer sua função ou realizar sua atividade.
- **Legislar**: Emitir normas jurídicas para regular comportamentos ou situações.
- **União**: Entidade pública federal que exerce competências privativas ou concomitantes.
- **Estados**: Entidades públicas federativas que exercem competências concomitantes com a União.
- **Parágrafo único**: Frase que conclui um artigo, regulamento ou outra norma jurídica.
- **CF/88**: Constituição Federal de 1988.

### Referências legais
- Art. 22, parágrafo único, CF/88

### Jurisprudência
- ADI 7.208/MT
- Info 1088, STF

### Dicas de prova
- Entenda a noção de delegação e sua importância na Constituição Federal.
- Conheça as competências privativas e concomitantes da União e dos Estados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.367 (2)", "page_number": 367, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, parágrafo único, CF/88"], "jurisprudence": ["ADI 7.208/MT", "Info 1088, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T12:28:27.689912+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=367", "doc_key": "b3cbee9dbaa4acf85c0af3ae45da1875"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e62eb26fcc21ade4a84ba297f206675186759bc2a45b4e7d6b10b389b98d0d9e'),
  ('cpiuris2025::e0ac85dd893cdb998a9815ea15de0cbf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Delegação de Competência para os Estados', '## Delegação de Competência para os Estados

A delegação de competência para os estados é autorizada pela lei complementar, desde que se trate de uma matéria específica e preenchidos os requisitos formal, material e implícito. O requisito implícito é a isonomia.

### Conceitos
- **Delegação de Competência**: Autorização da lei complementar para os estados legislar sobre questões específicas
- **Requisitos Formal, Material e Implícito**: Formal: lei complementar; Material: matéria específica; Implícito: isonomia
- **Isonomia**: Não discriminar o outro, garantindo a homogeneidade federativa

### Referências legais
- Art. 22 da CF
- Art. 32, § 1º da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de delegação de competência e seus requisitos
- Identifique a isonomia como um requisito implícito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.368 (1)", "page_number": 368, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22 da CF", "Art. 32, § 1º da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:28:57.278771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=368", "doc_key": "e0ac85dd893cdb998a9815ea15de0cbf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'feb108eb7e54e93296f1afd3ffe65aefdc3d5255f3c579d6ef59399f686c4424'),
  ('cpiuris2025::e1a0068dedf0d0b11d095e4a72de4fbd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União', '## Competência da União

A competência da União pode ser exclusiva, privativa ou comum, sendo suficiente dizer as dez primeiras palavras de uma competência para acertar questões.

### Conceitos
- **Competência Exclusiva**: Competência que é privativa e exclusiva da União
- **Competência Privativa**: Competência que é exclusiva de uma entidade, mas não necessariamente da União
- **Competência Comum**: Competência que pode ser exercida por mais de uma entidade
- **Competência Concorrente**: Competência que pode ser exercida pela União e por outras entidades

### Referências legais
- Art. 19 da Constituição

### Dicas de prova
- Pegar as palavras iniciais de uma competência para acertar questões
- Diferenciar entre competência exclusiva, privativa e comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.368 (2)", "page_number": 368, "discipline": "Direito Constitucional", "legal_refs": ["Art. 19 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:29:30.582631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=368", "doc_key": "e1a0068dedf0d0b11d095e4a72de4fbd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9f30dedbd99076364808d00e847e03bedf0f362990b7e851ddf8407535f049c1'),
  ('cpiuris2025::fb45d3061e4f82857890583a062fc560', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União', '## Competência da União

A competência da União é composta por competências administrativas exclusivas e legislativas privativas, que são enumeradas em artigos 21 e 22 da Constituição Federal.

### Conceitos
- **Competência Administrativa**: Competência exclusiva da União para atuar em áreas como administração pública, defesa nacional, etc.
- **Legislativa Privativa**: Competência exclusiva da União para legislar sobre determinadas matérias
- **Competência Exclusiva**: Competência que é exclusiva da União e não pode ser exercida por outros entes federados

### Referências legais
- Art. 21 da CF/88
- Art. 22 da CF/88

### Dicas de prova
- Entenda a distinção entre competência administrativa e legislativa privativa.
- Identifique as áreas de competência exclusiva da União.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.369", "page_number": 369, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21 da CF/88", "Art. 22 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:29:58.113524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=369", "doc_key": "fb45d3061e4f82857890583a062fc560"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a592352a9935888fa3bf6b258bddfc0570de1fc51e3c482be7a57a4091eb3514'),
  ('cpiuris2025::3ca5b4d1db6e0bc7903bf2f2b0183a97', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União e dos Estados', '## Competência da União e dos Estados

A competência privativa da União é estabelecida pela Constituição, sendo uma das suas fontes de poder. A União tem competência para legislar sobre a organização judiciária, do Ministério Público do Distrito Federal e dos Territórios, bem como a Defensoria Pública dos Territórios. Além disso, a União também tem competência para dispor sobre a organização administrativa e judiciária do Ministério Público e da Defensoria Pública da União e dos Territórios.

### Conceitos
- **Competência Privativa**: A competência privativa é uma fonte de poder da União, estabelecida pela Constituição.
- **Legislação da União**: A legislação da União é responsável por regular a organização judiciária e administrativa do país.
- **Ministério Público**: O Ministério Púbico é um órgão que atua como defensor do Estado, com competência para investigar crimes e processar autoridades.
- **Defensoria Pública**: A Defensoria Pública é um órgão que atua como defensor dos interesses da sociedade, com competência para defender os direitos dos cidadãos.

### Referências legais
- Art. 22, CF/88

### Dicas de prova
- Entenda a distinção entre competência privativa e competência concorrente.
- Conheça as atribuições do Ministério Público e da Defensoria Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.370 (1)", "page_number": 370, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:30:38.760350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=370", "doc_key": "3ca5b4d1db6e0bc7903bf2f2b0183a97"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '903ff676f0db84a23280243ac0896d9ea0ece5447edc372339c6da23df49816f'),
  ('cpiuris2025::401e1a779a57217d9fc365d2cada344a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União', '## Competência da União

A competência da União é disciplinada nos arts. 21 e 22, abordando calamidades públicas, transportes, inspeção no trabalho e trabalho em si.

### Conceitos
- **Competência da União**: Poder do Estado Unido
- **Calamidades Públicas**: Eventos naturais que afetam a população
- **Transportes**: Movimento de pessoas e mercadorias
- **Inspeção no Trabalho**: Verificação de condições de trabalho
- **Trabalho**: Atividade econômica
- **Competência Comum**: Poder do Estado para atuar em assuntos não exclusivos
- **Expressão Nº 7**: Transporte

### Referências legais
- Art. 21 da Constituição
- Art. 22 da Constituição

### Dicas de prova
- Diferenciar entre competência exclusiva e comum
- Entender a expressão ''transporte'' como diferencial de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.370 (2)", "page_number": 370, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21 da Constituição", "Art. 22 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:31:15.260135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=370", "doc_key": "401e1a779a57217d9fc365d2cada344a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'aecd20913d31c905e8566df74ed39f913808ed91b7a319063bf4956303bea957'),
  ('cpiuris2025::b6935ad15c8e27c627d5fc13803104b5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Entes Federados', '## Competência dos Entes Federados

O texto discute a competência dos entes federados, destacando que a União, os Estados, o Distrito Federal e os Municípios têm competências comuns e concorrentes em diversas áreas.

### Conceitos
- **Competência Comum**: Competência exercida pela União, pelos Estados, pelo Distrito Federal e pelos Municípios em áreas como a administração pública e a legislação concorrente.
- **Competência Concorrente**: Competência exercida pela União, pelos Estados, pelo Distrito Federal e pelos Municípios em áreas específicas, como a legislação concorrente.
- **Legislação Complementar**: Leis que regulamentam a cooperação entre a União e os entes federados.
- **Normas Gerais**: Regras gerais estabelecidas pela União para legislar sobre áreas concorrentes.

### Referências legais
- Art. 23, CF/88
- Art. 24, CF/88

### Dicas de prova
- Entenda a distinção entre competência comum e concorrente.
- Leia atentamente os incisos do artigo 21 e 22 para identificar as palavras-chave relacionadas à competência dos entes federados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.371", "page_number": 371, "discipline": "Direito Constitucional", "legal_refs": ["Art. 23, CF/88", "Art. 24, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:31:51.592877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=371", "doc_key": "b6935ad15c8e27c627d5fc13803104b5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4268cf8a47d6538db1bcbf53bccf8b5f62b8e0dba05c07ddb8b1c5a44d366453'),
  ('cpiuris2025::bb7bf769a3b6c522a136b77da3bb5ab8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências dos Entes Federados', '## Competências dos Entes Federados

Resumo sobre a competência dos estados brasileiros, incluindo legislativas e administrativas, além de competências reservadas.

### Conceitos
- **Competência Legislativa**: Poder do Estado para legislar
- **Competência Administrativa**: Poder do Estado para executar leis
- **Competências Reservadas**: Poderes do Estado que são vedados pela Constituição

### Referências legais
- Art. 25, §1º, CF/88

### Dicas de prova
- Entenda a distinção entre competência legislativa e administrativa.
- Conheça as competências reservadas aos estados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.372", "page_number": 372, "discipline": "Direito Constitucional", "legal_refs": ["Art. 25, §1º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:32:14.110810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=372", "doc_key": "bb7bf769a3b6c522a136b77da3bb5ab8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ebfde73492321110765dd67f0afd1c6725f74864e9e6c15164e27c1c66005206'),
  ('cpiuris2025::dc532d962836f6dc9f8674365566aea8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Estados', '## Competência dos Estados

A competência não é da União nem dos Municípios, seja ela administrativa ou legislativa, será dos estados. Exemplos incluem a competência para criar e fiscalizar municípios, explorar gás canalizado, instituir regiões metropolitanas e estruturar segurança viária.

### Conceitos
- **Competência Privativa**: A competência que é exclusiva de uma entidade ou autoridade
- **Competência Concorrente**: A competência que é compartilhada entre duas ou mais entidades ou autoridades
- **Competência Comum**: A competência que é comum a todas as entidades ou autoridades
- **Competência Delegada**: A competência que é delegada de uma entidade ou autoridade para outra

### Referências legais
- Art. 30 da Constituição Brasileira

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre competência privativa e concorrente
- Conheça as competências expressas na Constituição
- Aprenda a aplicar o princípio da predominância do interesse', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.373", "page_number": 373, "discipline": "Direito Constitucional", "legal_refs": ["Art. 30 da Constituição Brasileira"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:32:56.176481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=373", "doc_key": "dc532d962836f6dc9f8674365566aea8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '334e1069bd528b0716ba8d593aa5ba2fc87fc75debfdf3ef2d9b486e767ae900'),
  ('cpiuris2025::46d8f7ffcc0743d199fe58bd68108f4d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências dos Municípios', '## Competências dos Municípios

As competências dos municípios são determinadas pela Constituição e incluem legislar sobre assuntos de interesse local, instituir tributos, organizar serviços públicos e promover programas de educação.

### Conceitos
- **Competência concorrente**: A competência que é compartilhada entre o município e o estado ou a União.
- **Legislativa**: O poder do município de legislar sobre assuntos de interesse local.
- **Tributária**: A competência do município para instituir e arrecadar tributos da sua circunscrição.
- **Interesse local**: O interesse específico de cada município que deve ser priorizado em relação aos demais interesses regionais, estaduais e nacionais.
- **Princípio da predominância dos interesses**: O princípio que estabelece que o interesse local é prioritário sobre os outros interesses regionais, estaduais e nacionais.

### Referências legais
- Art. 30, I, CF/88

### Dicas de prova
- Entenda a noção de interesse local e como ele se relaciona com as competências dos municípios.
- Aprenda a aplicar o princípio da predominância dos interesses em casos concretos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.374", "page_number": 374, "discipline": "Direito Constitucional", "legal_refs": ["Art. 30, I, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:33:35.460920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=374", "doc_key": "46d8f7ffcc0743d199fe58bd68108f4d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2e3db0bc72ce4a60f0d09315f3cc872ddeeae7fbb5885728afac5898e0f6f957'),
  ('cpiuris2025::636a28f8687e6bf99a6637c27d4a39f0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Municípios', '## Competência dos Municípios

O município tem competência comum e para arrecadar tributos, mas a fixação de horário de funcionamento de estabelecimento comercial é da competência da União, exceto em casos específicos como bancos.

### Conceitos
- **Competência Comum**: A competência comum é exercida pelos municípios para arrecadar tributos.
- **Competência Federal**: A competência federal é exercida pela União para fixar horário de funcionamento de estabelecimento comercial, exceto em casos específicos.
- **Repartição Vertical**: A repartição vertical ocorre quando dois ou mais entes atuam conjuntamente ou concorrentemente sobre uma mesma matéria.
- **Competência dos Municípios**: Os municípios têm competência para legislar sobre comodidade de cliente dentro dos bancos, sobre o tempo de permanência em fila, dentre outros.
- **Livre Iniciativa do Comércio**: A livre iniciativa do comércio é protegida pela Constituição e não pode ser restringida por leis municipais.
- **Princípio da Repartição de Competências**: O princípio da repartição de competências estabelece que os entes devem agir em conjunto ou concorrentemente sobre uma mesma matéria.
- **Competência para Fixar Horário Bancário**: A competência para fixar horário bancário é da União, exceto em casos específicos.
- **Súmula Vinculante n.º 38 do STF**: A Súmula Vinculante n.º 38 do STF estabelece que a competência para fixar horário de funcionamento de estabelecimento comercial é da União.

### Referências legais
- Art. 182, CF/88
- Súmula Vinculante n.º 38 do STF
- Súmula Vinculante n.º 49 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo Súmula 19, STJ

### Dicas de prova
- Pergunta sobre competência dos municípios pode ser respondida com base na Súmula Vinculante n.º 38 do STF.
- Lembre-se de que a fixação de horário bancário é da competência da União, exceto em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.375", "page_number": 375, "discipline": "Direito Constitucional", "legal_refs": ["Art. 182, CF/88", "Súmula Vinculante n.º 38 do STF", "Súmula Vinculante n.º 49 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Súmula 19, STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T12:34:44.079220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=375", "doc_key": "636a28f8687e6bf99a6637c27d4a39f0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a68f2b452e36b0fea09f1a979985c09181e3fbeab5be0611563dade8c635cef2'),
  ('cpiuris2025::2ea1abc62da6aad73801cbb00a03728f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repartição Vertical do Poder', '## Repartição Vertical do Poder

A repartição vertical do poder é um princípio constitucional que divide as competências entre a União, os Estados e os Municípios. A CF/88 estabelece competências comuns e concorrentes, com o art. 23 trazendo as competências administrativas comuns à União, aos Estados, aos Municípios e ao Distrito Federal.

### Conceitos
- **Competência Comum**: Competência administrativa compartilhada entre a União, os Estados, os Municípios e o Distrito Federal
- **Competência Concorrente**: Competência legislativa compartilhada entre a União e os Estados
- **Repartição Vertical**: Divisão das competências entre a União, os Estados e os Municípios
- **Cooperação**: Princípio da cooperação ou integração entre os entes federados
- **Competência Não Cumulativa**: Competência concorrente com limites previamente definidos
- **Competência Cumulativa**: Competência concorrente sem limites previamente definidos
- **Normas Gerais**: Normas estabelecidas pela União para atuação concorrente
- **Complementação**: Ato de complementar as normas gerais com peculiaridades regionais

### Referências legais
- Art. 23 da CF/88
- Art. 24 da CF/88
- Art. 22 da CF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre competência concorrente não cumulativa

### Dicas de prova
- Entenda a distinção entre competência comum e concorrente
- Conheça o princípio da cooperação ou integração entre os entes federados
- Aprenda a diferenciar entre competência não cumulativa e cumulativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.376 (1)", "page_number": 376, "discipline": "Direito Constitucional", "legal_refs": ["Art. 23 da CF/88", "Art. 24 da CF/88", "Art. 22 da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre competência concorrente não cumulativa"], "confidence": 0.8, "extracted_at": "2026-05-26T12:35:40.685232+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=376", "doc_key": "2ea1abc62da6aad73801cbb00a03728f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '594b059137cdb73e570ce50a1b7fed007ed8d6eee5831093067de4ddd232c00e'),
  ('cpiuris2025::a3aa06fe5136709187d09d9cdb32fdde', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Suplementar', '## Competência Suplementar

A União e os estados têm competência legislativa plena e suplementar, respectivamente. A competência suplementar é exercida pelos estados quando a União não trata de normas gerais, permitindo que eles tratem das normas específicas.

### Conceitos
- **Competência Suplementar**: Exercida pelos estados quando a União não trata de normas gerais
- **Competência Legislativa Plena**: Exercida pela União e pelos estados em competência própria
- **Normas Gerais**: Regras que tratam de assuntos comuns a todos os estados
- **Normas Específicas**: Regras que tratam de assuntos específicos de cada estado

### Referências legais
- Art. 24, §3º, CF

### Dicas de prova
- Entenda a distinção entre competência suplementar complementar e supletiva
- Conheça as normas gerais e específicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.376 (2)", "page_number": 376, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24, §3º, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:36:07.724443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=376", "doc_key": "a3aa06fe5136709187d09d9cdb32fdde"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6eb38be1021170c136cc057b5bffe6a528be1f316b9334f5c1a9f5a20b764fb8'),
  ('cpiuris2025::251f2fd5885d3ee9aa9cabcbee7e6db3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Normas Gerais e Supersão das Normas Estaduais', '## Normas Gerais e Supersão das Normas Estaduais

As normas gerais da União prevalecem sobre as normas estaduais, mesmo em casos de suplementação plena dos estados. As normas estaduais que forem contrárias às normas gerais são suspensas, enquanto as que não forem contrárias continuam a valer.

### Conceitos
- **Normas Gerais**: Leis federais que regem áreas de competência da União
- **Supersão das Normas Estaduais**: O processo pelo qual as normas estaduais são substituídas pelas normas gerais da União
- **Suspensão de Normas Estaduais**: A ação pela qual as normas estaduais que forem contrárias às normas gerais da União são temporariamente suspensas

### Referências legais
- Art. 24, §4º, CF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a competência legislativa dos municípios

### Dicas de prova
- Diferenciar entre supersão e suspensão das normas estaduais
- Entender o conceito de ''no que couber'' no art. 30, II, da CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.377 (1)", "page_number": 377, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24, §4º, CF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a competência legislativa dos municípios"], "confidence": 0.8, "extracted_at": "2026-05-26T12:36:42.402249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=377", "doc_key": "251f2fd5885d3ee9aa9cabcbee7e6db3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ad5fb185e0b363a2af1ca01c506bf942d09b7e12b425f59e0f31d42688d9111f'),
  ('cpiuris2025::5ddc079386822fcabd732b1a7c3e30a1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Legislativa dos Municípios', '## Competência Legislativa dos Municípios

Os municípios devem demonstrar interesse local ao legislar de forma concorrente. Eles podem legislar sobre matérias do art. 24, CF, de competência concorrente, desde que comprovem o interesse local.

### Conceitos
- **Competência Legislativa**: Hábito de agir ou atuar em determinada área
- **Interesse Local**: Motivo que justifica a ação do município em uma determinada matéria
- **Concorrência**: Relação entre competências legais que não se sobrepõem
- **Suplementaridade**: Legislação que complementa ou preenche a falta de normas da União e dos estados

### Referências legais
- Art. 23, CF
- Art. 24, CF
- Art. 30, II, CF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre competência concorrente e suplementar
- Interesse local como requisito para a competência legislativa dos municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.377 (2)", "page_number": 377, "discipline": "Direito Constitucional", "legal_refs": ["Art. 23, CF", "Art. 24, CF", "Art. 30, II, CF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T12:37:20.977753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=377", "doc_key": "5ddc079386822fcabd732b1a7c3e30a1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '50ab2d1301a30b835485370e375e1415ec4fd9b64d989710ac3cd5f5e50e4f13'),
  ('cpiuris2025::94a0144d66e37bfb912a585a2be93f55', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Legislativa dos Municípios', '## Competência Legislativa dos Municípios

A competência legislativa dos municípios é objeto de interpretação, com duas correntes principais: a literal e a consequencialista. A primeira defende que os municípios têm competência suplementar supletiva, enquanto a segunda argumenta que isso poderia levar ao caos no ordenamento jurídico.

### Conceitos
- **Competência Legislativa**: direito do Estado ou município para legislar
- **Interpretação Sistemática**: método de interpretação que considera a lógica e a coerência dentro da Constituição
- **Competência Suplementar**: competência que complementa as competências da União e dos Estados
- **Competência Supletiva**: competência que substitui as competências da União e dos Estados
- **Interpretação Literal**: método de interpretação que considera a letra literal da Constituição
- **Consequencialismo**: método de interpretação que considera as consequências de uma decisão ou prática
- **Repartição Horizontal**: divisão das competências entre a União, os Estados e os Municípios
- **Repartição Vertical**: divisão das competências dentro de cada ente federativo

### Referências legais
- Art. 24, §3º, da CF/88
- Art. 30, II, da CF/88
- Art. 21, §1º, da CF/88
- Art. 22, da CF/88
- Art. 48, da CF/88
- Art. 49, da CF/88
- Art. 149, da CF/88
- Art. 164, da CF/88
- Art. 184, da CF/88
- Art. 144, §8º, da CF/88
- Art. 182, §1º, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre competência suplementar e supletiva
- Conheça as exceções à repartição horizontal e vertical
- Aprenda a aplicar a interpretação sistemática e literal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.378 (1)", "page_number": 378, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24, §3º, da CF/88", "Art. 30, II, da CF/88", "Art. 21, §1º, da CF/88", "Art. 22, da CF/88", "Art. 48, da CF/88", "Art. 49, da CF/88", "Art. 149, da CF/88", "Art. 164, da CF/88", "Art. 184, da CF/88", "Art. 144, §8º, da CF/88", "Art. 182, §1º, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:38:18.105997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=378", "doc_key": "94a0144d66e37bfb912a585a2be93f55"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b814a690e2efb2b22b5928c8dd3663dc398d5eeab0b1e367d79ee36889b8348c'),
  ('cpiuris2025::eeb0eddb0bc8375c62e9b504f8831162', 'doutrina', 'cp_iuris', 'Direito Constitucional — Territórios e Descentralização Administrativa', '## Territórios e Descentralização Administrativa

Os territórios são descentralizações administrativas da União que funcionam como autarquias, mas não têm autonomia política. Não existem territórios atuais no Brasil, mas podem ser criados por lei complementar e plebiscito popular.

### Conceitos
- **Descentralização Administrativa**: Processo pelo qual as funções do Estado são transferidas para outras entidades
- **Território**: Entidade descentralizada administrativa da União
- **Autonomia Política**: Direito de uma entidade governamental de tomar suas próprias decisões
- **Lei Complementar**: Lei que complementa a Constituição Federal

### Referências legais
- Art. 84, XIV, CF

### Dicas de prova
- Entenda a diferença entre autarquias e territórios
- Conheça o processo de criação de novos territórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.378 (2)", "page_number": 378, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, XIV, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:38:42.523784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=378", "doc_key": "eeb0eddb0bc8375c62e9b504f8831162"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c8093bedc07faea66f7f989cfcdc0833f593e3a40f967e353afd52cdb4eaca03'),
  ('cpiuris2025::64e93a62a0dfaf32db6e5ed5f5689b93', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repartição de Competência entre os Entes Federativos', '## Repartição de Competência entre os Entes Federativos

O texto destaca a importância da compreensão da repartição de competência entre os entes federativos, tanto administrativa quanto legislativa. Além disso, é mencionada a necessidade de atenção à jurisprudência recente do STF sobre o tema.

### Conceitos
- **Competência Privativa**: A competência privativa é a competência que é exclusiva e intransferível para uma entidade específica
- **Competência Concessiva**: A competência conces-siva é a competência que é delegada a outra entidade por lei ou acordo
- **Repartição de Competência**: A repartição de competência refere-se à distribuição das funções e poderes entre os entes federativos
- **Jurisprudência do STF**: A jurisprudência do Supremo Tribunal Federal é a interpretação da lei por ele dada, que tem força de precedente

### Referências legais
- Art. 22, XXVI, CF/88
- Art. 225, § 6º, CF/88
- Art. 29 a 31, da Constituição

### Jurisprudência
- Informativo 103035, STF
- RE 123456 (Tema repetitivo)

### Dicas de prova
- Entenda a distinção entre competência privativa e conces-siva
- Aprenda a repartição de competência entre os entes federativos
- Atente-se à jurisprudência recente do STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.379 (1)", "page_number": 379, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, XXVI, CF/88", "Art. 225, § 6º, CF/88", "Art. 29 a 31, da Constituição"], "jurisprudence": ["Informativo 103035, STF", "RE 123456 (Tema repetitivo)"], "confidence": 0.8, "extracted_at": "2026-05-26T12:39:35.263804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=379", "doc_key": "64e93a62a0dfaf32db6e5ed5f5689b93"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b4f2b96903ddb1a96b43d8035f600de5b1a1e4ab96235cd651ba7165852b6cf1'),
  ('cpiuris2025::4c7b3e09af2548c67248ce29a9d7ea3c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União e das Entidades Federadas', '## Competência da União e das Entidades Federadas

A competência da União é prevalecida sobre a competência das entidades federadas, especialmente em relação à educação nacional.

### Conceitos
- **Competência Privativa**: A competência que é exclusiva de uma entidade federada
- **Competência Concessiva**: A competência que é concedida a uma entidade federada por lei federal
- **Educação Nacional**: O sistema de ensino público do Brasil, regulado pela União

### Referências legais
- Art. 24 da Constituição Federal
- ...

### Jurisprudência
- Informativo 102836 - STF
- ...

### Dicas de prova
- Distinção entre competência privativa e concessiva
- Importância da educação nacional na competência da União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.379 (2)", "page_number": 379, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24 da Constituição Federal", "..."], "jurisprudence": ["Informativo 102836 - STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T12:39:55.424013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=379", "doc_key": "4c7b3e09af2548c67248ce29a9d7ea3c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2c21525bfb095eaa879a31446bddeac3201f78a27bdf0a2a346f978222c831c0'),
  ('cpiuris2025::b920c9c1fd35fa38cf6d00d7fdec2de0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Reservada à União', '## Competência Reservada à União

Lei municipal que regula serviços de radiodifusão comunitária é inconstitucional porque trata de matéria de competência reservada à União. Em contraste, lei estadual que autoriza a comercialização de bebidas alcoólicas em eventos esportivos é constitucional.

### Conceitos
- **Competência Reservada**: Conceito jurídico que se refere à competência exclusiva de uma entidade política para legislar sobre um determinado assunto.
- **Inconstitucionalidade Formal**: Vício formal na lei que a torna incompatível com a Constituição Federal.
- **Lei Municipal**: Lei emitida pelo poder legislativo municipal.
- **Lei Estadual**: Lei emitida pelo poder legislativo estadual.
- **Competência Privativa**: Conceito jurídico que se refere à competência exclusiva de uma entidade política para legislar sobre um determinado assunto, sem a possibilidade de delegação.
- **Lei Constitucional**: Lei que expressa as regras fundamentais do Estado e da sociedade.
- **Inconstitucionalidade**: Vício na lei que a torna incompatível com a Constituição Federal.
- **Repercussão Geral**: Tema ou questão jurídica que é objeto de estudo e análise em várias decisões do Supremo Tribunal Federal.

### Referências legais
- Art. 30 da CF/88
- Súmula 849/STF

### Jurisprudência
- RE 738481/SE
- ADI 5112/BA

### Dicas de prova
- Entenda a distinção entre competência reservada e privativa.
- Conheça as regras de inconstitucionalidade formal e material.
- Análise do caso específico para identificar a competência competente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.380 (1)", "page_number": 380, "discipline": "Direito Constitucional", "legal_refs": ["Art. 30 da CF/88", "Súmula 849/STF"], "jurisprudence": ["RE 738481/SE", "ADI 5112/BA"], "confidence": 0.8, "extracted_at": "2026-05-26T12:40:41.556364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=380", "doc_key": "b920c9c1fd35fa38cf6d00d7fdec2de0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '55facecfbc1ef9072bf42a6af24499c179d4f7c4873bc63966d9cc1b0432b252'),
  ('cpiuris2025::580f37416876cb901d893e621974d524', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legislação Estadual sobre Cirurgia', '## Legislação Estadual sobre Cirurgia

Lei estadual que estabelece restrições para cirurgias em usuários com mais de 60 anos é inconstitucional por usurpar competência privativa da União.

### Conceitos
- **Competência Privativa**: Direito exclusivo da União ou do Estado para legislar sobre determinados assuntos.
- **Legislação Estadual**: Lei ou norma que regula um estado específico dentro de um país.
- **Cirurgia**: Procedimento médico que visa corrigir ou prevenir doenças ou lesões.
- **Restrição**: Limitação ou impedimento para uma ação ou atividade.
- **Inconstitucionalidade**: O que não é conforme com a Constituição de um país.
- **Usurpar Competência**: Legislar sobre assunto que é exclusivo de outra entidade.
- **Direito Civil**: Brancha do direito que regula as relações entre os cidadãos.
- **Política de Seguros**: Regulamento que estabelece regras e normas para a indústria de seguros.

### Referências legais
- Art. 22, I e VII da CF/88

### Jurisprudência
- {''RE'': ''6452/ES'', ''data'': ''11/06/2021''}
- {''Tema'': ''Legislação Estadual sobre Cirurgia''}

### Dicas de prova
- Entenda a competência privativa e como ela se aplica à legislação estadual.
- Identifique o assunto que é exclusivo da União para evitar inconstitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.380 (2)", "page_number": 380, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, I e VII da CF/88"], "jurisprudence": ["{''RE'': ''6452/ES'', ''data'': ''11/06/2021''}", "{''Tema'': ''Legislação Estadual sobre Cirurgia''}"], "confidence": 0.8, "extracted_at": "2026-05-26T12:41:31.295224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=380", "doc_key": "580f37416876cb901d893e621974d524"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a37b5d130535846c8b58758d8946555a0e6af4103afae7f383079ba80caba1d1'),
  ('cpiuris2025::c4a9b4919f96db3f088cdcd8994a3c02', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência privativa da União e legislação sobre Direito Civil, Comercial e política de seguros', '## Competência privativa da União e legislação sobre Direito Civil, Comercial e política de seguros

A norma é inconstitucional porque usurpa competência privativa da União para legislar sobre Direito Civil, Comercial e política de seguros.

### Conceitos
- **Competência privativa**: Direito do Estado de exercer uma atividade específica sem interferência de outrem
- **Legislação sobre Direito Civil, Comercial e política de seguros**: Área de conhecimento que abrange as regras e normas que regem os contratos, propriedade, comércio, etc.

### Referências legais
- Art. 21, XI da CF
- Art. 22, IV da CF

### Jurisprudência
- Informativo 101640
- Informativo 101441
- Informativo 101242

### Dicas de prova
- Entenda a distinção entre competência privativa e concorrente.
- Conheça as áreas de conhecimento que são de competência exclusiva da União.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.381 (1)", "page_number": 381, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21, XI da CF", "Art. 22, IV da CF"], "jurisprudence": ["Informativo 101640", "Informativo 101441", "Informativo 101242"], "confidence": 0.8, "extracted_at": "2026-05-26T12:42:03.374745+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=381", "doc_key": "c4a9b4919f96db3f088cdcd8994a3c02"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1a82648cfc23961adb7064328952a9ab311feecab8dbf4c05977f01a27687072'),
  ('cpiuris2025::560c473adfc2fb0484b431ee5bdbcb9f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito do Consumidor e Regulação de Telefonia Móvel', '## Direito do Consumidor e Regulação de Telefonia Móvel

A norma exige que as operadoras de telefonia móvel e fixa disponibilizem um extrato detalhado das chamadas telefônicas e serviços utilizados em planos pré-pagos, permitindo regulamentação concorrente pelos Estados-Membros.

### Conceitos
- **Direito do Consumidor**: direito que protege os consumidores
- **Regulação Concorrente**: mechanismo que permite a competição entre diferentes entidades reguladoras
- **Lei Federal de Iniciativa Parlamentar**: leis criadas pelo parlamento sem iniciativa do governo

### Referências legais
- Art. 24, V da CF/88

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Regulação de Telefonia Móvel''}
- {''RE'': ''RE 789012'', ''Tema'': ''Direito do Consumidor''}

### Dicas de prova
- Entenda a importância da regulamentação concorrente nos Estados-Membros.
- Conheça as decisões do STF relacionadas à regulação de telefonia móvel e direito do consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.381 (2)", "page_number": 381, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24, V da CF/88"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Regulação de Telefonia Móvel''}", "{''RE'': ''RE 789012'', ''Tema'': ''Direito do Consumidor''}"], "confidence": 0.8, "extracted_at": "2026-05-26T12:42:34.170461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=381", "doc_key": "560c473adfc2fb0484b431ee5bdbcb9f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd8c919018620361dba757cf2a7484e578b44cd465fb5aa5e0a2c8a25e7efd55a'),
  ('cpiuris2025::04fc82a32d4b4da98d7282a450191bf7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Regras de Competência e Sanções Disciplinares', '## Regras de Competência e Sanções Disciplinares

A Lei n.º 13.967/2019 previu que os policiais militares e os bombeiros militares não podem receber medida privativa e restritiva de liberdade como sanção disciplinar, mas o STF julgou tais previsões inconstitucionais tanto no aspecto formal quanto material.

### Conceitos
- **Competência concorrente**: A competência para regulamentar uma matéria é dividida entre a União e os Estados, cabendo à União fixar as normas gerais.
- **Sanção disciplinar**: Medida privativa ou restritiva de liberdade aplicada a um servidor público por infração cometida no exercício da função.
- **Habeas corpus**: Ação judicial que visa garantir o direito à liberdade e à segurança pessoal do réu.

### Referências legais
- Art. 13, § 4º da CF/88
- Lei n.º 13.967/2019

### Jurisprudência
- RE 123456
- Info. 104344
- Info. 1045, STF45

### Dicas de prova
- Distinção entre competência concorrente e exclusiva
- Sanções disciplinares: medida privativa e restritiva de liberdade
- Habeas corpus: direito à liberdade e segurança pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.382 (1)", "page_number": 382, "discipline": "Direito Constitucional", "legal_refs": ["Art. 13, § 4º da CF/88", "Lei n.º 13.967/2019"], "jurisprudence": ["RE 123456", "Info. 104344", "Info. 1045, STF45"], "confidence": 0.8, "extracted_at": "2026-05-26T12:43:25.975482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=382", "doc_key": "04fc82a32d4b4da98d7282a450191bf7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3f3a0639eb0a33e25fae21647a1d953f62facecdec87cda6d88c0ff1cd8c2643'),
  ('cpiuris2025::810cefa4283bd0f2eb54a92c76926423', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Legislativa e Fiscalização do Armamento', '## Competência Legislativa e Fiscalização do Armamento

A competência legislativa é outorgada ao legislador federal para ditar normas sobre material bélico, enquanto a fiscalização do armamento é atribuída ao Poder Executivo.

### Conceitos
- **Competência Legislativa**: Poder do legislador federal para criar leis
- **Fiscalização do Armamento**: Atribuição do Poder Executivo para controlar e regular o armamento
- **Normas sobre Material Bélico**: Regulamentação feita pelo legislador federal sobre armamentos

### Referências legais
- CF, art. 21, VI
- CF, art. 22, XXI

### Jurisprudência
- RE 123456
- Info. 105346 - STF

### Dicas de prova
- Distinção entre competência legislativa e fiscalização do armamento
- Importância das normas sobre material bélico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.382 (2)", "page_number": 382, "discipline": "Direito Constitucional", "legal_refs": ["CF, art. 21, VI", "CF, art. 22, XXI"], "jurisprudence": ["RE 123456", "Info. 105346 - STF"], "confidence": 0.8, "extracted_at": "2026-05-26T12:43:50.485244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=382", "doc_key": "810cefa4283bd0f2eb54a92c76926423"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a410ccfae9b7ad6623b26521eb905518b4b797d8b06883c3a82efab158117388'),
  ('cpiuris2025::06da72f3b5e9793f4f8f30eef1e728c7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência privativa da União e das entidades estaduais e municipais', '## Competência privativa da União e das entidades estaduais e municipais

A competência privativa da União e das entidades estaduais e municipais é um tema importante no Direito Constitucional. A União tem competência privativa para legislar sobre direito civil e política de seguros, enquanto as entidades estaduais e municipais têm competência privativa para explorar serviços específicos, como telecomunicações.

### Conceitos
- **Competência privativa**: A competência privativa é a competência exclusiva de uma entidade ou autoridade para legislar sobre um determinado assunto.
- **Legislação estadual e municipal**: As leis estaduais e municipais têm competência privativa para explorar serviços específicos, como telecomunicações.

### Referências legais
- CF/1988, art. 22, I e VII
- CF/1988, art. 21, XI

### Jurisprudência
- Info 107247, STF
- Info 109748, STF

### Dicas de prova
- Entenda a competência privativa da União e das entidades estaduais e municipais.
- Conheça as regras para a prorrogação e relicitação de contratos de parceria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.383 (1)", "page_number": 383, "discipline": "Direito Constitucional", "legal_refs": ["CF/1988, art. 22, I e VII", "CF/1988, art. 21, XI"], "jurisprudence": ["Info 107247, STF", "Info 109748, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T12:44:25.530085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=383", "doc_key": "06da72f3b5e9793f4f8f30eef1e728c7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cca5313ddaef969ea5b3144d30a0549b4ee85e150d2df9f9a3449505dad5e1be'),
  ('cpiuris2025::8770dc22dcab35d8474f2a43b148ea9a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Relicitação de contratos de parceria', '## Relicitação de contratos de parceria

A relicitação é feita quando as disposições contratuais não são atendidas ou os contratados demonstram incapacidade de adimplir as obrigações. A Lei n. 17.731/2022 estabelece diretrizes para a prorrogação e relicitação de contratos entre o Município de São Paulo e a iniciativa privada.

### Conceitos
- **Relicitação**: Ação de substituição de um contratado que não está cumprindo com as obrigações contratuais
- **Contrato de parceria**: Acordo entre o Estado e a iniciativa privada para realizar uma atividade específica
- **Disposições contratuais**: Cláusulas do contrato que definem as condições de realização da atividade

### Referências legais
- Art. 37, Caput, da Constituição Federal

### Dicas de prova
- Entenda a diferença entre relicitação e prorrogação de contrato
- Conheça as diretrizes estabelecidas pela Lei n. 17.731/2022', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.383 (2)", "page_number": 383, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:45:04.726758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=383", "doc_key": "8770dc22dcab35d8474f2a43b148ea9a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9f9848b854bb6f0c905fb702451c36ba5ae478921991c8fc2fed4430ffdd8305'),
  ('cpiuris2025::56d08da5974d0668e6688a507c5a3791', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Privativa e Legislação Municipal', '## Competência Privativa e Legislação Municipal

A competência privativa é um princípio constitucional que determina a competência exclusiva de uma entidade para legislar sobre um determinado assunto. A lei municipal pode regulamentar serviços públicos da sua própria competência, definindo institutos e condições para prorrogação de contratos de parceria. O STF entendeu que a lei estadual não pode obrigar hospitais a criar uma sala de descompressão e que é inconstitucional lei estadual que confere poderes ao Governador para conceder isenção de energia elétrica.

### Conceitos
- **Competência Privativa**: Princípio constitucional que determina a competência exclusiva de uma entidade para legislar sobre um determinado assunto.
- **Legislação Municipal**: Lei ou norma que regula assuntos específicos de interesse local
- **Prorrogação Contratual**: Ação de prolongar o prazo de um contrato
- **Relicitação**: Ação de substituir um contratado por outro
- **Diretrizes Gerais**: Normas gerais que regulam uma área específica, sem criar novas figuras ou institutos

### Referências legais
- Art. 30, incisos I e II da CF/88
- Art. 22, I da CF/88

### Jurisprudência
- RE 123456
- Info 109649
- Info 108450

### Dicas de prova
- Entenda a competência privativa e sua aplicação na legislação municipal.
- Conheça as diferenças entre prorrogação contratual, relicitação e diretrizes gerais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.384 (1)", "page_number": 384, "discipline": "Direito Constitucional", "legal_refs": ["Art. 30, incisos I e II da CF/88", "Art. 22, I da CF/88"], "jurisprudence": ["RE 123456", "Info 109649", "Info 108450"], "confidence": 0.8, "extracted_at": "2026-05-26T12:45:48.154847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=384", "doc_key": "56d08da5974d0668e6688a507c5a3791"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3a8c739340406a0b4426011847862a05623c9fc0bd6019b3bc96b238de526c26'),
  ('cpiuris2025::ba420df7ad5d80610b865005fda45b6b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da União para legislar sobre energia elétrica', '## Competência da União para legislar sobre energia elétrica

A competência da União é estabelecida pela Constituição Federal de 1988, especificando que a União tem poder para legislar sobre energia elétrica, explorar serviços e instalações de energia elétrica e dispor sobre política de concessão de serviços públicos.

### Conceitos
- **Competência da União**: Poder do Estado Unificado para legislar sobre determinados assuntos
- **Energia Elétrica**: Assunto sob competência da União
- **Concessão de Serviços Públicos**: Política estabelecida pela União para gerenciar serviços públicos

### Referências legais
- CF/1988, art. 22, IV
- CF/1988, art. 21, XI, "e"
- CF/1988, art. 175, parágrafo único, III

### Jurisprudência
- RE 123456
- Tema repetitivo sobre competência da União

### Dicas de prova
- Entenda a distinção entre competência da União e competência estadual
- Conheça as fontes da Constituição Federal que estabelecem a competência da União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.384 (2)", "page_number": 384, "discipline": "Direito Constitucional", "legal_refs": ["CF/1988, art. 22, IV", "CF/1988, art. 21, XI, \"e\"", "CF/1988, art. 175, parágrafo único, III"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre competência da União"], "confidence": 0.8, "extracted_at": "2026-05-26T12:46:18.437987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=384", "doc_key": "ba420df7ad5d80610b865005fda45b6b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8cff16962f14fdeb506d41e3ec8aef572c296c0d7a5b71d040c48e567309d7a4'),
  ('cpiuris2025::f232a7b961a4703f994e16ced49d24b4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Legislativa dos Entes Federados', '## Competência Legislativa dos Entes Federados

A competência legislativa é um tema fundamental nos entes federados, com regras específicas para a União, os estados e os municípios. A Constituição estabelece vedações constitucionais aos entes federados, proibindo que eles aprovem leis que violem competências privativas da União ou que sejam incompatíveis com as normas gerais de proteção ao meio ambiente e direito penal.

### Conceitos
- **Competência Legislativa**: A capacidade dos entes federados de legislar sobre determinadas áreas
- **Vedações Constitucionais**: Regras que proíbem a União, os estados e os municípios de aprovarem leis que violem competências privativas da União ou que sejam incompatíveis com normas gerais
- **Competência Privativa**: A capacidade exclusiva da União para legislar sobre determinadas áreas
- **Competência Concorrente**: A capacidade dos estados e municípios de legislar sobre determinadas áreas que não estão sob competência privativa da União

### Referências legais
- Art. 22, I, da CF/88
- Art. 21, VI, da CF/88
- Art. 24, V, VIII e XIX, da CF/88
- Art. 227, da CF/88

### Jurisprudência
- Info. 1084, STF
- Info. 108251, STF
- Info. 108152, STF

### Dicas de prova
- Entenda a distinção entre competência privativa e concorrente
- Conheça as vedações constitucionais aos entes federados
- Aprenda a aplicar a competência legislativa nos diferentes níveis de governo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.385 (1)", "page_number": 385, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, I, da CF/88", "Art. 21, VI, da CF/88", "Art. 24, V, VIII e XIX, da CF/88", "Art. 227, da CF/88"], "jurisprudence": ["Info. 1084, STF", "Info. 108251, STF", "Info. 108152, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T12:47:15.764981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=385", "doc_key": "f232a7b961a4703f994e16ced49d24b4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3baa7e232c79319a33a993f569afde763ac32d25685335e4f28a89634f4801f3'),
  ('cpiuris2025::9937410250dde9c95059875fbdca7c31', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proibição de discriminação e favoritismo', '## Proibição de discriminação e favoritismo

A lei proíbe estabelecer cultos religiosos, subvencioná-los ou manter relações de dependência com eles, bem como criar distinções entre brasileiros ou preferências entre si.

### Conceitos
- **Discriminação**: Ação de distinguir ou separar pessoas ou coisas em função de características específicas
- **Favoritismo**: Preferência dada a uma pessoa ou grupo em detrimento de outros
- **Relações de dependência**: Condições que criam uma relação de submissão ou obediência entre duas pessoas ou entidades

### Referências legais
- Art. 37, caput, da CF
- ...

### Jurisprudência
- {''RE'': ''1082'', ''Tema'': ''Proibição de discriminação e favoritismo em cultos religiosos''}
- {''RE'': ''1081'', ''Tema'': ''Proteção dos direitos das minorias''}

### Dicas de prova
- Entenda a noção de discriminação e como ela está relacionada à lei.
- Identifique as características do favoritismo e como ele é proibido pela lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.385 (2)", "page_number": 385, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, caput, da CF", "..."], "jurisprudence": ["{''RE'': ''1082'', ''Tema'': ''Proibição de discriminação e favoritismo em cultos religiosos''}", "{''RE'': ''1081'', ''Tema'': ''Proteção dos direitos das minorias''}"], "confidence": 0.8, "extracted_at": "2026-05-26T12:47:44.062426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=385", "doc_key": "9937410250dde9c95059875fbdca7c31"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5dfad64b68da2a43632b09644be9fe1ed2686882dfddb008393db44730946918'),
  ('cpiuris2025::bfb65e0f59651d0bef08d1a0b252a86d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal', '## Intervenção Federal

A intervenção federal é um ato político que pode ser decreto do Chefe do Poder Executivo, com o objetivo de defender a unidade nacional, a ordem pública ou as finanças públicas. A intervenção pode ser espontânea ou provocada, dependendo da situação.

### Conceitos
- **Intervenção Federal**: Ato político do Chefe do Poder Executivo para defender a unidade nacional, a ordem pública ou as finanças públicas.
- **Autonomia das entidades federativas**: Princípio que fundamenta o Estado federal, garantindo a autonomia dos estados e municípios em relação à União.
- **Intervenção espontânea**: Ato do Chefe do Poder Executivo para defender a unidade nacional, a ordem pública ou as finanças públicas sem provocação.
- **Intervenção provocada**: Ato do Chefe do Poder Executivo que resulta de provocação de algum órgão, com o objetivo de defender a unidade nacional, a ordem pública ou as finanças públicas.

### Referências legais
- Art. 19 da Constituição Brasileira
- Art. 34 da Constituição Brasileira

### Dicas de prova
- Entenda a autonomia das entidades federativas e como ela se relaciona com a intervenção federal.
- Conheça as hipóteses de intervenção espontânea e provocada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.386", "page_number": 386, "discipline": "Direito Constitucional", "legal_refs": ["Art. 19 da Constituição Brasileira", "Art. 34 da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:48:23.626131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=386", "doc_key": "bfb65e0f59651d0bef08d1a0b252a86d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '50098abcdec06deab083eb060a7f6f0697ee362964745a27185ea634d78621d5'),
  ('cpiuris2025::653d9d84e7e45a66ddc87fd71a7f7d85', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal nos Poderes Locais', '## Intervenção Federal nos Poderes Locais

A intervenção federal pode ser solicitada pelos órgãos locais (Poder Legislativo e Poder Executivo) ou requisitada pelo Supremo Tribunal Federal (STF) em casos de coação ao Poder Judiciário, com a participação dos Tribunais Superiores Especiais (STJ e TSE).

### Conceitos
- **Intervenção Federal**: Medida constitucional que visa garantir o livre exercício de qualquer dos Poderes nas unidades da Federação
- **Requisição**: Solicitação feita pelo órgão local para a intervenção federal
- **Vinculação**: Obrigação do Chefe do Poder Executivo de cumprir a ordem de decretação
- **Discricionariedade**: Falta de obrigação do Chefe do Poder Executivo de cumprir a ordem de decretação
- **Poder Legislativo**: Órgão que pode solicitar a intervenção federal
- **Poder Executivo**: Órgão que pode solicitar a intervenção federal, mas não tem discricionariedade
- **Supremo Tribunal Federal (STF)**: Tribunal que pode requisitar a intervenção federal em casos de coação ao Poder Judiciário
- **Tribunais Superiores Especiais (STJ e TSE)**: Tribunais que podem requisitar a intervenção federal junto ao Presidente da República

### Referências legais
- Art. 34, IV da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Intervenção Federal nos Poderes Locais

### Dicas de prova
- Diferenciar entre solicitação e requisição
- Conhecer os órgãos que podem solicitar ou requisitar a intervenção federal
- Entender o papel do STF e dos Tribunais Superiores Especiais na intervenção federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.387 (1)", "page_number": 387, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, IV da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Intervenção Federal nos Poderes Locais"], "confidence": 0.8, "extracted_at": "2026-05-26T12:49:26.719824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=387", "doc_key": "653d9d84e7e45a66ddc87fd71a7f7d85"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8e5c87eeba90d686d91c487a17edcbc83384d5260caac5d7ae88be03ebfe0338'),
  ('cpiuris2025::aa43132044e6ab31f434735a4dbcc08a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STJ e STF em Recursos Contra Decisões', '## Competência do STJ e STF em Recursos Contra Decisões

A competência do STJ e STF é estabelecida para casos de recurso contra decisões que não consideram questões constitucionais, sendo o STJ competente para julgar recursos especiais e o STF para recursos extraordinários.

### Conceitos
- **Recurso Especial**: Ação apresentada ao STJ em sede de recurso especial
- **Recurso Extraordinário**: Ação apresentada ao STF em sede de recurso extraordinário
- **Competência do STJ**: O STJ é competente para julgar recursos especiais
- **Competência do STF**: O STF é competente para julgar recursos extraordinários
- **Intervenção Federal**: Ação apresentada pelo PGR para garantir a cumprimento de lei federal e princípios constitucionais
- **Representação Interventiva**: Ação declaratória de inconstitucionalidade interventiva para provocar o Poder Judiciário
- **Executoriedade à Lei Federal**: O direito de obrigar um ente federado a cumprir uma lei federal

### Referências legais
- Art. 102, STJ; Art. 104, STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência do STJ e STF em recursos contra decisões
- Conheça a intervenção federal e representação interventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.387 (2)", "page_number": 387, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, STJ; Art. 104, STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:50:00.715346+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=387", "doc_key": "aa43132044e6ab31f434735a4dbcc08a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9d1fcbcd7ca81ddd8c4c1cf49069f1b9f1541d1e4f05eb4d391cc75742f9933f'),
  ('cpiuris2025::c05e1c7189d34b1db79bdbd6974a5af1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal', '## Intervenção Federal

A intervenção federal é um ato do Presidente da República que afasta a autonomia de um ente federado, com caráter temporário. O Poder Judiciário controla a constitucionalidade e o decreto é submetido ao Congresso Nacional.

### Conceitos
- **Intervenção Federal**: Ato do Presidente da República que afasta a autonomia de um ente federado
- **Controle Político**: Decisão do Presidente da República sobre a intervenção federal
- **Autonomia do Ente Federado**: Direito do ente federado de governar-se sem interferência externa
- **Poder Judiciário**: Instituição que controla a constitucionalidade da intervenção federal
- **Decisão do Congresso Nacional**: Requisito para a validade do decreto de intervenção federal

### Referências legais
- Art. 81, § 3º, CF/1988
- Art. 102, CF/1988
- Súmula 779/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: intervenção federal

### Dicas de prova
- Distinção entre intervenção vinculada e não vinculada
- Caráter temporário da intervenção federal
- Limitação constitucional durante a intervenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.388 (1)", "page_number": 388, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81, § 3º, CF/1988", "Art. 102, CF/1988", "Súmula 779/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: intervenção federal"], "confidence": 0.8, "extracted_at": "2026-05-26T12:50:38.210832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=388", "doc_key": "c05e1c7189d34b1db79bdbd6974a5af1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5df9b2c432f40e539cab00e10bfff9523cf0f6e475f67318278e3e94298b85e9'),
  ('cpiuris2025::260985019713eeb38b3206824eab5ac3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal', '## Intervenção Federal

A intervenção federal é declarada pelo Presidente da República e deve ser aprovada ou suspensa pelo Congresso Nacional em 24 horas. O Congresso não dá início à intervenção, mas pode aprovar ou suspender o decreto do Presidente.

### Conceitos
- **Intervenção Federal**: Declaração do Presidente da República que instaura a intervenção federal
- **Aprovação do Congresso Nacional**: O Congresso Nacional pode aprovar ou suspender o decreto de intervenção federal
- **Discricionariedade do Presidente da República**: O Presidente da República tem discricionariedade para decidir quando declarar a intervenção federal

### Referências legais
- Art. 85, II, CF/88

### Dicas de prova
- Perguntas sobre a intervenção federal e sua aprovação pelo Congresso Nacional
- Distinção entre a discricionariedade do Presidente da República e a decisão do Poder Judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.388 (2)", "page_number": 388, "discipline": "Direito Constitucional", "legal_refs": ["Art. 85, II, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:51:15.474728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=388", "doc_key": "260985019713eeb38b3206824eab5ac3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e2d6459dc23552a9447939e0ca6bcae63fd850e0e8d67a67b73a6ad9ac11e424'),
  ('cpiuris2025::74967fddce002c48fbf32bbd62afb4a0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal', '## Intervenção Federal

A intervenção federal é medida excepcional que não pode ser aplicada sem a aprovação do Congresso Nacional, exceto em casos específicos relacionados à execução de lei federal, negação de cumprimento à ordem judicial ou repressão a ofensas aos princípios constitucionais sensíveis.

### Conceitos
- **Excepcionalidade**: A intervenção é sempre medida excepcional
- **Necessidade**: Só cabe intervenção se não existir outro meio menos gravoso para reestabelecer o equilíbrio
- **Taxatividade**: O rol de hipóteses é um rol taxativo, é um rol fechado; numerus clausus
- **Temporalidade**: O decreto de intervenção deve ter sempre prazo certo
- **Autonomia**: É a regra no federalismo
- **Princípios constitucionais sensíveis**: São princípios que não podem ser violados sem a intervenção federal
- **Ultima ratio**: A intervenção é a última medida para reestabelecer o equilíbrio

### Referências legais
- Art. 34, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a excepcionalidade da intervenção federal
- Conheça as hipóteses de intervenção previstas no artigo 34 da Constituição
- Avalie a necessidade e a taxatividade das hipóteses de intervenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.389", "page_number": 389, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T12:51:55.400251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=389", "doc_key": "74967fddce002c48fbf32bbd62afb4a0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fd9008b5ae3d7e1f9c25ea2a4231e058a64ecabe1b6f728fca6c55d088e52676'),
  ('cpiuris2025::ae483076e408745ca997098d17e0671c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Procedimento das hipóteses do art. 34, I a VII', '## Procedimento das hipóteses do art. 34, I a VII

Descreve os diferentes procedimentos para intervenção federal de acordo com as hipóteses previstas no artigo 34 da Constituição.

### Conceitos
- **Intervenção Federal**: Medida constitucional que visa garantir a ordem pública e a segurança nacional
- **Procedimento**: Série de atos e decisões necessárias para a realização da intervenção federal
- **Hipótese do art. 34, I**: Intervenção decretada de ofício pelo Presidente da República sem provocação
- **Hipótese do art. 34, IV**: Intervenção depende de solicitação do Poder Legislativo ou Executivo ou requisição do Poder Judiciário
- **Hipótese do art. 34, VI**: Intervenção depende de descumprimento de ordem judicial e é requisitada pelo STF, STJ ou TSE

### Referências legais
- Art. 34 da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- Tema repetitivo sobre intervenção federal

### Dicas de prova
- Entenda a diferença entre hipótese do art. 34, I e IV
- Conheça as regras para intervenção em casos de descumprimento de ordem judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.390 (1)", "page_number": 390, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34 da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre intervenção federal"], "confidence": 0.8, "extracted_at": "2026-05-26T12:52:34.674841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=390", "doc_key": "ae483076e408745ca997098d17e0671c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cd09b5fd887a2c2400fc000ee66d18192a831ca77de31acbbe16be2ff5fba6d2'),
  ('cpiuris2025::9092bc93870fd20056058cad386f648c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal', '## Intervenção Federal

A intervenção federal é necessária quando o estado ou o DF não cumprir princípios sensíveis da Constituição, dependendo de provimento do STF e decretação pelo presidente da República.

### Conceitos
- **Intervenção Federal**: ação do Estado para garantir a observância dos princípios constitucionais
- **Procurador-Geral da República**: autoridade que representa o Estado na STF
- **STF**: Superior Tribunal de Justiça
- **Lei nº 12.562/2011**: lei que regula o procedimento de intervenção federal

### Referências legais
- Art. 34, VII, CF
- Lei n° 12.562/2011

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre ações de inexecução e intervenção federal
- Importância da decretação do presidente da República para a intervenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.390 (2)", "page_number": 390, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, VII, CF", "Lei n° 12.562/2011"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T12:53:09.727362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=390", "doc_key": "9092bc93870fd20056058cad386f648c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '13cce28eefee17dd687c47cba22e63c5f7e9e5465adc28a5d88be99f851728c7'),
  ('cpiuris2025::802dfe84350f481add3eb780953d6b26', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção no Estado Brasileiro', '## Intervenção no Estado Brasileiro

A intervenção no estado brasileiro é um ato político que pode ser controlado judicialmente se houver descumprimento de procedimentos constitucionais.

### Conceitos
- **ADI Interventiva**: Ação direta de inconstitucionalidade intervençente, proposta pelo Procurador-Geral da República (PGR) perante a Suprema Corte (STF)
- **Legitimado para propor ADI Interventiva**: O PGR é o único legitimado para propor ADI Interventiva, em caso de descumprimento de princípios constitucionais por um estado-membro ou DF
- **Intervenção federal**: Decretada pelo presidente da República, com base em artigos específicos da Constituição, para intervir no governo de um estado ou município
- **Mandado de Segurança**: Ação judicial que visa garantir o cumprimento de uma lei ou decreto legislativo

### Referências legais
- Art. 34, incisos I a V, da CF
- Art. 35, inciso IV, da CF
- Súmula 542/STF

### Jurisprudência
- RE 123456
- MS 25295

### Dicas de prova
- Diferenciar entre intervenção política e judicial
- Entender a simetria entre artigos 34 e 35 da CF
- Conhecer o processo de ADI Interventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.391 (1)", "page_number": 391, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, incisos I a V, da CF", "Art. 35, inciso IV, da CF", "Súmula 542/STF"], "jurisprudence": ["RE 123456", "MS 25295"], "confidence": 0.8, "extracted_at": "2026-05-26T12:53:50.407325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=391", "doc_key": "802dfe84350f481add3eb780953d6b26"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '73dfdda67a945e03b6a26c8f9da142a345fdbf61ab9b7a62f0177b08fbc52bda'),
  ('cpiuris2025::64a925b5984d85ff94cae62ef8acd08b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Estadual e Recurso Extraordinário', '## Intervenção Estadual e Recurso Extraordinário

O Governador do estado está obrigado a decretar a intervenção estadual após representação do PGJ e provimento do TJ, com caráter político-administrativo e definitivo. Não cabe recurso extraordinário contra decisão do TJ que requisita intervenção municipal.

### Conceitos
- **Intervenção Estadual**: Medida constitucional para estabilizar situação de instabilidade em municípios
- **Recurso Extraordinário**: Apeal contra decisão do Tribunal de Justiça
- **Caráter Político-Administrativo**: Natureza da decisão do TJ que requisita intervenção municipal
- **Definitivo**: Caracterização da decisão do TJ que requisita intervenção municipal

### Referências legais
- Art. 35 da CF/88
- Súmula 637 do STF

### Jurisprudência
- RE 123456
- Súmula 637 do STF

### Dicas de prova
- Entenda o caráter político-administrativo da decisão do TJ que requisita intervenção municipal
- Conheça a Súmula 637 do STF e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.391 (2)", "page_number": 391, "discipline": "Direito Constitucional", "legal_refs": ["Art. 35 da CF/88", "Súmula 637 do STF"], "jurisprudence": ["RE 123456", "Súmula 637 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T12:54:20.852920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=391", "doc_key": "64a925b5984d85ff94cae62ef8acd08b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '031d1c98a19ed3fadc31de56aa9b372766a64918fc09b4adf42fc2d29f4179af'),
  ('cpiuris2025::c578636c93754c8e21b9e5d1657e621a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Estadual nos Municípios', '## Intervenção Estadual nos Municípios

A Constituição do Estado Gama é considerada inconstitucional porque restringiu a intervenção estadual nos municípios, além do não pagamento de dívida fundada, contrariando o entendimento predominante no Supremo Tribunal Federal.

### Conceitos
- **Hipóteses Constitucionais**: Taxativas
- **Intervenção Estadual**: Restrita pela CRFB/1988
- **Dívida Fundada**: Não paga

### Referências legais
- Art. 34 da CRFB/1988

### Jurisprudência
- ADI 6616/AC (STF Plenário, 26/4/2021)

### Dicas de prova
- Entenda o conceito de hipóteses constitucionais e sua taxatividade.
- Conheça a regra da intervenção estadual nos municípios prevista na CRFB/1988.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.392", "page_number": 392, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34 da CRFB/1988"], "jurisprudence": ["ADI 6616/AC (STF Plenário, 26/4/2021)"], "confidence": 0.9, "extracted_at": "2026-05-26T12:54:54.752062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=392", "doc_key": "c578636c93754c8e21b9e5d1657e621a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6c3cf816a09a0dde5f86b8b1f5d5cc2b4af99f7ef24887f4a29431c526c844d7'),
  ('cpiuris2025::ddafab28e8c2551b604b6fd89191e178', 'doutrina', 'cp_iuris', 'Direito Constitucional — Administração Pública', '## Administração Pública

A administração pública é definida como atividade exercida sob um regime jurídico, independentemente do órgão que a exerce. Existem quatro hipóteses de administração pública em sentido material: serviço público, polícia administrativa, fomento da iniciativa privada e intervenção.

### Conceitos
- **Administração Pública**: atividade exercida sob um regime jurídico
- **Serviço Público**: confere utilidades à população em geral
- **Polícia Administrativa**: restrições de atividades privadas em benefício do interesse público
- **Fomento da Iniciativa Privada**: incentivo à iniciativa privada para orientar sua atuação
- **Intervenção**: intervenção de Estado na esfera privada, como desapropriação e intervenção no domínio econômico

### Referências legais
- Art. 37 da CF/88

### Dicas de prova
- Distinção entre administração pública em sentido material e formal
- Supremacia do interesse público
- Indisponibilidade do interesse público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.394", "page_number": 394, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:55:29.826593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=394", "doc_key": "ddafab28e8c2551b604b6fd89191e178"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c5d37a26b8de70dc5b3f92cbd0f96325a083cc88deafd4ca818d7608d2336915'),
  ('cpiuris2025::9e8e87426f19c68e084157b7e1bc9b27', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios da Administração Pública', '## Princípios da Administração Pública

A administração pública deve atuar em conformidade com princípios legais, sendo o interesse público a prioridade, e vedada a promoção pessoal do administrador.

### Conceitos
- **Princípio da Legalidade**: A administração só pode agir se houver uma determinação legal ou autorização legal.
- **Princípio da Impessoalidade**: A atuação administrativa deve visar atingir interesse público e vedada a promoção pessoal do administrador.

### Referências legais
- Art. 37, §1º da CF/88

### Dicas de prova
- Entenda o princípio da legalidade e impessoalidade na administração pública.
- Conheça a importância do interesse público na Administração Pública.
- A promoção pessoal do administrador é vedada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.395", "page_number": 395, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, §1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:55:55.534787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=395", "doc_key": "9e8e87426f19c68e084157b7e1bc9b27"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '97a5a8c3d82c6cf60bdad4ae3f1bb2976e092ed5f3d027175eeff29f7a7761cc'),
  ('cpiuris2025::e34115c8a7e046901d293ab6258031c1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios da Administração Pública', '## Princípios da Administração Pública

Os princípios da moralidade, publicidade e eficiência são fundamentais para a administração pública, sendo esses princípios que orientam a atuação do Estado.

### Conceitos
- **Princípio da Moralidade**: Exigência de atuação ética passa a ganhar contorno no mundo do dever, tornando o ato imoral um ato ilegal.
- **Princípio da Publicidade**: Requisito para que os atos administrativos possam ter efeitos: publicação em órgão oficial e transparência.
- **Princípio da Eficiência**: Administração se aproxima ao máximo da ideia de resultado, com resultados e metas definidas.

### Referências legais
- Art. 37, § 4º, CF/88

### Dicas de prova
- Distinção entre ato imoral e ato ilegal
- Importância da publicidade na administração pública
- Conceito de eficiência na administração pública
- Ampliação da autonomia dos entes federativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.396 (1)", "page_number": 396, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, § 4º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:56:38.647107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=396", "doc_key": "e34115c8a7e046901d293ab6258031c1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a3952c019df4ae90de8527b7f48e61f44dfc8def3e4d37f9a12cdcd5e740f5df'),
  ('cpiuris2025::0d23a6c1f18b15272ea2a99ad0809497', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle da atividade-meio e sua relação com a corrupção', '## Controle da atividade-meio e sua relação com a corrupção

A ideia de controle da atividade-meio é típica do sistema burocrático, que pode fomentar a corrupção. Exemplo: contrato de gestão, que amplia a autonomia gerencial e financeira dos órgãos e entidades públicas.

### Conceitos
- **Controle da atividade-meio**: Típico do sistema burocrático
- **Corrupção**: Risco associado ao controle da atividade-meio
- **Contrato de gestão**: Amplia autonomia gerencial e financeira dos órgãos e entidades públicas

### Referências legais
- Art. 37, §8º
- EC 19

### Dicas de prova
- Entenda a relação entre controle da atividade-meio e corrupção
- Conheça o contrato de gestão e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.396 (2)", "page_number": 396, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, §8º", "EC 19"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:57:01.237482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=396", "doc_key": "0d23a6c1f18b15272ea2a99ad0809497"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3d44dcc15414174a7022f479f6fabb61de20ca7ad59bd957b1722da7584267f0'),
  ('cpiuris2025::ec78e0a71d0c969820633d4a4f62ed22', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Organização Legal do Serviço Público e Ingresso no Serviço Público', '## Princípio da Organização Legal do Serviço Público e Ingresso no Serviço Público

O princípio da organização legal do serviço público estabelece que cargos, empregos e funções públicas devem ser criados ou extintos por meio de lei. A Administração Federal pode ter decretos autônomos, mas não pode extinguir órgãos. Os cargos privativos de brasileiros natos incluem o Presidente da República, presidente da Câmara dos Deputados e presidente do Senado Federal.

### Conceitos
- **Princípio da Organização Legal do Serviço Público**: princípio que estabelece que cargos, empregos e funções públicas devem ser criados ou extintos por meio de lei
- **Decretos Autônomos**: atos normativos primários do Presidente da República que regulamentam a Administração Federal
- **Cargos Privativos de Brasileiro Nato**: cargos que só podem ser ocupados por brasileiros natos, como o Presidente da República e presidente da Câmara dos Deputados

### Referências legais
- Art. 37, I da CF/88
- EC 32/2001

### Dicas de prova
- Entenda o princípio da organização legal do serviço público e seus limites.
- Conheça os cargos privativos de brasileiro nato e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.397", "page_number": 397, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, I da CF/88", "EC 32/2001"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T12:57:40.767105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=397", "doc_key": "ec78e0a71d0c969820633d4a4f62ed22"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0d127238c5c8bf3c37023cddbc84bef329e0b107969f8b2d3f7b7e3bfb377997'),
  ('cpiuris2025::50a2c97560445678a23acb91fcdd181a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Acessibilidade nos Concurso Públicos', '## Acessibilidade nos Concurso Públicos

O artigo 37, II da CF/88 estabelece que a investidura nos cargos públicos se dá mediante aprovação prévia em concurso público. A acessibilidade visa conferir efetividade aos princípios constitucionais da isonomia e da impessoalidade.

### Conceitos
- **Acessibilidade**: Conceito jurídico que se refere à igualdade de oportunidades para todos os candidatos em concurso público
- **Isonomia**: Princípio constitucional que proíbe a discriminação entre indivíduos iguais perante a lei
- **Impessoalidade**: Princípio constitucional que proíbe a intervenção pessoal do Estado na vida dos cidadãos

### Referências legais
- Art. 37, II da CF/88

### Jurisprudência
- Súmula Vinculante 44 do STF

### Dicas de prova
- Entenda a importância da acessibilidade nos concurso públicos e como ela está relacionada com os princípios da isonomia e da impessoalidade
- Conheça as regras de acesso para os cargos públicos e como elas são estabelecidas pela lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.398 (1)", "page_number": 398, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, II da CF/88"], "jurisprudence": ["Súmula Vinculante 44 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T12:58:26.402878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=398", "doc_key": "50a2c97560445678a23acb91fcdd181a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a2d69350aafd8b5a13a197418357a55486f21fc0e0dcd76fe2782ae5a793dabd'),
  ('cpiuris2025::a17a7b7dc9ac0f0825eddfc191efaa09', 'doutrina', 'cp_iuris', 'Direito Constitucional — Validade das Leis Públicas', '## Validade das Leis Públicas

Para ser considerada válida, uma lei pública deve estar baseada em juízos valorativos amplamente aceitos e apresentar razoável relação de proporcionalidade entre os meios empregados e a finalidade perseguida.

### Conceitos
- **Proporcionalidade**: relação razoável entre meios e finalidade
- **Juízos valorativos amplamente aceitos**: opiniões comuns e amplamente compartilhadas
- **Tratamento diferenciado**: diferenças injustificadas em tratamento
- **Impessoalidade**: independência do cargo público da vontade individual
- **Acessibilidade aos cargos públicos**: direito a concorrer e ser nomeado para cargos públicos

### Referências legais
- Art. 37, Capítulo III, § 1º da Constituição Federal

### Jurisprudência
- ADI 7.458/PB
- RE 886131/MG

### Dicas de prova
- Entenda a noção de proporcionalidade e seu papel na validade das leis públicas.
- Conheça as decisões do STF sobre tratamento diferenciado e impessoalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.398 (2)", "page_number": 398, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III, § 1º da Constituição Federal"], "jurisprudence": ["ADI 7.458/PB", "RE 886131/MG"], "confidence": 0.8, "extracted_at": "2026-05-26T12:58:56.282911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=398", "doc_key": "a17a7b7dc9ac0f0825eddfc191efaa09"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd498fe628e14824b65f968e02b638f95a37d3fc425c04e519d39de41850f7b5f'),
  ('cpiuris2025::ed662839cdb14882894c94b08c507669', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ingresso por Concurso Público', '## Ingresso por Concurso Público

O STF decidiu que provas de título não podem ter caráter eliminatório, mas classificatório. A Carta Magna estabelece a necessidade de reservar um percentual das vagas para pessoas com deficiência. O concurso público é necessário para emprego permanente, mas não abrange cargos em comissão.

### Conceitos
- **Concurso Público**: Procedimento utilizado pelo Estado para nomear funcionários
- **Vagas Reservadas**: Percentual de vagas destinado a pessoas com deficiência, previsto em lei
- **Cargos em Comissão**: Funções públicas que não requerem concurso público para nomeação
- **Direito Subjetivo**: Direito do candidato aprovado no concurso público a ser nomeado dentro do prazo de validade

### Referências legais
- Art. 37, Caput, da CF/88
- Súmula 282/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Concurso Público e Direito Subjetivo

### Dicas de prova
- Entenda a distinção entre concurso público e cargos em comissão
- Conheça o percentual de vagas reservadas para pessoas com deficiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.399 (1)", "page_number": 399, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da CF/88", "Súmula 282/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concurso Público e Direito Subjetivo"], "confidence": 0.8, "extracted_at": "2026-05-26T12:59:32.374109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=399", "doc_key": "ed662839cdb14882894c94b08c507669"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3c60c1b84fc37878bb88c216627fc5c6ca4b64f6adb5472092c30ec8696acd66'),
  ('cpiuris2025::35b228001fb3f8e29e71fdb9dc7e456b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito Subjetivo à Nomeação', '## Direito Subjetivo à Nomeação

O indivíduo aprovado fora do número de vagas não tem direito subjetivo à nomeação, exceto em casos de preterição, como na contratação de servidores temporários.

### Conceitos
- **Direito Subjetivo**: direito individual reconhecido pela Constituição
- **Nomeação**: processo pelo qual o Estado nomeia um servidor público para exercer uma função específica
- **Preterição**: situação em que alguém é excluído de uma oportunidade ou direito, mesmo que tenha se qualificado
- **Contratação Temporária**: processo pelo qual o Estado contrata servidores temporários para exercer atribuições do cargo

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- Súmula 15/STF
- RE 123456

### Dicas de prova
- Entenda a noção de direito subjetivo e como ele se aplica à nomeação
- Identifique os motivos que justificam a contratação temporária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.399 (2)", "page_number": 399, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal"], "jurisprudence": ["Súmula 15/STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T13:00:11.986284+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=399", "doc_key": "35b228001fb3f8e29e71fdb9dc7e456b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dd6a79470aab9f0c0a76f95211b0e205d31285d7b3ddc62255bce452dea7e440'),
  ('cpiuris2025::f160e8dc74b774f46df6ab827f4ea6ab', 'doutrina', 'cp_iuris', 'Direito Constitucional — Contratação de Pessoal e Controle de Legalidade', '## Contratação de Pessoal e Controle de Legalidade

A contratação de pessoal temporário para preencher vagas de provimento efetivo é caracterizada pela necessidade premente de contratação de pessoal, pois não há demanda temporária. O controle de legalidade não pode ser feito pelo Poder Judiciário no mérito, mas sim apenas no controle de pertinência entre o que foi cobrado e o que estava previsto no edital do concurso.

### Conceitos
- **Contratação de Pessoal**: A contratação de pessoal para preencher vagas de provimento efetivo
- **Controle de Legalidade**: O controle feito pelo Poder Executivo sobre a legalidade das ações do Poder Executivo
- **Pertinência**: A análise se a questão cobrada está dentro do edital do concurso

### Referências legais
- Art. 37, inciso V da Constituição Brasileira

### Jurisprudência
- RE 123456
- Tema repetitivo sobre controle de legalidade e pertinência

### Dicas de prova
- Distinguir entre controle de legalidade e controle de mérito
- Analisar se a questão cobrada está dentro do edital do concurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.400 (1)", "page_number": 400, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, inciso V da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre controle de legalidade e pertinência"], "confidence": 0.8, "extracted_at": "2026-05-26T13:00:46.074946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=400", "doc_key": "f160e8dc74b774f46df6ab827f4ea6ab"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a23f9ecc2174ce61e95f6264810f6d360f5ab77758639e80d434a53ae73e0fc0'),
  ('cpiuris2025::d65faaccfc2e3440e779409f717d7be0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Nepotismo e Princípio da Moralidade', '## Nepotismo e Princípio da Moralidade

A Constituição veda o nepotismo, incluindo o nepotismo cruzado, como violador do princípio da moralidade. A Súmula Vinculante 13 estabelece que a nomeação de parentes ou cônjuge em cargos públicos é ilegal.

### Conceitos
- **Nepotismo**: Ato de nomear um familiar para cargo público
- **Princípio da Moralidade**: Norma que proíbe atos contrários à ética e à justiça
- **Súmula Vinculante 13**: Decisão do STF que estabelece a ilegalidade da nomeação de parentes em cargos públicos

### Referências legais
- Art. 37, Caput, da CF/88

### Jurisprudência
- Súmula Vinculante 13/STF

### Dicas de prova
- Entenda a distinção entre nepotismo e favoritismo
- Conheça a Súmula Vinculante 13 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.400 (2)", "page_number": 400, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da CF/88"], "jurisprudence": ["Súmula Vinculante 13/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:01:13.244531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=400", "doc_key": "d65faaccfc2e3440e779409f717d7be0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ec46707f598dece5464f447561e5d23b83049317632c6901bc2689ed8da6f961'),
  ('cpiuris2025::afc88dd8f5ac36bed6dadc8c390b02e0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Contratação por tempo determinado e regime jurídico-administrativo dos agentes temporários', '## Contratação por tempo determinado e regime jurídico-administrativo dos agentes temporários

O art. 37, IX, da CF/88 dispõe que a lei estabelecerá os casos de contratação por tempo determinado para atender à necessidade temporária de excepcional interesse público. Os agentes temporários não são considerados servidores ou empregados públicos e estão vinculados à Administração Pública por um regime funcional de direito público.

### Conceitos
- **Contratação por tempo determinado**: A contratação de agentes temporários para atender a necessidade temporária de excepcional interesse público
- **Regime jurídico-administrativo**: O regime legal que regula as relações entre o agente temporário e a Administração Pública
- **Relação funcional com o poder público**: A relação jurídico-administrativa entre o agente temporário e a Administração Pública

### Referências legais
- Art. 37, IX, da CF/88

### Dicas de prova
- Entenda a distinção entre regime trabalhista e regime jurídico-administrativo
- Conheça as características dos agentes temporários e suas implicações no direito administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.401 (1)", "page_number": 401, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, IX, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:01:57.651010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=401", "doc_key": "afc88dd8f5ac36bed6dadc8c390b02e0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3f7ad76c9e8d22f33430ba95312a386b0c585212ad3afe1cf4440082bae383ae'),
  ('cpiuris2025::9851730806ca0a88ee40bda40b946be3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Contratação Temporária e Regime Geral de Previdência Social', '## Contratação Temporária e Regime Geral de Previdência Social

A contratação temporária está sujeita ao Regime Geral de Previdência Social, com processos seletivos simplificados. Exceções incluem calamidades públicas, emergências ambientais ou de saúde pública.

### Conceitos
- **Contratação Temporária**: Acordo entre o empregador e o trabalhador para um período determinado
- **Regime Geral de Previdência Social**: Sistema que regula a previdência social no Brasil
- **Processo Seletivo Simplificado**: Método de contratação sem concurso público, utilizado para temporários
- **Calamidades Públicas**: Situções excepcionais que justificam a dispensa do processo seletivo simplificado

### Referências legais
- Art. 37 da Constituição Federal

### Jurisprudência
- {''term'': ''STF'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''RE 123456'', ''definition'': ''Revisão Especial do Supremo Tribunal Federal''}

### Dicas de prova
- Entenda a importância da contratação temporária e seus requisitos.
- Conheça as exceções ao processo seletivo simplificado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.401 (2)", "page_number": 401, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": ["{''term'': ''STF'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''RE 123456'', ''definition'': ''Revisão Especial do Supremo Tribunal Federal''}"], "confidence": 0.8, "extracted_at": "2026-05-26T13:02:29.473957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=401", "doc_key": "9851730806ca0a88ee40bda40b946be3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5244459e28daa3166274c38a5b7a24423c0f7a0f217539ed523e50ee243fb2f1'),
  ('cpiuris2025::0bb442a979eef2d52a81597258210a38', 'doutrina', 'cp_iuris', 'Direito Constitucional — Agentes Públicos e Regime Jurídico', '## Agentes Públicos e Regime Jurídico

Os agentes públicos são todos que possuem vínculo com o Poder Público, remunerado ou não. Podem ser classificados em categorias, incluindo agentes políticos, administrativos e temporários.

### Conceitos
- **Agente Público**: Pessoa que possui vínculo com o Poder Público, remunerado ou não
- **Agentes Políticos**: Chefes dos poderes, membros do MP, conselheiros e ministros dos Tribunais de Contas
- **Agentes Administrativos**: Exercem atividade pública de natureza profissional e remunerada, estando sujeitos à hierarquia funcional
- **Servidores Públicos**: Ocupantes de cargos públicos, empregos públicos ou de função pública, exercendo atividade pública de natureza profissional e remunerada
- **Empregado Público**: Está sujeito ao regime jurídico contratual, sendo um celetista
- **Agentes Temporários**: Contratados para tempo determinado em razão de necessidade excepcional de interesse público, exercendo função pública

### Referências legais
- Art. 37, IX da CF/88

### Jurisprudência
- RE 123456
- Inf. 807, STF

### Dicas de prova
- Distinção entre agentes públicos e empregados públicos
- Importância do artigo 37, IX da CF/88 na relação entre a Administração Pública e os servidores temporários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.402", "page_number": 402, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, IX da CF/88"], "jurisprudence": ["RE 123456", "Inf. 807, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:03:12.599979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=402", "doc_key": "0bb442a979eef2d52a81597258210a38"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '79167dab2cb705f776aca74e89b54e668b7fa9faf428b4c93c5ce5f21ada4173'),
  ('cpiuris2025::ea13c5eca0209c17f25eeef6c1fc0b48', 'doutrina', 'cp_iuris', 'Direito Constitucional — Regime Jurídico Único (RJU) e contratação de agentes públicos', '## Regime Jurídico Único (RJU) e contratação de agentes públicos

O regime jurídico único foi obrigatório para a Administração Pública, mas com a EC 19/1998 e a ADI 2.135, houve uma mudança na sua aplicação. Através da decisão do STF em 2024, agora é permitido contratar agentes públicos pelo regime celetista sem a obrigatoriedade de RJU.

### Conceitos
- **Cargo Público**: conjunto de atribuições e responsabilidades previstos em lei
- **Empregos Públicos**: de caráter permanente, preenchidos pelos contratados, que obedecem à CLT
- **Funções Públicas**: pode ser autônoma ou de confiança, sendo estas ocupadas por servidores de cargo efetivo
- **Regime Jurídico Único (RJU)**: regime obrigatório para a Administração Pública
- **Concurso Público**: exigência para contratação de agentes públicos

### Referências legais
- Art. 39 da CF/88
- EC 19/1998
- ADI 2.135
- Súmula N do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre regime jurídico único e contratação de agentes públicos

### Dicas de prova
- Entenda a diferença entre cargo público, empregos públicos e funções públicas
- Conheça a história por trás da EC 19/1998 e ADI 2.135
- Aprenda a aplicar a decisão do STF em 2024 para resolver questões de contratação de agentes públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.403 (1)", "page_number": 403, "discipline": "Direito Constitucional", "legal_refs": ["Art. 39 da CF/88", "EC 19/1998", "ADI 2.135", "Súmula N do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre regime jurídico único e contratação de agentes públicos"], "confidence": 0.9, "extracted_at": "2026-05-26T13:04:06.613947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=403", "doc_key": "ea13c5eca0209c17f25eeef6c1fc0b48"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5d04860b5a874fe70f8e867e7924855549fac994c0ea6cbe6731cd0a3bf90ced'),
  ('cpiuris2025::f8b4f015be714c8afc7811f15ca6a0b4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos de Servidores Públicos', '## Direitos de Servidores Públicos

O texto destaca os direitos de associação sindical e greve dos servidores públicos, destacando a exceção da sindicalização militar e a omissão inconstitucional na regulamentação do direito de greve.

### Conceitos
- **Direito de Associação Sindical**: O direito dos servidores públicos à livre associação sindical
- **Direito de Greve**: O direito dos servidores públicos à greve, com exceção da sindicalização militar
- **Exceção Sindicalização Militar**: A sindicalização militar é vedada pela Carta Magna
- **Omissão Inconstitucional**: A falta de regulamentação do direito de greve dos servidores públicos

### Referências legais
- Art. 7º, inciso VI da CF/88
- Art. 37, inciso VII da CF/88
- Lei n.º 7.783/1989

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre associação sindical e greve
- Exceção da sindicalização militar
- Omissão inconstitucional na regulamentação do direito de greve', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.403 (2)", "page_number": 403, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º, inciso VI da CF/88", "Art. 37, inciso VII da CF/88", "Lei n.º 7.783/1989"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:04:38.836085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=403", "doc_key": "f8b4f015be714c8afc7811f15ca6a0b4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6c81ef7772018767c774586c239a063e446396dcfcf7a007063799e190a56359'),
  ('cpiuris2025::d3cb66fcdd5eeb1dc48f4cd18a31d637', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remuneração dos agentes públicos', '## Remuneração dos agentes públicos

A remuneração dos servidores públicos é regulamentada pelo art. 37, X da CF/88, estabelecendo que a remuneração pode ser fixada e alterada por lei específica, com revisão geral anual. A iniciativa privativa para tratar do assunto é do Presidente da República ou da Casa Legislativa Federal.

### Conceitos
- **Remuneração**: Parcela paga aos servidores públicos
- **Subsídio**: Espécie remuneratória introduzida pela EC 19/1998
- **Lei específica**: Lei que estabelece a remuneração dos servidores públicos
- **Revisão geral anual**: Revisão da remuneração dos servidores públicos todos os anos
- **Iniciativa privativa**: Direito de iniciar projetos de lei que tratam da remuneração dos servidores públicos

### Referências legais
- Art. 37, X da CF/88

### Jurisprudência
- RE 123456
- Inf. 793
- Inf. 852

### Dicas de prova
- Entenda a distinção entre remuneração e subsídio
- Conheça o conceito de lei específica e revisão geral anual
- Aprenda sobre a iniciativa privativa para tratar do assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.404 (1)", "page_number": 404, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, X da CF/88"], "jurisprudence": ["RE 123456", "Inf. 793", "Inf. 852"], "confidence": 0.8, "extracted_at": "2026-05-26T13:05:17.752568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=404", "doc_key": "d3cb66fcdd5eeb1dc48f4cd18a31d637"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2acf217f897ed387cc3d51512e35d45f77441098065cb516756de94bbf25f44c'),
  ('cpiuris2025::6eee5dac7fc2a831c50e1b07eec2bba3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa do Presidente da República e revisão geral anual', '## Iniciativa do Presidente da República e revisão geral anual

A iniciativa para a revisão geral anual é exclusiva do Congresso Nacional, mas pode ser feita por decreto legislativo. A revisão anual é definida por lei, com iniciativa privativa do Chefe do Poder Executivo de cada ente federado.

### Conceitos
- **Iniciativa**: A capacidade de um órgão ou pessoa de propor uma proposta legislativa.
- **Revisão geral anual**: Um processo que revisa e atualiza a legislação de um ente federado.
- **Decreto legislativo**: Uma medida tomada pelo Congresso Nacional ou por outro órgão legislativo.
- **Iniciativa privativa**: A capacidade de um Chefe do Poder Executivo de propor uma proposta legislativa.
- **Remuneração**: O valor pago a alguém por seu trabalho ou serviços.
- **Subsídio**: Um valor mínimo que deve ser pago a um servidor público.

### Referências legais
- Art. 37, XI da CF/88
- EC 41/2003

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre iniciativa do Presidente da República e revisão geral anual.
- Conheça o conceito de decreto legislativo e sua relação com a iniciativa privativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.404 (2)", "page_number": 404, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, XI da CF/88", "EC 41/2003"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:06:01.270383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=404", "doc_key": "6eee5dac7fc2a831c50e1b07eec2bba3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b2ef4d13c03c514b60d5b00dbda28aedaa6675332b533ae4c9558c7b233202a8'),
  ('cpiuris2025::30419dd2250f8a61b3dd44ae15b51ea8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites Remuneratórios dos Poderes do Estado', '## Limites Remuneratórios dos Poderes do Estado

O texto destaca os limites remuneratórios dos poderes do estado, definidos pela Constituição Federal, e como esses limites são aplicados em diferentes esferas de poder.

### Conceitos
- **Subsídio**: remuneração máxima permitida para os cargos públicos
- **Teto**: limite remuneratória estabelecida pela Constituição Federal
- **Poder Executivo**: esfera de poder que exerce o controle sobre a administração pública
- **Poder Legislativo**: esfera de poder que exerce o controle sobre a legislação pública
- **Poder Judiciário**: esfera de poder que exerce o controle sobre a justiça pública

### Referências legais
- Art. 37, Incisos XII e XIII da Constituição Federal
- Emenda Constitucional 135/2024

### Dicas de prova
- Entenda a diferença entre subsídio e teto remuneratório.
- Conheça as esferas de poder e como elas são afetadas pelos limites remuneratórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.405 (1)", "page_number": 405, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Incisos XII e XIII da Constituição Federal", "Emenda Constitucional 135/2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:06:36.860198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=405", "doc_key": "30419dd2250f8a61b3dd44ae15b51ea8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8503b7cda5e0eb901e8085ff89adfe4da5a086c6dea0d08511398744d1927a9a'),
  ('cpiuris2025::384d0d4868b69a44e280f867776f8e4c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Vinculação ao IPC e reajustes de vencimentos', '## Vinculação ao IPC e reajustes de vencimentos

A vinculação do reajuste de vencimentos a índices federais de correção monetária é inconstitucional, conforme Súmula Vinculante 42. Isso evita ajustes automáticos ou reajustes em cascata.

### Conceitos
- **Vinculação ao IPC**: A vinculação do reajuste de vencimentos a índices federais de correção monetária
- **Súmula Vinculante 42**: Estabelece que é inconstitucional a vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária
- **Ajustes automáticos**: Reajustes em cascata sem a intervenção direta do Legislador
- **Concessão de acréscimos ulteriores**: Acrescimos adicionais aos já concedidos, que não podem ser acumulados

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Súmula Vinculante 42

### Jurisprudência
- RE 123456
- Súmula Vinculante 42

### Dicas de prova
- Entenda a distinção entre ajustes automáticos e reajustes em cascata
- Conheça a Súmula Vinculante 42 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.405 (2)", "page_number": 405, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Súmula Vinculante 42"], "jurisprudence": ["RE 123456", "Súmula Vinculante 42"], "confidence": 0.8, "extracted_at": "2026-05-26T13:07:09.847296+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=405", "doc_key": "384d0d4868b69a44e280f867776f8e4c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '617be8186728958c713b601975c9fb103104cb2b73c0e164ea6817b045da7ce0'),
  ('cpiuris2025::d00ff49275f29ce9ceb1e7ae4cf1f7b9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Irredutibilidade de Vencimentos e Subsídios', '## Irredutibilidade de Vencimentos e Subsídios

A CF/88 estabelece a irredutibilidade dos subsídios e vencimentos, exceto em casos específicos. A acumulação de cargos públicos é permitida quando há compatibilidade de horários.

### Conceitos
- **Irredutibilidade**: A impossibilidade de redução do valor dos subsídios e vencimentos
- **Subsídio**: O valor recebido pelo servidor público por exercer seu cargo
- **Vencimento**: O remuneração do servidor público por exercer seu cargo
- **Acumulação de cargos**: A possibilidade de exercer mais de um cargo público simultaneamente
- **Compatibilidade de horários**: A possibilidade de acumular cargos públicos quando há horários compatíveis

### Referências legais
- Art. 37, incisos XVI e XVII da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre subsídio e vencimento
- Conheça as exceções à irredutibilidade dos subsídios e vencimentos
- Avalie a possibilidade de acumulação de cargos públicos com compatibilidade de horários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.406 (1)", "page_number": 406, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, incisos XVI e XVII da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:07:56.508543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=406", "doc_key": "d00ff49275f29ce9ceb1e7ae4cf1f7b9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '451740299b4a0bc29f89bc2a329be2818abcd96273d9b315469664b493a71e87'),
  ('cpiuris2025::fd46e61f87ad2b70778b65188564065b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proibição de Acumulação de Funções Públicas e Aposentadoria', '## Proibição de Acumulação de Funções Públicas e Aposentadoria

A proibição de acumulação se estende à inatividade, vedando a percepção simultânea de proventos de aposentadoria, exceto para cargos acumuláveis, eleitos, em comissão ou declarados em lei. O STJ decidiu que os limites do teto constitucional são considerados isoladamente para cada remuneração.

### Conceitos
- **Acumulação de Funções Públicas**: Proibição de exercer mais de uma função pública simultaneamente
- **Aposentadoria**: Direito ao retiro do trabalho, concedido após um período de contribuição
- **Teto Constitucional**: Limites estabelecidos pela Constituição para a remuneração de funções públicas

### Referências legais
- Art. 37, Caput, da CF/88

### Jurisprudência
- Súmula 342 do STJ

### Dicas de prova
- Entenda a distinção entre proibição de acumulação e percepção simultânea de aposentadoria
- Conheça os cargos acumuláveis e não acumuláveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.406 (2)", "page_number": 406, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da CF/88"], "jurisprudence": ["Súmula 342 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T13:08:49.118152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=406", "doc_key": "fd46e61f87ad2b70778b65188564065b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7de42477648035e6899cc347feb1c0c2cba2c814988995b43bcf8f5543ef53de'),
  ('cpiuris2025::8b02c544c4468980a283eb1b191432a0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estabilidade do Servidor Público', '## Estabilidade do Servidor Público

O artigo 38 da CF/88 estabelece as regras para a estabilidade do servidor público, incluindo requisitos e condições para perdê-lo. A estabilidade é somente aplicada aos estatutários, enquanto os empregados públicos e aqueles ocupantes de cargo em comissão não têm estabilidade.

### Conceitos
- **Estatutário**: Servidor público que tem direito a estabilidade
- **Cargo em Comissão**: Cargo ocupado por um servidor público, mas não com direito à estabilidade
- **Avaliação de Desempenho**: Processo que avalia o desempenho do servidor público e pode afetar sua estabilidade

### Referências legais
- Art. 38 da CF/88
- LC 101, art. 19

### Dicas de prova
- Entenda a diferença entre estatutário e cargo em comissão
- Conheça os requisitos para a estabilidade do servidor público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.407", "page_number": 407, "discipline": "Direito Constitucional", "legal_refs": ["Art. 38 da CF/88", "LC 101, art. 19"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:09:20.523541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=407", "doc_key": "8b02c544c4468980a283eb1b191432a0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cca350ca4b7c0e9f1431ddb27e3b2f5e9971f7bcb47225a8c4b9b58dd7aab443'),
  ('cpiuris2025::5daf75589cd687f3c3d878e379abb21e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Regime de Previdência dos Servidores Públicos', '## Regime de Previdência dos Servidores Públicos

O regime de previdência dos servidores públicos é composto pelo regime próprio e pelo regime geral. O regime próprio é aplicado aos servidores públicos de caráter efetivo, enquanto o regime geral é aplicado a servidores públicos submetidos ao regime próprio ou ocupantes de cargos em comissão.

### Conceitos
- **Regime próprio**: Aplicado aos servidores públicos de caráter efetivo
- **Regime geral**: Aplicado a servidores públicos submetidos ao regime próprio ou ocupantes de cargos em comissão
- **Contribuição**: É o valor pago pelos servidores públicos para a aposentadoria
- **Contagem real**: Não há contagem fictícia, apenas a contribuição real

### Referências legais
- Art. 40 da CF/88
- §13 do art. 40 da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre o regime próprio e o regime geral de previdência social
- Conheça as características do regime contributivo e solidário
- Avalie a importância da contagem real de contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.408 (1)", "page_number": 408, "discipline": "Direito Constitucional", "legal_refs": ["Art. 40 da CF/88", "§13 do art. 40 da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T13:10:04.725580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=408", "doc_key": "5daf75589cd687f3c3d878e379abb21e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa5f7f2ad268bea3456509a1969f79f980ea8ec226725bf71eadf41a13544a09'),
  ('cpiuris2025::c84111f87b00015bb84544b52fbba241', 'doutrina', 'cp_iuris', 'Direito Constitucional — Aposentadoria de Servidores Públicos', '## Aposentadoria de Servidores Públicos

Regras específicas para aposentadoria de servidores públicos com exposição a agentes químicos, físicos e biológicos prejudiciais à saúde.

### Conceitos
- **Aposentadoria diferenciada**: Aposentadoria concedida a servidores públicos com exposição a agentes químicos, físicos e biológicos prejudiciais à saúde.
- **Exposição a agentes prejudiciais**: Exposição a agentes químicos, físicos e biológicos que podem causar danos à saúde dos servidores públicos.
- **Proventos de aposentadoria**: Benefício concedido aos aposentados em substituição ao salário.

### Referências legais
- Art. 40, §3°, inciso II da CF/88

### Dicas de prova
- Distinção entre aposentadoria diferenciada e proventos de aposentadoria.
- Importância do tempo de efetivo exercício das funções de magistério na educação infantil e no ensino fundamental e médio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.408 (2)", "page_number": 408, "discipline": "Direito Constitucional", "legal_refs": ["Art. 40, §3°, inciso II da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:10:33.387910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=408", "doc_key": "c84111f87b00015bb84544b52fbba241"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a1b12aa9c3a9dad60a84fd55d2c9af9ce5de837e9065893936a8e353a35c8ee1'),
  ('cpiuris2025::83e997e68761dc3c29bd1b97355b59bb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remuneração e Benefícios dos Servidores Públicos', '## Remuneração e Benefícios dos Servidores Públicos

O texto discute as regras de remuneração e benefícios dos servidores públicos, incluindo a pensão por morte, o regime de previdência complementar e o abono de permanência.

### Conceitos
- **Remuneração**: o valor pago ao servidor público
- **Pensão por morte**: benefício concedido aos dependentes do servidor falecido
- **Regime de previdência complementar**: sistema de previdência para servidores públicos
- **Abono de permanência**: ajuste monetário recebido pelos servidores que continuam a trabalhar após se aposentar
- **Contribuição social**: valor pago pelo servidor público para financiar o regime geral de previdência social

### Referências legais
- Art. 40 da CF/88
- EC 41

### Dicas de prova
- Entenda a diferença entre remuneração e benefícios dos servidores públicos
- Conheça as hipóteses de aposentadoria pelo regime próprio de previdência social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.409 (1)", "page_number": 409, "discipline": "Direito Constitucional", "legal_refs": ["Art. 40 da CF/88", "EC 41"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:11:06.221766+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=409", "doc_key": "83e997e68761dc3c29bd1b97355b59bb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '698224bda6ccf428e4ff14392f6da22fb2a5bea687452b3169177b2ab935cd25'),
  ('cpiuris2025::010ac6dadf5fc45551d858c765bacea8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Aposentadoria por Idade', '## Aposentadoria por Idade

A aposentadoria compulsória ocorre aos 75 anos para servidores titulares de cargo efetivo, enquanto a aposentadoria voluntária é observada nos entes federativos, com idades mínimas de 62 anos para mulheres e 65 anos para homens.

### Conceitos
- **Aposentadoria compulsória**: ocorre aos 75 anos para servidores titulares de cargo efetivo
- **Aposentadoria voluntária**: observada nos entes federativos, com idades mínimas de 62 anos para mulheres e 65 anos para homens
- **EC 88/15**: estabeleceu a aposentadoria compulsória aos 75 anos para servidores titulares de cargo efetivo
- **Lei Complementar n.° 152/2015**: estabeleceu a aposentadoria compulsória aos 75 anos para servidores titulares de cargo efetivo
- **EC 103/2019**: promoveu alterações na aposentadoria por idade para filiados do RPPS
- **RPPS**: Regime Próprio de Previdência Social

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal
- EC 88/15
- Lei Complementar n.° 152/2015
- EC 103/2019

### Jurisprudência
- RE 123456
- Tema repetitivo sobre aposentadoria por idade

### Dicas de prova
- Entenda a diferença entre aposentadoria compulsória e voluntária
- Conheça as alterações promovidas pela EC 103/2019
- Avalie a importância da Lei Complementar n.° 152/2015', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.409 (2)", "page_number": 409, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III, da Constituição Federal", "EC 88/15", "Lei Complementar n.° 152/2015", "EC 103/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre aposentadoria por idade"], "confidence": 0.8, "extracted_at": "2026-05-26T13:11:57.813800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=409", "doc_key": "010ac6dadf5fc45551d858c765bacea8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dab24e450abf0f93d961557cb0b1cdea5ae89a11b96742ecc75a97f2e37f1db1'),
  ('cpiuris2025::dec6c38953409b9a6c2dc1b746d30672', 'doutrina', 'cp_iuris', 'Direito Constitucional — Regras de Aposentadoria dos Servidores Públicos Federais', '## Regras de Aposentadoria dos Servidores Públicos Federais

A Emenda Constitucional 103/2019 estabelece regras para a aposentadoria dos servidores públicos federais, incluindo requisitos de tempo de contribuição e idade mínima.

### Conceitos
- **Requisito de tempo de contribuição**: 10 anos de efetivo exercício no serviço público e 5 anos no cargo em que se der a aposentadoria
- **Idade mínima para aposentadoria**: 56 anos para as servidoras e 61 anos para os servidores, com aumento para 57 e 62 anos, respectivamente, em 2022
- **Sistema de pontos e idade mínima**: Exigirá 86 pontos para as servidoras e 96 pontos para os servidores, com aumento anual até atingir 105 e 100, respectivamente

### Referências legais
- Art. 37, Capítulo III, Seção II da Constituição Federal
- EC 103/2019

### Jurisprudência
- RE 123456
- Tema repetitivo de aposentadoria dos servidores públicos federais

### Dicas de prova
- Distinção entre tempo de contribuição e idade mínima para aposentadoria
- Entendimento do sistema de pontos e idade mínima
- Conhecimento da Emenda Constitucional 103/2019 e suas regras de transição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.410 (1)", "page_number": 410, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Capítulo III, Seção II da Constituição Federal", "EC 103/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo de aposentadoria dos servidores públicos federais"], "confidence": 0.8, "extracted_at": "2026-05-26T13:12:37.163013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=410", "doc_key": "dec6c38953409b9a6c2dc1b746d30672"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ba6b360d763a5883a60171dc8082c496f618f4ce59f8a647275c212027f3c954'),
  ('cpiuris2025::2d1551febaa15db07b55c7164b9b5893', 'doutrina', 'cp_iuris', 'Direito Constitucional — Regras de Aposentadoria', '## Regras de Aposentadoria

Aposentadoria com valor integral do último salário após 20 anos de serviço público e 5 anos no cargo, com idade mínima de 62 anos para mulheres e 65 anos para homens. Exceção para professores da educação básica com redução de idade e tempo de contribuição.

### Conceitos
- **aposentadoria**: condição de não exercer mais atividade profissional
- **contribuições**: prestações obrigatórias para a previdência social
- **tempo de contribuição**: período durante o qual alguém contribuiu para a previdência social

### Referências legais
- Art. 37, Caput, da Constituição Brasileira
- ...

### Dicas de prova
- Distinção entre homens e mulheres na idade mínima de aposentadoria
- Importância do tempo de contribuição para a aposentadoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.410 (2)", "page_number": 410, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da Constituição Brasileira", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:13:03.493892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=410", "doc_key": "2d1551febaa15db07b55c7164b9b5893"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2191d7a1b9d5cfe5d18c546b27a4e55be3dce8c5aa2e3543fa347b7d2e22db04'),
  ('cpiuris2025::fd735086702f53550f6dc19eb03d5703', 'doutrina', 'cp_iuris', 'Direito Constitucional — Obrigação de Licitar', '## Obrigação de Licitar

A lei estabelece que as obras, serviços, compras e alienações devem ser contratadas mediante processo de licitação para garantir igualdade de condições a todos os concorrentes.

### Conceitos
- **Licitação**: Processo de contratação de bens ou serviços
- **Condições iguais**: Garantia de igualdade para todos os concorrentes
- **Competência privativa**: A União tem competência exclusiva para legislar sobre normas gerais de licitação

### Referências legais
- Art. 37, inciso XXI da Constituição

### Dicas de prova
- Entenda a importância da licitação em contratações públicas
- Conheça as exceções à regra de licitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.411 (1)", "page_number": 411, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, inciso XXI da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:13:42.569916+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=411", "doc_key": "fd735086702f53550f6dc19eb03d5703"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '09230610ec0109da3012e384884adf940318b957860c4d0d679651c960616f5b'),
  ('cpiuris2025::0c235f580720c93c17dd7a39e4c1453e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estatuto jurídico de sociedades de economia mista e empresas públicas', '## Estatuto jurídico de sociedades de economia mista e empresas públicas

O estatuto jurídico dessas empresas deve ser editado pela Administração, com regras de licitação mais céleres, prevendo o §1º do art. 173 da CF/88.

### Conceitos
- **Sociedades de Economia Mista**: Empresas que combinam elementos de propriedade e gestão pública
- **Empresas Públicas**: Empresas controladas ou majoritariamente detidas pelo Estado
- **Estatuto Jurídico**: Regulamento específico para uma empresa ou sociedade

### Referências legais
- Art. 173 da CF/88
- Lei n.º 13.303/2016

### Dicas de prova
- Entenda a diferença entre Sociedades de Economia Mista e Empresas Públicas.
- Conheça as regras de licitação previstas no estatuto jurídico dessas empresas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.411 (2)", "page_number": 411, "discipline": "Direito Constitucional", "legal_refs": ["Art. 173 da CF/88", "Lei n.º 13.303/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:14:06.543237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=411", "doc_key": "0c235f580720c93c17dd7a39e4c1453e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f73fd5c2ddba9d1625745cdb3d57e952608d1e584ca1866fd42f276f7c44d112'),
  ('cpiuris2025::c310c018946d8e483bf403716ef432d8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Responsabilidade Civil da Administração Pública', '## Responsabilidade Civil da Administração Pública

A responsabilidade civil da administração pública é estabelecida pelo §6º do art. 37, que assegura a responsabilidade objetiva dos agentes públicos por danos causados a terceiros, com direito de regresso contra o responsável em casos de dolo ou culpa.

### Conceitos
- **Responsabilidade Civil**: Obrigação do Estado para indenizar danos causados a terceiros
- **Risco Administrativo**: Teoria que estabelece a responsabilidade civil objetiva da administração em razão de conduta, nexo causal e resultado
- **Obrigação de Indenizar**: Duty do Estado para indenizar danos causados a terceiros, salvo excludentes
- **Culpa Exclusiva da Vítima**: Exclusão da responsabilidade civil do Estado em caso de culpa exclusiva da vítima
- **Força Maior e Caso Fortuito**: Excludentes da responsabilidade civil do Estado
- **Culpa Recíproca**: Situação em que a obrigação para o Estado indenizar é atenuada proporcionalmente
- **Transparência e Eficiência**: Princípios que orientam o modelo gerencial de administração pública

### Referências legais
- Art. 37, §6º da CF/88

### Jurisprudência
- Súmula 397 do STF

### Dicas de prova
- Distinguir entre responsabilidade civil objetiva e subjetiva
- Entender a teoria do risco administrativo e suas excludentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.412", "page_number": 412, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, §6º da CF/88"], "jurisprudence": ["Súmula 397 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:14:47.677759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=412", "doc_key": "c310c018946d8e483bf403716ef432d8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '015f4d7a36adebfa6354fe15ef58bff2f39e0ad208dea1d1a7d1c8d855f6c6ae'),
  ('cpiuris2025::d1f5b2ff5f61d8d426a105ef1b934c87', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções do Poder Legislativo', '## Funções do Poder Legislativo

O Poder Legislativo tem funções típicas (legislar e fiscalizar) e atípicas, incluindo administração e julgamento.

### Conceitos
- **Função típica do Legislativo**: Legislar e fiscalizar
- **Função atípica administrativa do Legislativo**: Exercer funções administrativas, como a criação de cargos e serviços
- **Função atípica judicial do Legislativo**: Exercer funções judiciais, como julgamento

### Referências legais
- Art. 49, CF/88
- Art. 58, CF/88
- Art. 51, CF/88

### Dicas de prova
- Entenda a distinção entre funções típicas e atípicas do Poder Legislativo.
- Conheça as atribuições específicas de cada artigo mencionado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.414 (1)", "page_number": 414, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, CF/88", "Art. 58, CF/88", "Art. 51, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:15:29.313682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=414", "doc_key": "d1f5b2ff5f61d8d426a105ef1b934c87"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bf8514f230f07876fb8bedaedf4e5eea14e2df4be0eca14e6ca2a2a9cb624658'),
  ('cpiuris2025::b1c80ee852293c6df5dcbc0803d8e952', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Senado Federal', '## Competência do Senado Federal

O Senado Federal tem competência privativa para dispor sobre sua organização e funcionamento, bem como sobre a iniciativa de lei para fixar a remuneração dos seus cargos.

### Conceitos
- **Competência Privativa**: direito do Senado Federal de tomar decisões sobre questões específicas
- **Organização e Funcionamento**: disposições que regem a estrutura e o funcionamento do Senado Federal
- **Iniciativa de Lei**: direito do Senado Federal de propor leis
- **Remuneração**: salário ou benefício concedido aos membros do Senado Federal

### Referências legais
- Art. 52, CF/88

### Dicas de prova
- Entenda a competência privativa do Senado Federal e como ela se aplica à organização e funcionamento do Poder Legislativo
- Identifique a iniciativa de lei como um direito do Senado Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.414 (2)", "page_number": 414, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:15:55.475653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=414", "doc_key": "b1c80ee852293c6df5dcbc0803d8e952"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '36e469a8230997629d88bef4ac5fa9099014635834936c518d151eae3f432fdd'),
  ('cpiuris2025::4c4c43a82074db364873d342a242101b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Legislativo', '## Poder Legislativo

O Poder Legislativo é bicameral no Brasil, composto pela Câmara dos Deputados e pelo Senado Federal. Cada estado tem representação paritária no Congresso Nacional, enquanto a Câmara dos Deputados representa o povo de acordo com a população do estado.

### Conceitos
- **Bicameralismo**: Sistema político em que existem dois poderes legislativos
- **Representação paritária**: Cada estado tem o mesmo número de senadores no Congresso Nacional
- **Voto separado**: A contagem de votos é feita em cada uma das Casas, separadamente

### Referências legais
- Art. 52, CF/88
- Art. 57, 3º

### Dicas de prova
- Entenda a diferença entre representação proporcional e paritária
- Conheça o sistema de votos separados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.415", "page_number": 415, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, CF/88", "Art. 57, 3º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:16:27.917722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=415", "doc_key": "4c4c43a82074db364873d342a242101b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '645e0fed234ead7338e20d30ebaf803ac25e19f26c11d4a7e4c935346c85c6a8'),
  ('cpiuris2025::58cbd37e337fb5ac793a322bf884beb9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recondução dos membros das Mesas Diretoras das Assembleias Legislativas', '## Recondução dos membros das Mesas Diretoras das Assembleias Legislativas

A recondução dos membros das Mesas Diretoras das assembleias legislativas é limitada a uma única vez, de acordo com o art. 57, §4º da CF/88, exceto para os Estados que podem prever reeleição em número ilimitado, mas apenas uma vez.

### Conceitos
- **Recondução**: A prática de ser eleito novamente para o mesmo cargo
- **Mandato consecutivo**: O direito de ser reeleito para o mesmo cargo em seguida
- **Vedação à recondução**: A proibição de ser eleito novamente para o mesmo cargo

### Referências legais
- Art. 57, §4º da CF/88

### Jurisprudência
- STF. Plenário. AI 6720/AL, ADI 6721/RJ e ADI 6722/RO
- Info. 1030

### Dicas de prova
- Entenda a diferença entre recondução e mandato consecutivo
- Conheça as limitações da vedação à recondução nos Estados
- Análise cuidadosa do artigo 57, §4º da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.416", "page_number": 416, "discipline": "Direito Constitucional", "legal_refs": ["Art. 57, §4º da CF/88"], "jurisprudence": ["STF. Plenário. AI 6720/AL, ADI 6721/RJ e ADI 6722/RO", "Info. 1030"], "confidence": 0.8, "extracted_at": "2026-05-26T13:17:15.686762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=416", "doc_key": "58cbd37e337fb5ac793a322bf884beb9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd82b3378a20e66b753a5656d296272771aeae1c2fe267088800b5621a48056b3'),
  ('cpiuris2025::a22aeaa8739e9b7f037135610fa71b85', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legislativo Brasileiro', '## Legislativo Brasileiro

Descreve a estrutura e funcionamento do Legislativo brasileiro, incluindo as Câmaras dos Deputados e Senado Federal.

### Conceitos
- **Câmara dos Deputados**: órgão legislativo composto por representantes do povo, eleitos pelo sistema proporcional
- **Senado Federal**: órgão legislativo composto por representantes dos estados e do DF, com mandato de oito anos
- **Mesa Diretora**: órgão de diretoria da Casa Legislativa, responsável por exercer funções administrativas e conduzir trabalhos legislativos

### Referências legais
- Art. 58 da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: eleição de representantes do povo

### Dicas de prova
- Diferenciar entre sistema proporcional e majoritário
- Entender a relação entre o número de deputados federais e estaduais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.417 (1)", "page_number": 417, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: eleição de representantes do povo"], "confidence": 0.8, "extracted_at": "2026-05-26T13:17:47.356297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=417", "doc_key": "a22aeaa8739e9b7f037135610fa71b85"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e35e757271f2eaf80a1738439c9ab1dec1ae373aa3af42aae8c32e7bdeea6fa8'),
  ('cpiuris2025::88ef30ecd684b0a9b6d5503e0f4ae2d3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mesa Diretoras do CN e seus cargos', '## Mesa Diretoras do CN e seus cargos

As Mesas Diretoras do CN são presididas por presidentes de Câmara e Senado, com cargos alternados entre as duas câmaras. Os membros da Mesa têm mandato de 2 anos, sem recondução para o mesmo cargo na mesma legislatura.

### Conceitos
- **Mesa Diretoras**: órgão executivo do CN
- **Câmara e Senado**: câmaras legislativas brasileiras
- **mandato**: período de tempo para o exercício de cargo
- **recondução**: repetição do mesmo cargo em uma legislatura

### Referências legais
- Art. 40 da Constituição Federal

### Jurisprudência
- Súmula 636/STF

### Dicas de prova
- Entenda a estrutura da Mesa Diretoras e seus cargos.
- Conheça as regras de mandato e recondução para os membros da Mesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.417 (2)", "page_number": 417, "discipline": "Direito Constitucional", "legal_refs": ["Art. 40 da Constituição Federal"], "jurisprudence": ["Súmula 636/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:18:12.276198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=417", "doc_key": "88ef30ecd684b0a9b6d5503e0f4ae2d3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '65b828a0276aa28337651bd129c7a97c158438312c3dcb98c274115cdb62b3a2'),
  ('cpiuris2025::d32db45ddb7481008eb14ead72ee05d1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Reeleição de Presidentes da Câmara dos Deputados e do Senado Federal', '## Reeleição de Presidentes da Câmara dos Deputados e do Senado Federal

A reeleição dos Presidentes da Câmara dos Deputados e do Senado Federal é permitida, mas com limitações. A reeleição em número ilimitado é inconstitucional.

### Conceitos
- **Reeleição**: O direito de um político ser reeleito para o mesmo cargo.
- **Mandato Consecutivo**: A possibilidade de um político ser reeleito imediatamente após a expiração do seu mandato anterior.
- **Comissão Parlamentar**: Um órgão instituído para facilitar o trabalho do Plenário, que pode estudar e examinar proposições legislativas.
- **Atribuições das Comissões**: Discutir e votar projetos de lei, realizar audiências públicas, convocar ministros de Estado, etc.
- **Reprodução Obrigatória**: Uma norma que deve ser adotada por todos os Estados-membros.
- **Mandato Consecutivo Limitado**: A possibilidade de um político ser reeleito apenas uma vez após a expiração do seu mandato anterior.
- **Inconstitucionalidade**: Uma ação ou ato que viola a Constituição.
- **Plenário**: O órgão legislativo mais alto de um Estado-membro.

### Referências legais
- Art. 1.057, §4º, da CF/88

### Jurisprudência
- STF. Plenário. ADI 6524
- STF. Plenário. ADI 6720/AL
- STF. Plenário. ADI 6721/RJ
- STF. Plenário. ADI 6722/RO

### Dicas de prova
- Entenda a diferença entre reeleição e mandato consecutivo.
- Conheça as atribuições das comissões parlamentares.
- Identifique a reprodução obrigatória em relação às constituições estaduais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.418 (1)", "page_number": 418, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1.057, §4º, da CF/88"], "jurisprudence": ["STF. Plenário. ADI 6524", "STF. Plenário. ADI 6720/AL", "STF. Plenário. ADI 6721/RJ", "STF. Plenário. ADI 6722/RO"], "confidence": 0.8, "extracted_at": "2026-05-26T13:19:12.221907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=418", "doc_key": "d32db45ddb7481008eb14ead72ee05d1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1d92c6aa6919af993acbd3b5c149efaadd958cd6a0f4f0bf10ec850a85d8ec3f'),
  ('cpiuris2025::e183b6ac2607d6003e78ba7516b1b0a7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalidade de preceitos estatais', '## Constitucionalidade de preceitos estatais

Preceito da Constituição do Estado é inconstitucional se submete o relatório de impacto ambiental ao crivo de comissão permanente e específica da Assembleia Legislativa.

### Conceitos
- **Constitucionalidade**: A validade ou não da Constituição
- **Preceito constitucional**: Disposição da Constituição
- **Inconstitucionalidade**: O que é inconstitucional em relação à Constituição
- **Relatório de impacto ambiental (RIMA)**: Documento que avalia os impactos ambientais de uma atividade
- **Crivo de comissão permanente**: Processo de análise e aprovação de um documento por uma comissão específica

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula N STF
- RE 123456

### Dicas de prova
- Entenda a diferença entre ato do poder de polícia e atribuição do Poder Executivo
- Conheça o conceito de relatório de impacto ambiental (RIMA) e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.418 (2)", "page_number": 418, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula N STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T13:19:39.323196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=418", "doc_key": "e183b6ac2607d6003e78ba7516b1b0a7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '049f47291dbbb52ee4876515f07c328ccb6445e25fd6ba190dd9f81b7bbe6ab5'),
  ('cpiuris2025::d8b0a872eb5552845897ce7aba52b384', 'doutrina', 'cp_iuris', 'Direito Constitucional — Comissões Temporárias no Poder Legislativo', '## Comissões Temporárias no Poder Legislativo

As comissões temporárias são criadas para apreciar determinado assunto, extinguindo-se com o término da legislatura ou expirado o prazo para existência. Elas têm caráter temporário e incluem CPIs.

### Conceitos
- **Comissão Temporária**: comissão criada para apreciar determinado assunto
- **CPI (Comissão Parlamentar de Inquérito)**: comissão temporária que investiga um fato de interesse público
- **Sessão Legislativa**: período em que ocorrem as discussões e principais deliberações no Poder Legislativo
- **Regimento Comum**: instrumento que define as regras do funcionamento do Congresso Nacional

### Referências legais
- Art. 58, CF/88

### Dicas de prova
- Entenda a diferença entre comissão temporária e CPI.
- Conheça as atribuições da Comissão Representativa do Congresso Nacional durante o recesso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.419", "page_number": 419, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:20:12.654109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=419", "doc_key": "d8b0a872eb5552845897ce7aba52b384"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd803b88a734b77ae2275ea009ad4ab4ee5da37ffdc54e97fa2a022caa63e1842'),
  ('cpiuris2025::e20077b839a574364df93d3e93555a1b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Criação de CPIs', '## Criação de CPIs

A criação de Comissões Parlamentares de Inquérito (CPIs) está protegida pela Constituição e depende do preenchimento de requisitos específicos, como o requerimento de um terço dos membros das casas legislativas, a indicação de fato determinado a ser apurado e a definição de prazo certo para sua duração.

### Conceitos
- **CPI**: Comissão Parlamentar de Inquérito
- **Art. 58 da CF**: Requisitos indispensáveis à criação das CPIs
- **Direito Público Subjetivo**: Direito das minorias (1/3 é minoria)
- **Mandado de Segurança**: Remédio constitucional para impedimento de instauração de CPI

### Referências legais
- Art. 58 da CF

### Jurisprudência
- Informativo 1013 (14/4/2021)

### Dicas de prova
- Entenda a importância das minorias no processo constitucional
- Conheça os requisitos indispensáveis à criação das CPIs
- Aprenda a distinguir entre o direito público subjetivo e o mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.420 (1)", "page_number": 420, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF"], "jurisprudence": ["Informativo 1013 (14/4/2021)"], "confidence": 0.9, "extracted_at": "2026-05-26T13:20:56.688282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=420", "doc_key": "e20077b839a574364df93d3e93555a1b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '49d994e6a1b18870bf1acf0e9013a3cd54819050cf7075acb37770ac15b3affd'),
  ('cpiuris2025::263573104b20ca03071f3d12dcbf1436', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia das CPIs', '## Autonomia das CPIs

As CPIs têm autonomia para exercer suas funções, incluindo a avaliação de políticas públicas e o exercício do poder fiscalizatório.

### Conceitos
- **CPI**: Comissão Parlamentar de Inquérito
- **Autonomia**: Direito das CPIs de agir sem interferência externa
- **Fiscalização**: Atividade de controle e supervisão do Poder Executivo
- **Legiferante**: Poder que tem a capacidade de criar leis
- **Investigação**: Coleta de informações para fins legais ou administrativos

### Referências legais
- Art. 58, §3º, da Constituição

### Jurisprudência
- Súmula Nº 923 do STF

### Dicas de prova
- Entenda a autonomia das CPIs e seu papel no sistema político brasileiro.
- Conheça as funções específicas das CPIs, como fiscalização e investigação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.420 (2)", "page_number": 420, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58, §3º, da Constituição"], "jurisprudence": ["Súmula Nº 923 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:21:21.019450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=420", "doc_key": "263573104b20ca03071f3d12dcbf1436"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1bd45cc0a829294af5981cae54188b8b4c7ec17b03579d7445ad93574acc52bc'),
  ('cpiuris2025::df3075ac249db58ee2dbc596a50c9391', 'doutrina', 'cp_iuris', 'Direito Constitucional — Comissão de Investigação Parlamentar (CPI)', '## Comissão de Investigação Parlamentar (CPI)

A CPI é um órgão do Congresso Nacional que pode investigar fatores determinados e promover responsabilidade civil ou criminal. As decisões da CPI devem ser tomadas por maioria dos membros, e a comissão deve ter um prazo certo para funcionar.

### Conceitos
- **CPI**: Comissão de Investigação Parlamentar
- **Coletialidade**: Princípio que exige a tomada de decisões por maioria dos membros de uma instituição
- **Poderes próprios**: Poderes conferidos a um órgão ou entidade para agir independentemente de outra autoridade
- **Investigação**: Ação de coletar informações e provas para esclarecer uma questão ou problema
- **Responsabilidade civil ou criminal**: Obrigação de reparar danos ou punir alguém por um ato ou omissão
- **Princípio da simetria**: Princípio que estabelece a igualdade entre os poderes do Estado e das autoridades judiciais
- **Prazo certo**: Período de tempo estabelecido para o funcionamento de um órgão ou entidade
- **Mandado de segurança**: Medida judicial que visa proteger direitos e garantir a ordem pública

### Referências legais
- Art. 58 da Constituição Federal
- Súmula Nº 538 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de CPI e seus poderes.
- Conheça o princípio da coletialidade e sua importância na tomada de decisões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.421 (1)", "page_number": 421, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal", "Súmula Nº 538 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:22:08.989910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=421", "doc_key": "df3075ac249db58ee2dbc596a50c9391"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5e14e56362de0deeb396699e22be54d89daaa7a44ac71411384010be05a5fdf9'),
  ('cpiuris2025::04a571657affb6cae20875c042bbde32', 'doutrina', 'cp_iuris', 'Direito Constitucional — Amplitude das CPIs', '## Amplitude das CPIs

As Comissões de Investigação Permanentes (CPIs) têm amplitude limitada, podendo quebrar sigilos bancários e fiscal, ouvir testemunhas e investigados, mas não podem determinar prisão, buscas e apreensões genéricas sem autorização judicial.

### Conceitos
- **Amplitude de CPI**: Limitações das CPIs em relação à investigação
- **Poder geral de cautela**: Exclusivo do magistrado, não da CPI
- **Prisão**: Não pode ser determinada por CPI sem autorização judicial

### Referências legais
- Art. 102, § 3º, inciso IV da CF
- Súmula 822/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Amplitude das CPIs

### Dicas de prova
- Entenda a amplitude das CPIs e suas limitações
- Distinga entre poder geral de cautela e exclusividade da CPI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.421 (2)", "page_number": 421, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso IV da CF", "Súmula 822/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Amplitude das CPIs"], "confidence": 0.8, "extracted_at": "2026-05-26T13:22:45.421245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=421", "doc_key": "04a571657affb6cae20875c042bbde32"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f3eac4b24dc3be261da38bb5b0c7d81886969d119d203a10ec9fc6dc4815a4d7'),
  ('cpiuris2025::7701322f791a16141bd160d494981d0d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Legislativo e Investigação de Fatos', '## Poder Legislativo e Investigação de Fatos

A CPI não pode investigar fatos de interesse exclusivamente privado ou violar a separação dos Poderes. Além disso, os atos da CPI não alcançam atos de natureza jurisdicional.

### Conceitos
- **CPI**: Comissão de Investigação
- **Separação dos Poderes**: Princípio que estabelece a autonomia de cada Poder do Estado
- **Autonomia Federativa**: Direito dos estados-membros de manter sua autonomia e soberania
- **Investigação de Fatos**: Ação da CPI para investigar fatos relacionados a uma questão pública

### Referências legais
- Art. 3º, §2º, Lei n.º 10.679/2013
- Art. 5º, XI e XII, CF/88

### Jurisprudência
- ADPF 848 MC-Ref/DF
- Informativo 1023, STF

### Dicas de prova
- Distinção entre fatos de interesse público e privado
- Separação dos Poderes e autonomia federativa
- Limitações da CPI em relação ao poder judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.422 (1)", "page_number": 422, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º, §2º, Lei n.º 10.679/2013", "Art. 5º, XI e XII, CF/88"], "jurisprudence": ["ADPF 848 MC-Ref/DF", "Informativo 1023, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:23:18.370364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=422", "doc_key": "7701322f791a16141bd160d494981d0d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'de21ec8874359fe15a37c18e46ef5ac888b95d0c6e89abab04b8ee85f6d52093'),
  ('cpiuris2025::58992a3eca039b41e3a1f23eb595f9d9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e Decisões Públicas', '## Poder Judiciário e Decisões Públicas

A decisão da CPI deve ser fundamentada para evitar nulidade, de acordo com o art. 93, IX, CF/88.

### Conceitos
- **Princípio da Fundamentação**: Requer que as decisões devem estar fundamentadas
- **Poder Judiciário Público**: Julgamentos dos órgãos do Poder Judiciário são públicos
- **Intimidade do Interessado**: O sigilo deve ser preservado para proteger o direito à intimidade

### Referências legais
- Art. 93, IX, CF/88

### Dicas de prova
- Diferenciar interceptação telefônica de dado telefônico
- Entender a importância do princípio da fundamentação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.422 (2)", "page_number": 422, "discipline": "Direito Constitucional", "legal_refs": ["Art. 93, IX, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:23:40.086313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=422", "doc_key": "58992a3eca039b41e3a1f23eb595f9d9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1bd33792a43f9be1e6b2506b27771d8101ecc53c6e7e533edebfcf1b9281c1c6'),
  ('cpiuris2025::3a017f2b0b6239557d73fa97f5ff4795', 'doutrina', 'cp_iuris', 'Direito Constitucional — Comissão Parlamentar de Inquérito (CPI) e suas características', '## Comissão Parlamentar de Inquérito (CPI) e suas características

A CPI é uma investigação parlamentar que deve ser tomada por colegiado e maioria de votos, respeitando o princípio federativo. Ela deve guardar um nexo causal com a gestão da coisa pública e envolver bens, serviços ou interesse da União e da sociedade como um todo.

### Conceitos
- **CPI**: Comissão Parlamentar de Inquérito
- **colegialidade**: Princípio que exige a tomada de decisões por colegiado e maioria de votos
- **princípio federativo**: Princípio que respeita a autonomia dos estados e municípios
- **nexo causal**: Conexão lógica entre a investigação e a gestão da coisa pública

### Referências legais
- Art. 1º, Lei n.º 10.001/2000

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda o conceito de CPI e suas características
- Identifique a importância do princípio federativo na CPI
- Conheça as regras para a transmissão dos relatórios da CPI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.423 (1)", "page_number": 423, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, Lei n.º 10.001/2000"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:24:24.429908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=423", "doc_key": "3a017f2b0b6239557d73fa97f5ff4795"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f78d16b801975db055d683c7a933bf4faef9c95298d428c4f37a623ffd24ee68'),
  ('cpiuris2025::76886c59a26bd765b141b48e0f9a3421', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processos de Comissão Parlamentar de Inquérito (CPI) e Prioridade nas Ações Judiciais', '## Processos de Comissão Parlamentar de Inquérito (CPI) e Prioridade nas Ações Judiciais

O artigo estabelece regras para os processos instaurados em decorrência de CPIs, incluindo a comunicação semestral da fase do processo pelo MP e a prioridade das ações judiciais derivadas de CPI.

### Conceitos
- **Comissão Parlamentar de Inquérito (CPI)**: instituição que investiga fatos relacionados a um determinado assunto
- **Prioridade nas ações judiciais**: regras que estabelecem a ordem em que as ações judiciais devem ser processadas
- **Relatório semestral**: documento que o MP deve enviar ao Poder Judiciário e às autoridades legislativas sobre o andamento do processo
- **Processo penal**: procedimento jurídico que visa punir um indivíduo por um crime
- **Ações judiciais derivadas de CPI**: ações que são processadas em decorrência de uma CPI

### Referências legais
- Art. 2º, Parágrafo único da Lei 10.001/2000

### Dicas de prova
- Entenda a diferença entre processo administrativo e judicial.
- Conheça as regras de prioridade para as ações judiciais derivadas de CPIs.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.423 (2)", "page_number": 423, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º, Parágrafo único da Lei 10.001/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:24:57.093813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=423", "doc_key": "76886c59a26bd765b141b48e0f9a3421"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9b636197a6e478af0316286a699edb05e96f5ba347d9afb0abd74ce44bef92c0'),
  ('cpiuris2025::7ae438634ff89ca9bb330517d41cbd6b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Comissão de Investigação da Conduta Administrativa (CPI)', '## Comissão de Investigação da Conduta Administrativa (CPI)

A CPI é um órgão do Poder Legislativo que pode convocar e inquirir pessoas, determinar a condução coercitiva de testemunha e realizar buscas e apreensões, mas com limitações e ressalvas.

### Conceitos
- **CPI**: Comissão de Investigação da Conduta Administrativa
- **Contraditório**: Direito do acusado de responder às acusações feitas contra ele
- **Ampla Defesa**: Direito do acusado de ter assistência jurídica adequada
- **Cláusula de Reserva**: Conceito jurídico que limita a aplicação de uma lei ou norma a certos casos ou situações
- **Prisão em Flagrante**: Arresto imediato de alguém suspeito de cometer um crime
- **Busca e Apreensão**: Ação realizada pela CPI para coletar provas contra o investigado
- **Sigilo Profissional**: Direito do advogado de manter confidenciais as informações obtidas durante a representação

### Referências legais
- Art. 4º, Lei 10.001/2000

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre o contraditório e a ampla defesa
- Conheça as cláusulas de reserva que limitam a aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.424", "page_number": 424, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4º, Lei 10.001/2000"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:25:40.353409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=424", "doc_key": "7ae438634ff89ca9bb330517d41cbd6b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '841b2e3cfe65a99e33c8c66bfd55e6dad103e840cd234508695247a0ba8e6ddd'),
  ('cpiuris2025::66d05a565a141f70d698412801057c46', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sessão Legislativa do CN', '## Sessão Legislativa do CN

A sessão legislativa do CN é estabelecida pela CF/88, com duração de dois períodos legislativos. É interrompida apenas após a aprovação de projeto de lei de diretrizes orçamentárias.

### Conceitos
- **Sessão Legislativa**: Reunião do CN para discutir e votar leis
- **Período Legislativo**: Duração da sessão legislativa
- **Diretrizes Orçamentárias**: Projeto de lei que estabelece diretrizes para o orçamento anual
- **Convocação Extraordinária**: Reunião do CN fora do período regular, geralmente em casos de emergência

### Referências legais
- Art. 48 da CF/88
- Art. 49 da CF/88
- EC 50/2006

### Jurisprudência
- STF. Plenário. ADPF 836/RR
- Informativo 1024, STF

### Dicas de prova
- Entenda a diferença entre sessão legislativa e convocação extraordinária
- Conheça as atribuições do Congresso Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.425", "page_number": 425, "discipline": "Direito Constitucional", "legal_refs": ["Art. 48 da CF/88", "Art. 49 da CF/88", "EC 50/2006"], "jurisprudence": ["STF. Plenário. ADPF 836/RR", "Informativo 1024, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:26:27.473251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=425", "doc_key": "66d05a565a141f70d698412801057c46"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '420cb33d039885fbb3bc4f5e6ee4ef8cae5c00c02f649856e0a2bd8943c86e03'),
  ('cpiuris2025::585bfddce829b614e13ebb25ff8a14a1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Congresso Nacional', '## Competência do Congresso Nacional

Resumo do artigo 49, que estabelece a competência exclusiva do Congresso Nacional em diversas áreas, incluindo tratados internacionais, declaração de guerra e aprovação do estado de defesa.

### Conceitos
- **Competência Exclusiva**: A competência que é exercida apenas pelo Congresso Nacional
- **Tratados Internacionais**: Acordos ou atos internacionais que acarretem encargos ou compromissos gravosos ao patrimônio nacional
- **Declaração de Guerra**: A autorização do Congresso Nacional para declarar guerra
- **Estado de Defesa**: A aprovação do Congresso Nacional para o estado de defesa

### Referências legais
- Art. 49 da Constituição

### Dicas de prova
- Entenda a distinção entre competência exclusiva e delegada
- Conheça os exemplos de tratados internacionais que requerem declaração do Congresso Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.426 (1)", "page_number": 426, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:26:57.181466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=426", "doc_key": "585bfddce829b614e13ebb25ff8a14a1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c76288245a73a42b55a7d5768bee101c8c78cff1ae1886913889101c1e48cd35'),
  ('cpiuris2025::58946ca33b8dc547e081a99ad7f0f9be', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poderes do Congresso Nacional', '## Poderes do Congresso Nacional

O Congresso Nacional tem competências específicas, incluindo fiscalização e controle do Poder Executivo, preservação de sua competência legislativa e aprovação de iniciativas relacionadas a atividades nucleares.

### Conceitos
- **Poder Legislativo**: O Poder Legislativo é um dos três Poderes do Estado brasileiro, responsável pela elaboração das leis.
- **Competência Legislativa**: A competência legislativa é a autoridade concedida ao Poder Legislativo para criar, alterar ou extinguir leis.
- **Fiscalização e Controle**: A fiscalização e o controle são mecanismos utilizados pelo Congresso Nacional para supervisionar e regular as atividades do Poder Executivo.
- **Tribunal de Contas da União**: O Tribunal de Contas da União é um órgão responsável por fiscalizar a gestão pública federal.
- **Concessões de Rádio e Televisão**: As concessões de rádio e televisão são autorizações concedidas pelo Congresso Nacional para a exploração desses meios de comunicação.
- **Competência Normativa**: A competência normativa é a autoridade concedida ao Poder Legislativo para criar, alterar ou extinguir normas legais.
- **Poder Executivo**: O Poder Executivo é um dos três Poderes do Estado brasileiro, responsável pela execução das leis.
- **Administração Indireta**: A administração indireta é uma forma de gestão pública que não está diretamente subordinada ao Poder Executivo.

### Referências legais
- Art. 58 da Constituição Federal

### Dicas de prova
- Entenda a competência legislativa e o papel do Congresso Nacional no controle do Poder Executivo.
- Identifique as atividades que estão sob a competência exclusiva do Congresso Nacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.426 (2)", "page_number": 426, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:27:40.421081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=426", "doc_key": "58946ca33b8dc547e081a99ad7f0f9be"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd4f248311e321fe1983e0614a18792380a75320d30211216d3764cd932f8ed18'),
  ('cpiuris2025::10b15a6d04dc6bf58e5c8a2895722b0e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências do Congresso Nacional e Legislativo', '## Competências do Congresso Nacional e Legislativo

O texto discute as competências do Congresso Nacional e do Legislativo, incluindo a autorização de referendo e convocação de plebiscito, a fixação de subsídios dos Deputados Federais e Senadores, e a competência exclusiva para julgar contas do Presidente da República.

### Conceitos
- **Competências do Congresso Nacional**: A competência exclusiva do Congresso Nacional para julgar contas do Presidente da República.
- **Legislativo**: O Legislativo é o órgão responsável por autorizar referendo e convocar plebiscito, fixar subsídios dos Deputados Federais e Senadores.
- **Subsídios dos Deputados**: Os subsídios dos Deputados Federais e Senadores são fixados pelo Congresso Nacional, enquanto os subsídios dos Deputados Estaduais são fixados por lei de iniciativa da Assembleia Legislativa do Estado.
- **Princípio Federativo**: O princípio federativo é o princípio que estabelece a autonomia dos Estados-membros em relação ao governo federal.

### Referências legais
- Art. 49, VII da CF/88
- Art. 27, §2° da CF/88

### Jurisprudência
- RE 123456
- Info 109056, STF

### Dicas de prova
- Entenda a competência do Congresso Nacional e do Legislativo.
- Conheça o princípio federativo e sua importância na Constituição.
- Diferencie entre subsídios dos Deputados Federais e Senadores, e dos Deputados Estaduais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.427", "page_number": 427, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, VII da CF/88", "Art. 27, §2° da CF/88"], "jurisprudence": ["RE 123456", "Info 109056, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:28:36.797374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=427", "doc_key": "10b15a6d04dc6bf58e5c8a2895722b0e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e9928c4399e372c501239e23a6da8b201b23070ea0b85e766ef33fb5db2d377'),
  ('cpiuris2025::e0af2a64be72c32e3674c6105c0729cc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Congresso Nacional e separação dos poderes', '## Competência do Congresso Nacional e separação dos poderes

O Congresso Nacional tem competência para legislar sobre questões que afetam a União, enquanto os Estados têm competência para legislar sobre questões que afetam apenas seus respectivos territórios. A separação dos poderes é um princípio fundamental que limita a competência do Poder Executivo e impede que ele exerça controle indevido sobre o Legislativo.

### Conceitos
- **Competência exclusiva**: A competência de uma entidade para legislar sobre um determinado assunto
- **Separação dos Poderes**: Princípio que limita a competência do Poder Executivo e impede que ele exerça controle indevido sobre o Legislativo
- **Legislativo**: Poder do Estado que tem como função legislar
- **Executivo**: Poder do Estado que tem como função executar as leis
- **Coletividade**: A ideia de que a competência é exercida por um coletivo, em vez de um indivíduo
- **Princípio da colegialidade**: Regra que estabelece que as decisões devem ser tomadas por um coletivo, em vez de um indivíduo
- **Ato de fiscalização**: Ação do Legislativo para controlar o Executivo
- **Requisição de informações**: Pedidos feitos pelo Legislativo ao Executivo para obter informações

### Referências legais
- Art. 49, X da CF/88
- Art. 50 da CF/88

### Jurisprudência
- ADI 4700/DF
- STF Plenário

### Dicas de prova
- Entenda a competência do Congresso Nacional e como ela se relaciona com a separação dos poderes
- Conheça o princípio da colegialidade e como ele afeta as decisões do Legislativo
- Aprenda a fazer requisições de informações ao Executivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.428 (1)", "page_number": 428, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, X da CF/88", "Art. 50 da CF/88"], "jurisprudence": ["ADI 4700/DF", "STF Plenário"], "confidence": 0.8, "extracted_at": "2026-05-26T13:29:25.236854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=428", "doc_key": "e0af2a64be72c32e3674c6105c0729cc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a81d84f354d8f0a34fe190b436f08a56f335716f3ece6ae9cc1b3f572b0252a3'),
  ('cpiuris2025::6750f773dc27b165451ad965119f9224', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atribuições da Câmara dos Deputados', '## Atribuições da Câmara dos Deputados

A Câmara dos Deputados tem competências privativas definidas na Constituição, especificamente no art. 51, que detalha suas atribuições.

### Conceitos
- **Câmara dos Deputados**: órgão legislativo do Poder Executivo
- **Competências privativas**: atribuições exclusivas da Câmara dos Deputados
- **Art. 51 CF/88**: disposição constitucional que define as competências da Câmara dos Deputados

### Referências legais
- Art. 51 da CF/88

### Jurisprudência
- RE 865401/MG
- Tema 83257, STF

### Dicas de prova
- Entenda a importância das competências privativas da Câmara dos Deputados
- Conheça o art. 51 da CF/88 e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.428 (2)", "page_number": 428, "discipline": "Direito Constitucional", "legal_refs": ["Art. 51 da CF/88"], "jurisprudence": ["RE 865401/MG", "Tema 83257, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:29:47.986728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=428", "doc_key": "6750f773dc27b165451ad965119f9224"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f9105400971876f484bb54269c0fdb477eb35e1e5f434acb67b02965fe1f1489'),
  ('cpiuris2025::4c58e20945c2e0125ce48f12b4a95290', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Legislativo', '## Poder Legislativo

O Poder Legislativo tem competências específicas, como autorizar a instauração de processo contra o Presidente e os ministros de Estado, tomar contas do Presidente da República e elaborar seu regimento interno.

### Conceitos
- **Competência privativa**: A competência que é exclusiva de um órgão ou entidade
- **Autorização prévia**: O ato de autorizar a instauração de processo antes de sua análise
- **Instauração do processo**: O ato de iniciar o processo contra um indivíduo
- **Juízo de admissibilidade**: A avaliação da legitimidade do processo
- **Juízo de mérito**: A análise da substância do processo
- **Denúncia**: O ato de apresentar acusações contra um indivíduo
- **Responsabilidade conexa**: A responsabilidade de um ministro de Estado por crimes cometidos em conjunto com o Presidente da República

### Referências legais
- Art. 49, § 2º, inciso IV da Constituição Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Autorização prévia e instauração do processo

### Dicas de prova
- Entenda a competência privativa do Poder Legislativo
- Conheça as regras de autorização prévia e instauração do processo
- Avalie a diferença entre juízo de admissibilidade e juízo de mérito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.429 (1)", "page_number": 429, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, § 2º, inciso IV da Constituição Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Autorização prévia e instauração do processo"], "confidence": 0.8, "extracted_at": "2026-05-26T13:30:41.004372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=429", "doc_key": "4c58e20945c2e0125ce48f12b4a95290"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2632bf5a2a464c567a0cec4fec7b28e8fd94b914eead2a66f27d1529e2c5e2dc'),
  ('cpiuris2025::983b17deabdfbedaff99866bf3e7f6da', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atribuições do Senado Federal', '## Atribuições do Senado Federal

O Senado Federal tem atribuições privativas, incluindo processar e julgar o Presidente da República em crimes de responsabilidade, além de outros cargos e funcionários públicos.

### Conceitos
- **Maioria simples**: Voto positivo de mais de metade dos membros do Senado
- **Processamento e julgamento**: Atribuição do Senado Federal processar e julgar determinados cargos e funcionários públicos
- **Crimes de responsabilidade**: Delitos cometidos por membros do Poder Executivo, Legislativo ou Judiciário

### Referências legais
- Art. 52 da Constituição Federal

### Dicas de prova
- Entenda a diferença entre maioria simples e voto de 2/3
- Conheça as atribuições privativas do Senado Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.429 (2)", "page_number": 429, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:31:04.976136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=429", "doc_key": "983b17deabdfbedaff99866bf3e7f6da"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '73bdd237e3f6092ad4e7a747cf63311c29ea2c4dd92211406cbae96938781f2f'),
  ('cpiuris2025::27699ca3e6f3190691186eb9757fce46', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Legislativo', '## Poder Legislativo

Descreve as competências do Poder Legislativo, incluindo a aprovação de leis e a eleição de membros do Conselho da República.

### Conceitos
- **Poder Legislativo**: O poder que executa as funções legislativas
- **Tribunal de Contas da União**: Entidade responsável por controlar a gestão pública
- **Ministros do Tribunal de Contas da União**: Especialistas em controle interno que fazem parte do Tribunal de Contas
- **Cargos que a lei determina**: Funções públicas que são regulamentadas por lei

### Referências legais
- Art. 49 da Constituição Federal
- Art. 102, § 3º, da Constituição Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Impeachment do Presidente e do Vice-Presidente da República

### Dicas de prova
- Entenda a estrutura do Poder Legislativo e suas competências
- Conheça as funções específicas de cada cargo mencionado no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.430 (1)", "page_number": 430, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49 da Constituição Federal", "Art. 102, § 3º, da Constituição Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Impeachment do Presidente e do Vice-Presidente da República"], "confidence": 0.8, "extracted_at": "2026-05-26T13:31:37.568560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=430", "doc_key": "27699ca3e6f3190691186eb9757fce46"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b3e64c6bab0157671f9f92d69c688509446e3bb5d7156f827e1fb7eede5e101e'),
  ('cpiuris2025::1b74c4e4de93bc41a255533d8ebb4892', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Difuso e Suspensão da Execução', '## Controle Difuso e Suspensão da Execução

A suspensão da execução de uma lei é discricionária, mas não é obrigatória após a declaração de inconstitucionalidade pelo STF. A abstrativização do controle difuso permite que o Senado não suspenda a execução se for apenas controle concreto.

### Conceitos
- **Controle Difuso**: A capacidade do STF de declarar inconstitucionalidade de uma norma sem necessariamente suspender sua execução.
- **Suspensão da Execução**: O ato pelo qual o Senado Federal interrompe a execução de uma lei considerada inconstitucional.
- **Abstrativização do Controle Difuso**: A tendência de reduzir o controle difuso ao controle concreto, permitindo que o STF não suspenda a execução se for apenas controle concreto.

### Referências legais
- Art. 102, § 3º, inciso IV da CF/88

### Jurisprudência
- RE 123456
- Súmula 427/STF

### Dicas de prova
- Entenda a diferença entre controle concreto e controle difuso.
- Conheça a abstrativização do controle difuso e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.430 (2)", "page_number": 430, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso IV da CF/88"], "jurisprudence": ["RE 123456", "Súmula 427/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:32:31.673711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=430", "doc_key": "1b74c4e4de93bc41a255533d8ebb4892"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '06d6b85ba778374029f254c7b86e63526fa1e901e3f7fd0abf2275f92c74b0f7'),
  ('cpiuris2025::f161dd0cc172d9f400eae92f918daad1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidades parlamentares', '## Imunidades parlamentares

As imunidades parlamentares visam garantir a independência do Poder Legislativo e são irrenunciáveis. As imunidades materiais estabelecem que os deputados e senadores são invioláveis civil e penalmente por suas opiniões, palavras e votos relacionadas ao exercício da função.

### Conceitos
- **Imunidade material**: inviolabilidade civil e penal por opiniões, palavras e votos relacionados ao exercício da função
- **Inviolabilidade absoluta**: presunção de pertinência com o desempenho da função em qualquer lugar
- **Imunidade formal**: proteção contra processos e ações judiciais relacionadas ao exercício da função
- **Independência do Poder Legislativo**: garantia de que o Parlamento possa exercer suas funções sem interferências

### Referências legais
- Art. 53, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre imunidades materiais e formais
- Conheça a importância da independência do Poder Legislativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.431", "page_number": 431, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:33:28.809241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=431", "doc_key": "f161dd0cc172d9f400eae92f918daad1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f5681e0b286661edd5385d7f06389c745cd77efd88763bb384082084d7e03457'),
  ('cpiuris2025::b6aec1da981b073d934621a14b9ff426', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade do Parlamentar', '## Imunidade do Parlamentar

O parlamentar possui imunidade material desde a diplomação, independentemente do local de proferimento. A imunidade é de ordem pública e não pode ser renunciada. Além disso, os deputados federais, estaduais e distritais possuem imunidade parlamentar material, enquanto os vereadores não.

### Conceitos
- **Imunidade Material**: Conceito jurídico que protege o parlamentar contra a prisão nos crimes cometidos após a diplomação
- **Diplomação**: Atestado de que o sujeito foi regularmente eleito, que marca o início da imunidade material
- **Imunidade Parlamentar Material**: Conceito jurídico que protege os deputados federais, estaduais e distritais contra a prisão nos crimes cometidos após a diplomação
- **Vereador**: Membro do legislativo municipal que não possui imunidade parlamentar material

### Referências legais
- Art. 29, VIII, CF/88
- Art. 53, §2º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre imunidade material e diplomação podem ser difíceis, mas é importante entender a distinção entre os dois conceitos
- A exceção prevista no art. 53, §2º, CF/88 é fundamental para responder corretamente às perguntas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.432 (1)", "page_number": 432, "discipline": "Direito Constitucional", "legal_refs": ["Art. 29, VIII, CF/88", "Art. 53, §2º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:34:23.925682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=432", "doc_key": "b6aec1da981b073d934621a14b9ff426"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cf63fa6a6d892cb342415d057f99b6db735594db000f2be46cb4f2d84badcdcc'),
  ('cpiuris2025::1ab57b61f452bf711f42b4b0c96409ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva é decidida por maioria absoluta dos parlamentares, sendo aberta e não secreta. Exceções são previstas na legislação criminal, com a condenação transitada em julgado sendo um caso jurídico construído pelo STF.

### Conceitos
- **Prisão Preventiva**: Decisão da prisão preventiva feita por maioria absoluta dos parlamentares
- **Flagrante de Crime Inafiançável**: Situação em que a prisão é necessária para evitar a fuga do preso
- **Votação Aberta e Não Secreta**: Méodo de votação utilizado na decisão da prisão preventiva

### Referências legais
- Art. 53, §2º, da CF

### Jurisprudência
- HC 89417 (Informativo 437 do STF)
- AP 396 (Caso Natan Donadon)

### Dicas de prova
- Distinção entre flagrante de crime inafiançável e outros casos
- Votação aberta e não secreta na decisão da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.432 (2)", "page_number": 432, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, §2º, da CF"], "jurisprudence": ["HC 89417 (Informativo 437 do STF)", "AP 396 (Caso Natan Donadon)"], "confidence": 0.8, "extracted_at": "2026-05-26T13:35:08.317349+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=432", "doc_key": "1ab57b61f452bf711f42b4b0c96409ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cfe9ff9900b497712b65532043b790948e7baf147b9ccd5ff633543db476910c'),
  ('cpiuris2025::81dcf7d50c86b392cf8e7db3c02d5e0b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade Parlamentar e Medidas Cautelares', '## Imunidade Parlamentar e Medidas Cautelares

O presidente da Assembleia Legislativa de Rondônia foi preso em flagrante, mas os autos não foram encaminhados para a Assembleia em 24 horas. O presidente recorreu ao STJ e STF, argumentando que a Constituição protege a imunidade parlamentar. No entanto, a Ministra Cármen Lúcia levantou a tese da relativização do artigo 53, §2º, da CF, afirmando que a Constituição não pode ser utilizada contra o próprio presidente.

### Conceitos
- **Imunidade Parlamentar**: Conceito jurídico que protege os parlamentares de responsabilidade criminal por suas ações em decorrência do exercício do mandato
- **Medidas Cautelares Diversas da Prisão**: Ações tomadas pelo Poder Judiciário para evitar a prisão de um parlamentar, como afastamento do cargo ou recolhimento domiciliar noturno
- **Relativização do Artigo 53, §2º, da CF**: Tese jurídica que afirma que a Constituição não pode ser utilizada contra o próprio presidente, mesmo em casos de imunidade parlamentar

### Referências legais
- Art. 53, §2º, da CF

### Jurisprudência
- HC 89417
- ADI 5526
- Informativo 881 STF

### Dicas de prova
- Entenda a noção de imunidade parlamentar e suas limitações
- Conheça as medidas cautelares diversas da prisão e como elas são aplicadas aos parlamentares
- Análise da tese da relativização do artigo 53, §2º, da CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.433 (1)", "page_number": 433, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, §2º, da CF"], "jurisprudence": ["HC 89417", "ADI 5526", "Informativo 881 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:35:59.105884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=433", "doc_key": "81dcf7d50c86b392cf8e7db3c02d5e0b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '59c992848ceec9d71b92d076486af56aad9e33d884f850742def9dbdb42b771e'),
  ('cpiuris2025::da3b0421274b9d2356ae92d7778d9d51', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade Parlamentar', '## Imunidade Parlamentar

A imunidade parlamentar é composta por duas partes: a imunidade formal em relação à prisão e a imunidade em relação ao processo. A primeira é definida pela maioria dos membros da Casa Legislativa, enquanto a segunda é garantida pelo art. 53, §3º, CF.

### Conceitos
- **Imunidade Parlamentar**: Direito que protege os parlamentares de penalidades por suas opiniões, palavras e votos
- **Prisão Preventiva**: Medida cautelar que pode ser aplicada a um suspeito antes do julgamento
- **Imunidade Formal**: Proteção contra a prisão preventiva, definida pela maioria dos membros da Casa Legislativa
- **Imunidade Em Relação Ao Processo**: Proteção dos parlamentares contra o processo em si, garantida pelo art. 53, §3º, CF

### Referências legais
- Art. 53, §2º, da CF
- Art. 53, §3º, CF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinguir entre imunidade formal e imunidade em relação ao processo
- Entender que a imunidade formal é definida pela maioria dos membros da Casa Legislativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.433 (2)", "page_number": 433, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, §2º, da CF", "Art. 53, §3º, CF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:36:31.842487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=433", "doc_key": "da3b0421274b9d2356ae92d7778d9d51"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9223c33ca2c8b5345a4ec9db9ac4ca5d666059f3719f1ab56bf81f602e710c4b'),
  ('cpiuris2025::d73fa33fc2f71527d9e5d4059622a804', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade Formal em Relação ao Processo', '## Imunidade Formal em Relação ao Processo

A imunidade formal em relação ao processo confere às casas legislativas a prerrogativa de sustar o andamento da ação penal por crime cometido por parlamentar após a diplomação, desde que haja iniciativa de partido político e voto da maioria absoluta dos membros.

### Conceitos
- **Imunidade Formal**: Prerrogativa das casas legislativas para sustar o andamento da ação penal por crime cometido por parlamentar após a diplomação.
- **Iniciativa de Partido Político**: Necessária para que a imunidade formal seja aplicada, sendo feita pela maioria absoluta dos membros da casa legislativa representada.
- **Voto da Maioria Absoluta**: Requerido para que a imunidade formal seja aplicada, sendo necessário o voto de mais de metade dos membros da casa legislativa.
- **Sustação do Andamento da Ação**: Prerrogativa das casas legislativas para suspender o andamento da ação penal por crime cometido por parlamentar após a diplomação.

### Referências legais
- Art. 3º, § 3º, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a imunidade formal e suas limitações.
- Conheça as condições necessárias para que a imunidade formal seja aplicada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.434 (1)", "page_number": 434, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º, § 3º, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:37:24.506909+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=434", "doc_key": "d73fa33fc2f71527d9e5d4059622a804"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '81347f07d76ba13d8681beb10434de78c84e55ed46cc592a48703666eb770c98'),
  ('cpiuris2025::c43757ebeee66b20f4a290f011221a5b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade Parlamentar e Processo', '## Imunidade Parlamentar e Processo

A imunidade parlamentar em relação ao processo é a mera possibilidade de sustação de ação contra parlamentar, após diplomação. O procedimento consiste em denúncia ou queixa-crime para o STF.

### Conceitos
- **Imunidade Parlamentar**: direito que protege os parlamentares do processo
- **Processo**: procedimento jurídico que busca a aplicação da lei
- **Sustação de Processo**: ação que suspende o andamento do processo
- **Denúncia**: ação pública que denuncia um crime
- **Queixa-Crime**: ação privada que denuncia um crime

### Referências legais
- Art. 37, Caput, da Constituição Federal
- EC 35/2001

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Entenda a diferença entre denúncia e queixa-crime
- Conheça a evolução da imunidade parlamentar ao longo dos anos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.434 (2)", "page_number": 434, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da Constituição Federal", "EC 35/2001"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:38:04.003945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=434", "doc_key": "c43757ebeee66b20f4a290f011221a5b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9d4884dc7f97f32dd9f07d45c84d1b62ae81abb3fee7d46c690a32c7181583f7'),
  ('cpiuris2025::734ac05126dcf6337876dc2d1c20061d', 'doutrina', 'cp_iuris', 'Direito Constitucional — O Processo de Sustação da Ação Penal', '## O Processo de Sustação da Ação Penal

Para que um político seja processado penalmente pelo STF, é necessário que pratique o crime no exercício do mandato e em função do mandato. O STF recebe a denúncia ou queixa-crime e inicia a ação penal, comunicando a Mesa da respectiva Casa.

### Conceitos
- **Mandato**: O exercício de uma função pública
- **Fungo público**: A pessoa que exerce mandato ou cargo público
- **Foro**: O tribunal competente para julgar um caso
- **Sustação da ação penal**: O processo de suspensão da ação penal
- **Prescrição**: O período durante o qual uma ação não pode ser iniciada
- **Corte Constitucional**: A Corte que interpreta e aplica a Constituição
- **Juiz de primeiro grau**: O juiz que julga um caso em primeira instância
- **Tese da redução teleológica**: A interpretação de que a Constituição tem uma finalidade ou propósito específico

### Referências legais
- Art. 53, §4º, CF/88
- Art. 53, §5º, CF/88
- Informativo 900 do STF
- Ação Penal 937/QO

### Jurisprudência
- RE 123456
- Tema repetitivo da Ação Penal 937/QO

### Dicas de prova
- Entenda a diferença entre mandato e função pública
- Conheça o conceito de foro e como ele se aplica ao caso
- Aprenda sobre a sustação da ação penal e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.435 (1)", "page_number": 435, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, §4º, CF/88", "Art. 53, §5º, CF/88", "Informativo 900 do STF", "Ação Penal 937/QO"], "jurisprudence": ["RE 123456", "Tema repetitivo da Ação Penal 937/QO"], "confidence": 0.8, "extracted_at": "2026-05-26T13:38:57.709728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=435", "doc_key": "734ac05126dcf6337876dc2d1c20061d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '470ee992a5ff8eda0c2926b5406031e6fbbb5fd37483606aedddddacc9f722d0'),
  ('cpiuris2025::d1841806e192cb3639291b2d78269ad9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Exercício de função no STF e competência', '## Exercício de função no STF e competência

O STF interpreta restritivamente os arts. 102, I, b e 53, § 1º, da CF/88, limitando a competência por foro por prerrogativa de função à situação em que o crime é praticado no exercício do mandato e guarda relação com ele.

### Conceitos
- **Competência por foro**: O direito do STF de julgar crimes cometidos por seus membros em decorrência do exercício de função.
- **Exercício de função**: A atividade realizada pelo membro do STF que lhe confere competência para julgar um crime.
- **Relação com o mandato**: A conexão entre o crime cometido e a função exercida pelo membro do STF.
- **Autorização do STF**: O direito do STF de autorizar ou não a investigação de um crime cometido por seu membro em decorrência do exercício de função.
- **Investigação**: A ação processual que visa apurar a veracidade de uma acusação.
- **Competência**: O direito do STF de julgar um crime cometido por seu membro em decorrência do exercício de função.
- **Mandato**: A função exercida pelo membro do STF que lhe confere competência para julgar um crime.
- **Deslocamento de competência**: O caso em que a competência por foro é transferida para outro tribunal ou autoridade.

### Referências legais
- Art. 102, I, b da CF/88
- Art. 53, § 1º da CF/88

### Jurisprudência
- RE 937/QO
- Informativo 900

### Dicas de prova
- Entenda a relação entre o exercício de função e a competência do STF.
- Conheça a distinção entre autorização e investigação no contexto da competência por foro.
- Aprenda a aplicar a regra de deslocamento de competência em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.435 (2)", "page_number": 435, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, b da CF/88", "Art. 53, § 1º da CF/88"], "jurisprudence": ["RE 937/QO", "Informativo 900"], "confidence": 0.8, "extracted_at": "2026-05-26T13:40:02.677514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=435", "doc_key": "d1841806e192cb3639291b2d78269ad9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '66cabdfd8ac8ea3ecaf15eff92f28531dcf5c419f30ea362381a92bc4a8f7bb4'),
  ('cpiuris2025::689230cc4aa142045a0cbaaa897f25b9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STF', '## Competência do STF

A competência do STF é preservada até o fim da instrução processual. Os parlamentares federais têm foro por prerrogativa de função, que inicia-se com a diplomação e encerra-se com o término do mandato.

### Conceitos
- **Competência do STF**: A competência do Supremo Tribunal Federal é preservada até o fim da instrução processual.
- **Foro por prerrogativa de função**: O foro por prerrogativa de função é um direito dos parlamentares federais, que inicia-se com a diplomação e encerra-se com o término do mandato.
- **Competência preservada**: A competência do STF é preservada até o fim da instrução processual, mesmo após a renúncia ao cargo ou encerramento do mandato.
- **Inquéritos policiais**: Os inquéritos policiais devem tramitar perante o STF, não podendo a Polícia Federal abrir Inquérito de ofício para apurar a conduta de parlamentares federais.
- **Suplentes dos parlamentares federais**: Os suplentes dos parlamentares federais não possuem foro por prerrogativa de função, salvo se vierem a exercer a atividade parlamentar.

### Referências legais
- Art. 53, §1º c/c art. 102, I, b da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência preservada do STF e o foro por prerrogativa de função dos parlamentares federais.
- Diferencie entre a competência preservada e a competência intransgredida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.436 (1)", "page_number": 436, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, §1º c/c art. 102, I, b da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:40:52.050132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=436", "doc_key": "689230cc4aa142045a0cbaaa897f25b9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd7b827a746f5ec80164ae7aebc87575ff840c92d89f58067b035f0d2970ef909'),
  ('cpiuris2025::70b426703a831ce8dfe86ba0ac5e2985', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência e prerrogativa de função', '## Competência e prerrogativa de função

Regras sobre competência e prerrogativa de função para parlamentares, incluindo reeleição consecutiva e afastamento do Poder Legislativo.

### Conceitos
- **Prerrogativa de função**: Direito que protege o parlamentar da perda de mandato por exercer sua função
- **Competência**: O poder de tomar decisões sobre uma área específica
- **Reeleição consecutiva e ininterrupta**: A possibilidade de um parlamentar ser reeleito para um novo mandato sem pausa
- **Afastamento do Poder Legislativo**: O ato de um parlamentar deixar de exercer sua função

### Referências legais
- Art. 56 da CF

### Dicas de prova
- Entenda a noção de prerrogativa de função e como ela afeta a competência do parlamentar
- Conheça as regras sobre reeleição consecutiva e ininterrupta
- Afastamento do Poder Legislativo: entenda o que isso significa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.436 (2)", "page_number": 436, "discipline": "Direito Constitucional", "legal_refs": ["Art. 56 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:41:19.376334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=436", "doc_key": "70b426703a831ce8dfe86ba0ac5e2985"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '735aa773b17b854f8c2458f93f311357ae9bac9d0a1a2aeb215d0341ff6abe80'),
  ('cpiuris2025::1571dc4fc03825c1aed3f8cfdb9d9eaf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidades Parlamentares', '## Imunidades Parlamentares

Os deputados e senadores têm imunidades que os protegem de serem processados por ações relacionadas ao exercício do mandato, mas podem renunciar a essas imunidades em determinadas situações.

### Conceitos
- **Imunidade Material**: A imunidade que protege as palavras e opiniões do parlamentar relacionadas ao mandato.
- **Imunidade Testemunhal**: A imunidade que protege o parlamentar de testemunhar sobre informações recebidas ou prestadas em razão do exercício do mandato.
- **Desobrigação de Testemunhar**: O direito dos deputados e senadores de não serem obrigados a testemunhar sobre informações recebidas ou prestadas em razão do exercício do mandato.

### Referências legais
- Art. 53, §6º, CF/88

### Dicas de prova
- Entenda a diferença entre imunidade material e testemunhal.
- Conheça as hipóteses em que o parlamentar pode ser obrigado a testemunhar.
- Aprenda a importância da licença da Casa respectiva para a incorporação às Forças Armadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.437 (1)", "page_number": 437, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, §6º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:42:08.649741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=437", "doc_key": "1571dc4fc03825c1aed3f8cfdb9d9eaf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa6ab9310a593bc214222bd38688e0eae22f9343c2dab8e7630385c9e8d0e718'),
  ('cpiuris2025::ebddd3dfd738d434fbb7aea180b5ceb2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidades dos membros do Congresso Nacional', '## Imunidades dos membros do Congresso Nacional

Os membros do Congresso Nacional não perderão o mandato por investir em cargos de Estado ou por licença, desde que dura mais de 120 dias.

### Conceitos
- **imunidade**: direito que protege os membros do Congresso Nacional
- **cargo de Estado**: cargos que incluem Ministro de Estado, Governador de Território, etc.
- **licença**: afastamento do mandato por motivo de doença ou interesse particular

### Referências legais
- Art. 56, CF/88

### Dicas de prova
- Entenda que as imunidades não são do indivíduo, mas sim do cargo que ele exerce.
- Conheça os cargos de Estado que incluem a perda da imunidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.437 (2)", "page_number": 437, "discipline": "Direito Constitucional", "legal_refs": ["Art. 56, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:42:35.165474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=437", "doc_key": "ebddd3dfd738d434fbb7aea180b5ceb2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd7cce8fd605a16aa55cc3981c8e6e425263efb6c797ba8b3c8ab13567012811b'),
  ('cpiuris2025::1a25830efadf123830c835a64ffefb24', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidades e Supremacia do Poder Legislativo', '## Imunidades e Supremacia do Poder Legislativo

O texto discute as imunidades dos parlamentares, especialmente em relação à suspensão durante o estado de sítio e a convocação de suplentes. O STF acolheu ação da PGR que questionou a inovação na disciplina do estatuto constitucional dos congressistas.

### Conceitos
- **Imunidades**: Conceito jurídico que protege os parlamentares de certas ações judiciais e administrativas
- **Supremacia do Poder Legislativo**: Princípio constitucional que assegura a superioridade do Poder Legislativo em relação aos outros poderes do Estado
- **Estado de Sítio**: Situação excepcional em que o governo assume poderes especiais para garantir a ordem pública e a segurança nacional
- **Convocação de Suplente**: Procedimento pelo qual um substituto é convocado para assumir a função de um parlamentar licenciado

### Referências legais
- Art. 56, § 1º, CF/88
- Súmula N STF
- Art. X da Lei Y

### Jurisprudência
- MS 25579/2005
- ADI 7253/AC
- RE 123456

### Dicas de prova
- Entenda a noção de imunidades e sua aplicação nos casos de estado de sítio e convocação de suplentes.
- Conheça o princípio da supremacia do Poder Legislativo e como ele se aplica à disciplina dos congressistas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.438 (1)", "page_number": 438, "discipline": "Direito Constitucional", "legal_refs": ["Art. 56, § 1º, CF/88", "Súmula N STF", "Art. X da Lei Y"], "jurisprudence": ["MS 25579/2005", "ADI 7253/AC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T13:43:21.092233+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=438", "doc_key": "1a25830efadf123830c835a64ffefb24"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd693c97ec7d3d5e38cafbbc4a62e480704ef0705245f5f059fe3670892b3b071'),
  ('cpiuris2025::e95801bb841f273879c55d8832d16006', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sucessão no mandato de Senador cassado', '## Sucessão no mandato de Senador cassado

A sucessão no mandato de Senador cassado não é automatica, pois a cassação do mandato invalida a própria votação obtida pelo candidato e afeta a legitimidade do vencedor, necessitando renovação do pleito.

### Conceitos
- **Sucessão no mandato**: O processo pelo qual um novo membro assume o cargo de um que abandonou ou foi cassado
- **Cassação do mandato**: A decisão da Justiça Eleitoral que invalida o mandato de um Senador
- **Renovação do pleito**: O processo pelo qual se realiza uma nova eleição para preencher o cargo vago
- **Legitimidade das eleições**: A qualidade de ser legítimo ou não, em relação às eleições
- **Moralidade administrativa**: O princípio que exige que os funcionários públicos sejam moralmente dignos

### Referências legais
- Art. 56 § 1º da CF/88
- Súmula 643/STF
- Súmula 644/STF

### Jurisprudência
- RE 123456
- ADPF 643/DF
- ADPF 644/DF

### Dicas de prova
- Perguntam sobre a sucessão no mandato de Senador cassado
- Distinção entre renovação do pleito e sucessão no mandato
- Importância da legitimidade das eleições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.438 (2)", "page_number": 438, "discipline": "Direito Constitucional", "legal_refs": ["Art. 56 § 1º da CF/88", "Súmula 643/STF", "Súmula 644/STF"], "jurisprudence": ["RE 123456", "ADPF 643/DF", "ADPF 644/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:44:09.732617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=438", "doc_key": "e95801bb841f273879c55d8832d16006"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7a10ada703cc144b10960f955894130d62455f2127e7f802b9bfff5fc1e58c7f'),
  ('cpiuris2025::a9a73c5a4de22d098a409cc27d4c96d6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Incompatibilidades e Perda do Mandato', '## Incompatibilidades e Perda do Mandato

O art. 54 e 55 da CF/88 estabelecem regras para incompatibilidades dos deputados e senadores, além de procedimentos para a perda do mandato em caso de infrações.

### Conceitos
- **Incompatibilidade**: Evitar o exercício da influência para alcançar favores indevidos.
- **Proibição**: Restrição ao exercício de certas atividades ou ações
- **Decoro Parlamentar**: Conduzir-se com dignidade e respeito em relação à função pública.

### Referências legais
- Art. 54, CF/88
- Art. 55, CF/88

### Dicas de prova
- Entenda a distinção entre incompatibilidade e proibição.
- Conheça as causas que levam à perda do mandato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.439 (1)", "page_number": 439, "discipline": "Direito Constitucional", "legal_refs": ["Art. 54, CF/88", "Art. 55, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:44:38.377395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=439", "doc_key": "a9a73c5a4de22d098a409cc27d4c96d6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '712d1eafaf57ce627c82147f7e51ab024cdc204f5f71eb62e50f4c16abdd498b'),
  ('cpiuris2025::9684442134a1b84279ad066b502904bb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Decoro Parlamentar', '## Decoro Parlamentar

A quebra do decoro parlamentar é aferida pela Casa Legislativa, mas o Judiciário pode analisar os pressupostos de legalidade da medida e o STF aprecia se foram respeitados o contraditório, ampla defesa e devido processo legal.

### Conceitos
- **Decoro Parlamentar**: conjunto de regras legais e morais que envolvem o exercício de atividade parlamentar
- **Contraditório**: direito do interessado de se manifestar sobre a decisão tomada pela autoridade competente
- **Ampla Defesa**: direito do interessado de ter assistência jurídica técnica e gratuita, quando for o caso
- **Devido Processo Legal**: direito do interessado de ser informado sobre a decisão tomada pela autoridade competente

### Referências legais
- Art. 58 da Constituição Federal
- Súmula 401/STF

### Jurisprudência
- Informativo 401/STF
- Informativo 406/STF

### Dicas de prova
- Entenda a importância do decoro parlamentar e como ele é regulamentado pela Constituição Federal.
- Conheça os direitos do interessado em relação à decisão tomada pela autoridade competente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.439 (2)", "page_number": 439, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal", "Súmula 401/STF"], "jurisprudence": ["Informativo 401/STF", "Informativo 406/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:45:08.197957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=439", "doc_key": "9684442134a1b84279ad066b502904bb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '71b34d1eab6d662cb2a3bbfa9f19e11b7d5fdab79916c7b00e721ae3cd91df2e'),
  ('cpiuris2025::d4c47f2da6dea9904a7aa1c2d02432f0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade e Competência da Corte Suprema no Mérito da Perda de Mandato', '## Legitidade e Competência da Corte Suprema no Mérito da Perda de Mandato

A Corte Suprema não tem legitimidade e competência para decidir o mérito da perda de mandato por decoro parlamentar. A decisão é interna da Câmara ou do Senado, dependendo do cargo. Em casos de condenação criminal transitada em julgado, a perda do mandato depende da decisão da Casa Legislativa.

### Conceitos
- **Legitidade e Competência**: A capacidade e autoridade para agir em um determinado campo
- **Mérito**: O aspecto substancial de uma questão ou caso, que é objeto de análise e decisão
- **Perda de Mandato**: A extinção do cargo de parlamentar por decoro ou condenação criminal
- **Corte Suprema**: O órgão mais alto do sistema judiciário, responsável por interpretar a Constituição e decidir casos importantes

### Referências legais
- Art. 55, inciso VI da CF
- Informativo 863/STF
- Informativo 903/STF
- Ação Penal 694/2017
- Ação Penal 968/2018
- Ação Penal 996/2018

### Jurisprudência
- RE 123456
- Tema repetitivo: Legitidade e Competência da Corte Suprema no Mérito da Perda de Mandato

### Dicas de prova
- Entenda a distinção entre a legitimidade e competência da Corte Suprema em relação à perda de mandato.
- Conheça as diferentes posições do STF sobre a aplicação do §2º do art. 55 na condenação criminal transitada em julgado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.440 (1)", "page_number": 440, "discipline": "Direito Constitucional", "legal_refs": ["Art. 55, inciso VI da CF", "Informativo 863/STF", "Informativo 903/STF", "Ação Penal 694/2017", "Ação Penal 968/2018", "Ação Penal 996/2018"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legitidade e Competência da Corte Suprema no Mérito da Perda de Mandato"], "confidence": 0.8, "extracted_at": "2026-05-26T13:46:04.540879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=440", "doc_key": "d4c47f2da6dea9904a7aa1c2d02432f0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f987033ef0c38d46b76fc28a6cca9f78b1226288e19ce30576a68574b1616ddb'),
  ('cpiuris2025::c687539f6e0472ac495e22ca0269c2a8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Perda do Mandato dos Deputados e Senadores', '## Perda do Mandato dos Deputados e Senadores

A perda do mandato depende da decisão da Casa, por maioria absoluta e em votação aberta, independentemente do tipo de regime.

### Conceitos
- **Mandato**: direito político que concede ao parlamentar a representação popular
- **Casa**: Câmara dos Deputados ou Senado Federal
- **Maoria absoluta**: voto de maioria absoluta, necessária para tomar decisões importantes
- **Votação aberta**: votação em que os membros da Casa podem expressar suas opiniões livremente

### Referências legais
- Art. 55, §2º da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a diferença entre regime aberto e semiaberto
- Conheça o artigo 55, §2º da Constituição
- A importância da maioria absoluta na decisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.440 (2)", "page_number": 440, "discipline": "Direito Constitucional", "legal_refs": ["Art. 55, §2º da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:46:31.021213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=440", "doc_key": "c687539f6e0472ac495e22ca0269c2a8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8944eb31b38fa56793c583d0f9038ce1798976fa97316ddb03877c9f0f148d37'),
  ('cpiuris2025::54ea6dad33d3d781ff457de272e27b22', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autocontenção e limites do ativismo judicial', '## Autocontenção e limites do ativismo judicial

O STF só pode interferir em procedimentos legislativos para garantir o cumprimento da Constituição, proteger direitos fundamentais ou resguardar a democracia. A autocontenção é uma técnica que visa evitar intervenção política do Poder Judiciário.

### Conceitos
- **Autocontenção**: Técnica que visa evitar intervenção política do Poder Judiciário
- **Ativismo judicial**: Intervenção excessiva ou política do Poder Judiciário
- **Independência dos poderes**: Respeito pela autonomia e autoridade de cada poder do Estado

### Referências legais
- Art. 55, §2º e §3º da CF/88

### Dicas de prova
- Entenda a diferença entre autocontenção e ativismo judicial
- Conheça as hipóteses em que o STF pode interferir em procedimentos legislativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.441 (1)", "page_number": 441, "discipline": "Direito Constitucional", "legal_refs": ["Art. 55, §2º e §3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:46:58.983974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=441", "doc_key": "54ea6dad33d3d781ff457de272e27b22"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '17d413eaea10e82a85e661d397c609d8838c201d14b7fa4e8909047a723b82f7'),
  ('cpiuris2025::ad8125a391b31851c4c38fa3ee10b82f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Suspensão de Efeitos em Processo que Vise à Perda do Mandato', '## Suspensão de Efeitos em Processo que Vise à Perda do Mandato

O processo que vise ou possa levar à perda do mandato terá seus efeitos suspensos até as deliberações finais da Casa respectiva. A renúncia, nesse caso, não traz benefício, pois implica na inelegibilidade pelo prazo de oito anos.

### Conceitos
- **Suspensão de Efeitos**: Mudança temporária da aplicação de uma decisão ou ato
- **Perda do Mandato**: Fim do mandato de um político
- **Prerrogativa**: Direito especial de um político
- **Inelegibilidade**: Impossibilidade de ser eleito por um período determinado

### Referências legais
- Art. 58 da Constituição Federal

### Dicas de prova
- Diferenciar entre suspensão e não suspensão de efeitos
- Entender a importância da prerrogativa no caso de perda do mandato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.441 (2)", "page_number": 441, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:47:37.274805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=441", "doc_key": "ad8125a391b31851c4c38fa3ee10b82f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '22504ca373eb43cf9a42247ae0574ca759cbf4d6cf631aef3b40f904afe472ba'),
  ('cpiuris2025::4b529b741e79cf49aa3830ddb39b82ac', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tribunais de Contas e Poder Legislativo', '## Tribunais de Contas e Poder Legislativo

Os Tribunais de Contas são órgãos vinculados ao Poder Legislativo, auxiliando no controle externo da administração. Eles não têm hierarquia com o Poder Legislativo e suas decisões não fazem parte do sistema jurídico civil.

### Conceitos
- **Tribunal de Contas**: órgão vinculado ao Poder Legislativo, auxiliando no controle externo da administração
- **Poder Legislativo**: entidade do Estado que tem como função legislar e controlar o Poder Executivo
- **Hierarquia**: relação de superioridade entre entidades ou órgãos do Estado

### Referências legais
- Art. 73 da Constituição Federal
- §1º do art. 73 da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a relação entre o Tribunal de Contas e o Poder Legislativo.
- Conheça os requisitos para ser ministro do TCU.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.442 (1)", "page_number": 442, "discipline": "Direito Constitucional", "legal_refs": ["Art. 73 da Constituição Federal", "§1º do art. 73 da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:48:11.051167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=442", "doc_key": "4b529b741e79cf49aa3830ddb39b82ac"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1d8b8bc670d728695f7160616e540570fbe2f0ee1c0cebe5d1d907e9afc29305'),
  ('cpiuris2025::90fa2e92592f6329c05c5a06cfc745d2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Fiscalização Contábil e Financeira', '## Fiscalização Contábil e Financeira

A fiscalização contábil, financeira, orçamentária, operacional e patrimonial da União e das entidades da administração direta e indireta é exercida pelo Congresso Nacional, mediante controle externo.

### Conceitos
- **Controle Externo**: Exercido pelo Poder Legislativo
- **Poder Legislativo**: Unidade do Estado que tem como função legislar e fiscalizar
- **TCU**: Tribunal Contábil, Financeiro e de Controle
- **Fiscalização Contábil**: Exercício do controle sobre a gestão financeira da União e das entidades da administração direta e indireta
- **Controle Interno**: Exercido pelo próprio órgão ou entidade administrada
- **Administração Direta e Indireta**: As entidades que executam as políticas públicas

### Referências legais
- Art. 59 da CF/88

### Dicas de prova
- Entenda a distinção entre controle interno e externo
- Conheça o papel do TCU na fiscalização contábil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.442 (2)", "page_number": 442, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:48:40.720798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=442", "doc_key": "90fa2e92592f6329c05c5a06cfc745d2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7ba3633e47c46d520934c5cef55df0fc62c67b90d3d2f034cda95a1296cc586b'),
  ('cpiuris2025::0c85026fab5669e72adc8d988f1ca1cc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poderes do Tribunal de Contas', '## Poderes do Tribunal de Contas

O Tribunal de Contas tem atribuições para apreciar contas públicas, fiscalizar despesas e aplicar sanções em caso de ilegalidade.

### Conceitos
- **Atribuição do TC**: Compete ao TC apreciar contas prestadas anualmente pelo Presidente da República
- **Fiscalização**: O TC realiza inspeções e auditorias para fiscalizar despesas e aplicação de recursos
- **Sanções**: O TC pode aplicar sanções em caso de ilegalidade de despesa ou irregularidade de contas

### Referências legais
- Art. 71 da Constituição

### Dicas de prova
- Entenda a importância do Tribunal de Contas na fiscalização das contas públicas
- Conheça as atribuições específicas do TC e como elas se relacionam com o art. 71 da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.443 (1)", "page_number": 443, "discipline": "Direito Constitucional", "legal_refs": ["Art. 71 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:49:22.035624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=443", "doc_key": "0c85026fab5669e72adc8d988f1ca1cc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '77b2d43eb9cd17c21d904896ad3459455494733da2f4b36fea2d0001216475ee'),
  ('cpiuris2025::0bae6649a17e3cb6aef457400e2854fd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade do TCU para anular acordos extrajudiciais', '## Legitimidade do TCU para anular acordos extrajudiciais

O TCU tem legitimidade para anular acordos extrajudiciais celebrados entre particulares e a administração pública, desde que não homologados judicialmente. No entanto, se o acordo for homologado judicialmente, o TCU não pode anulá-lo.

### Conceitos
- **Legitimidade**: Qualidade de ser qualificado para agir em um determinado campo
- **TCU**: Tribunal de Contas, órgão responsável pela fiscalização e controle dos atos da administração pública
- **Acordo extrajudicial**: Convenção ou acordo celebrada entre particulares e a administração pública sem a intervenção do Poder Judiciário
- **Homologação judicial**: Decisão do juiz que confirma a validade de um acordo extrajudicial
- **Indisponibilidade dos bens**: Medida adotada pelo TCU para proteger os bens de uma pessoa em decorrência de irregularidades ou abusos

### Referências legais
- Art. 44, §2º, da Lei nº 8.443/92

### Jurisprudência
- Info 779, STF; Info 780, STF

### Dicas de prova
- Distinção entre homologação judicial e não-homologação
- Legitimidade do TCU para anular acordos extrajudiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.443 (2)", "page_number": 443, "discipline": "Direito Constitucional", "legal_refs": ["Art. 44, §2º, da Lei nº 8.443/92"], "jurisprudence": ["Info 779, STF; Info 780, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:50:02.341213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=443", "doc_key": "0bae6649a17e3cb6aef457400e2854fd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '09e8163f7751923eedbf6abb95d3d558a3145fd141dc3e89d84798f1b0070b74'),
  ('cpiuris2025::bf3bd96727eaa280dddea15fa5ee9996', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do TCU e Poderes Implícitos', '## Competência do TCU e Poderes Implícitos

O Tribunal de Contas (TCU) tem competência para julgar as contas do Presidente da República, governador de Estado e prefeito. O TCU também possui poderes para expedir medidas cautelares com base na teoria dos poderes implícitos. A competência do TCU é garantida pela Constituição Federal, que atribui meios para alcançar a finalidade da sua função.

### Conceitos
- **Competência do TCU**: A competência do Tribunal de Contas (TCU) é determinada pela Constituição Federal e inclui a julgamento das contas do Presidente da República, governador de Estado e prefeito.
- **Poderes Implícitos**: A teoria dos poderes implícitos estabelece que a Constituição Federal garante meios para alcançar a finalidade da função do TCU.
- **Medidas Cautelares**: O TCU pode expedir medidas cautelares com base na teoria dos poderes implícitos para garantir a sua competência.
- **Competência do TCU em Investigações Financeiras**: O TCU não tem competência para requisitar a quebra de sigilo bancário, mas pode exigir informações específicas quando há recursos públicos envolvidos.

### Referências legais
- Art. 89 da CF/88
- Súmula Vinculante 3, STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência do TCU e os poderes implícitos.
- Conheça a teoria dos poderes implícitos e suas aplicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.444 (1)", "page_number": 444, "discipline": "Direito Constitucional", "legal_refs": ["Art. 89 da CF/88", "Súmula Vinculante 3, STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:50:44.571504+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=444", "doc_key": "bf3bd96727eaa280dddea15fa5ee9996"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '531cf0510285358eb016fe35b0a33b4245f390dea28914ed68aca6781ffbef5e'),
  ('cpiuris2025::3faad19ed668e166a0cc0051d0050629', 'doutrina', 'cp_iuris', 'Direito Constitucional — Contraditório e Ampla Defesa no Tribunal de Contas da União', '## Contraditório e Ampla Defesa no Tribunal de Contas da União

O contraditório e a ampla defesa são garantidos nos processos do Tribunal de Contas da União, exceto na apreciação da legalidade do ato de concessão inicial de aposentadoria, reforma e pensão, desde que não haja o transcurso de cinco anos sem emissão do ato de controle.

### Conceitos
- **Contraditório**: Direito do interessado participar da decisão que afeta seus direitos
- **Ampla Defesa**: Direito do interessado ter acesso a todos os fatos e provas relevantes para a decisão
- **Tribunal de Contas da União**: Entidade responsável por controlar a gestão pública federal

### Referências legais
- Art. 5º, LIV, da CF; Súmula Vinculante n° 3/2014 do STF

### Jurisprudência
- RE 123456
- Súmula Vinculante n° 3/2014 do STF

### Dicas de prova
- Entenda a exceção que não é mais aplicável
- Conheça o prazo de cinco anos sem emissão do ato de controle', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.444 (2)", "page_number": 444, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV, da CF; Súmula Vinculante n° 3/2014 do STF"], "jurisprudence": ["RE 123456", "Súmula Vinculante n° 3/2014 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:51:25.489940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=444", "doc_key": "3faad19ed668e166a0cc0051d0050629"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b77325f28fc1567d9d89c093ccdd4c24e5bd2035cffdff60aa96a8419dfc7462'),
  ('cpiuris2025::04afdf0a2b0531e856de6ca8ac213c73', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tribunal de Contas (TCU) e controle externo', '## Tribunal de Contas (TCU) e controle externo

O Tribunal de Contas pode apreciar a constitucionalidade das leis, mas apenas pelo controle concreto. Os Tribunais de Contas devem observar a cláusula de reserva de plenário e não podem manter o sigilo de uma denúncia apresentada contra um administrador público.

### Conceitos
- **Tribunal de Contas**: órgão responsável pela fiscalização contábil, financeira e orçamentária
- **controle externo**: exercido pelo Tribunal de Contas para garantir a observância das leis e normas
- **cláusula de reserva de plenário**: requisito para que o Tribunal de Contas possa apreciar a constitucionalidade de uma lei
- **controle concreto**: exercido pelo Tribunal de Contas apenas em casos específicos, e não abstratamente
- **sigilo de denúncia**: proibição de revelar a identidade da pessoa que fez a denúncia contra um administrador público

### Referências legais
- Art. 55 da Lei Orgânica do TCU
- Súmula 857/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: controle externo e Tribunais de Contas

### Dicas de prova
- Entenda a diferença entre controle concreto e abstrato
- Conheça a cláusula de reserva de plenário e sua importância para o Tribunal de Contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.445 (1)", "page_number": 445, "discipline": "Direito Constitucional", "legal_refs": ["Art. 55 da Lei Orgânica do TCU", "Súmula 857/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: controle externo e Tribunais de Contas"], "confidence": 0.8, "extracted_at": "2026-05-26T13:52:09.379897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=445", "doc_key": "04afdf0a2b0531e856de6ca8ac213c73"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cfd1bbca1f66aa0103585a4701bebe10a66ab814bd32dd184579f726faa5ab52'),
  ('cpiuris2025::4b9a7bd60cf2d7936e3687bca0aa10e3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Escolha dos membros do Tribunal de Contas e procedimento com as contas municipais', '## Escolha dos membros do Tribunal de Contas e procedimento com as contas municipais

A CF/88 estabelece que os TCs estaduais, distritais e municipais são compostos por sete conselheiros. O STF determinou que três serão escolhidos pelo governador e quatro pela Assembleia Legislativa. Além disso, a LC n.º 64/1990 prevê que os políticos inelegíveis ficam após o rejeitão de suas contas por órgão competente.

### Conceitos
- **Tribunal de Contas**: órgão responsável por fiscalizar as contas públicas
- **Câmara Municipal**: órgão legislativo municipal
- **Governador**: chefe do Poder Executivo estadual
- **Assembleia Legislativa**: órgão legislativo estadual
- **Ministério Público**: órgão responsável por fiscalizar a conduta dos políticos
- **Ficha-limpa**: procedimento que visa identificar e punir os políticos com contas rejeitadas

### Referências legais
- Art. 58 da CF/88
- LC n.º 64/1990, art. 1º

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a estrutura do Tribunal de Contas e o papel da Câmara Municipal na fiscalização das contas públicas.
- Conheça a legislação específica sobre a ficha-limpa e as consequências para os políticos inelegíveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.445 (2)", "page_number": 445, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF/88", "LC n.º 64/1990, art. 1º"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:52:57.393115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=445", "doc_key": "4b9a7bd60cf2d7936e3687bca0aa10e3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bdc6a9de11e1263a90460e0688c6edcdaf48a164d92f5c8ee26791fb65d52bab'),
  ('cpiuris2025::fba59825b62f49ef6e938560a1980771', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tribunais de Contas e competência legislativa', '## Tribunais de Contas e competência legislativa

O Tribunal de Contas tem a função de admitir pareceres prévios, que podem ser ou não aprovados pela Câmara dos Vereadores. A Câmara é quem decide sobre a inelegibilidade do prefeito, mas o Tribunal de Contas apenas admite o parecer. Além disso, os Tribunais de Contas estaduais têm as mesmas prerrogativas que o TCU da União.

### Conceitos
- **Tribunal de Contas**: órgão responsável por fiscalizar a gestão pública
- **Câmara dos Vereadores**: órgão legislativo que decide sobre a inelegibilidade do prefeito
- **inelegibilidade**: situação em que o prefeito não pode se candidatar às eleições
- **competência legislativa**: poder do legislador para tomar decisões sobre questões públicas

### Referências legais
- Art. 1º, I, ''g'', da LC n.º 64/1990
- Art. 31, §2º, da CF
- Art. 70 a 75 da CF/88

### Jurisprudência
- RE 123456
- Info 851
- Informativo 834

### Dicas de prova
- Entenda a distinção entre o Tribunal de Contas e a Câmara dos Vereadores
- Conheça a competência legislativa e como ela se aplica aos Tribunais de Contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.446 (1)", "page_number": 446, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, I, ''g'', da LC n.º 64/1990", "Art. 31, §2º, da CF", "Art. 70 a 75 da CF/88"], "jurisprudence": ["RE 123456", "Info 851", "Informativo 834"], "confidence": 0.8, "extracted_at": "2026-05-26T13:53:50.338916+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=446", "doc_key": "fba59825b62f49ef6e938560a1980771"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8a3857bf85386568e9c29da9457b3a8c3d65cc4f8403405667fd146bd8dbcc5a'),
  ('cpiuris2025::37625fe0a8b0777849de54be0dd1123e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências dos Tribunais de Contas e Execução de Acordões', '## Competências dos Tribunais de Contas e Execução de Acordões

Os Tribunais de Contas estaduais têm competência para aplicar sanções a responsáveis por ilegalidades em despesas ou irregularidades em contas, com eficácia de título executivo extrajudicial.

### Conceitos
- **Título Executivo Extrajudicial**: Decisão do Tribunal de Contas que tem eficácia imediata e pode ser executada sem a necessidade de uma ação judicial.
- **Execução de Título**: Procedimento pelo qual o Estado busca a execução de uma decisão judicial ou extrajudicial para cobrar um débito.
- **Responsável**: Pessoa física ou jurídica que é condenada por ilegalidade em despesas ou irregularidades em contas.
- **Condenação**: Decisão do Tribunal de Contas que condena uma pessoa a pagar uma multa ou ressarcir o erário.
- **Multidão**: Multa proporcional ao dano causado ao erário, estabelecida pela lei.
- **Irregularidade de Contas**: Ocorrência de erro ou falta no gerenciamento das contas públicas.
- **Dêbito**: Dever que o Estado tem em relação a uma pessoa, geralmente decorrente de um contrato ou obrigação.

### Referências legais
- Art. 71 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre título executivo judicial e extrajudicial.
- Conheça as sanções aplicáveis às irregularidades em contas públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.446 (2)", "page_number": 446, "discipline": "Direito Constitucional", "legal_refs": ["Art. 71 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:54:34.582119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=446", "doc_key": "37625fe0a8b0777849de54be0dd1123e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c965522543e7b94c8b7852af88cc24ca56a43ed14f28f5f6617e0e477414477d'),
  ('cpiuris2025::c1dc4b78c0f840fcb6c4f3dcd5dba904', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade para Execução Judicial de Acórdãos do Tribunal de Contas', '## Legitimidade para Execução Judicial de Acórdãos do Tribunal de Contas

A decisão do Tribunal de Contas não precisa ser inscrita em dívida ativa, pois o próprio acórdão tem eficácia de título executivo extrajudicial. A legitimidade para propor a execução do acórdão é apenas do ente público prejudicado com a atuação do gestor.

### Conceitos
- **Legitimidade Ativa**: O direito de uma parte tomar medidas em um processo
- **Título Executivo Extrajudicial**: Eficácia da decisão do Tribunal de Contas sem necessidade de inscrição em dívida ativa
- **Execução Civil de Título Extrajudicial**: Regras aplicadas à execução de crédito decorrente de título executivo extrajudicial
- **Dívida Ativa**: Debito que precisa ser inscrito em dívida ativa para ser cobrado

### Referências legais
- Art. 71, §3º da CF/88

### Jurisprudência
- RE 1003433/RJ
- Tema 642 - STF Plenário

### Dicas de prova
- Distinção entre legitimidade ativa e passiva para a execução judicial de acórdãos do Tribunal de Contas
- Regras aplicadas à execução civil de título executivo extrajudicial
- Importância da titularidade do crédito para a cobrança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.447", "page_number": 447, "discipline": "Direito Constitucional", "legal_refs": ["Art. 71, §3º da CF/88"], "jurisprudence": ["RE 1003433/RJ", "Tema 642 - STF Plenário"], "confidence": 0.8, "extracted_at": "2026-05-26T13:55:16.382711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=447", "doc_key": "c1dc4b78c0f840fcb6c4f3dcd5dba904"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1a53a39ea1a1df23d6af5f75b2c3026ddaf65ecbf506b4891d890b1b54f9ee18'),
  ('cpiuris2025::2a4fbcc911e6b5b3c3ead8d55e567c29', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo', '## Processo Legislativo

É um conjunto de regras que visa à produção de normas jurídicas no ordenamento, diferenciado dos atos normativos derivados do direito administrativo.

### Conceitos
- **Autocrático**: Processo legislativo elaborado pelo governante que impõe a sua norma.
- **Indireto (representativo)**: Predomina nos Estados democráticos, onde os cidadãos escolhem representantes que elaboram as leis de acordo com a vontade do povo.
- **Direto**: Processo legislativo feito diretamente pelo povo.
- **Semidireto**: Há representantes que elaboram o projeto, submetido à apreciação do povo para aprovar ou não a norma.

### Referências legais
- Art. 58 da Constituição Brasileira de 1988

### Dicas de prova
- Diferenciar entre autocrático e indireto (representativo) para evitar confusão.
- Entender a classificação do processo legislativo em direto, semidireto e indireto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.449", "page_number": 449, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:56:06.533384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=449", "doc_key": "2a4fbcc911e6b5b3c3ead8d55e567c29"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '24be55ac83225cdaf7f998674935f925901198427c89350f98483169c0f1fcc1'),
  ('cpiuris2025::21186ab98cb5c52766cc10476fcac95c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo', '## Processo Legislativo

O processo legislativo é dividido em três etapas: iniciativa, constitutiva e complementar. A iniciativa é feita por deputados ou senadores, comissões ou até mesmo o Presidente da República.

### Conceitos
- **Iniciativa**: Faculdade atribuída a um ente para iniciar um processo legislativo
- **Fase introdutória**: Fase que introduz o projeto de lei, com iniciativa do projeto de lei
- **Fase constitutiva**: Fase em que se elabora a proposição legislativa
- **Fase complementar**: Fase final do processo legislativo, com aprovação ou rejeição da proposição

### Referências legais
- Art. 61, §2º, CF

### Dicas de prova
- Entenda a diferença entre o processo legislativo ordinário e sumário
- Conheça as fases do processo legislativo (iniciativa, constitutiva e complementar)
- Identifique os principais prazos e sanções no processo legislativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.450", "page_number": 450, "discipline": "Direito Constitucional", "legal_refs": ["Art. 61, §2º, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:56:52.095843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=450", "doc_key": "21186ab98cb5c52766cc10476fcac95c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '55fba84b97ad96a573de37cdbdb009dd22d2e78058eca255c581e8387063f521'),
  ('cpiuris2025::418c7b317346b82bffa0b8b177333235', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Legislativa', '## Iniciativa Legislativa

A iniciativa das leis cabe a qualquer membro da Câmara dos Deputados, do Senado Federal ou do Congresso Nacional, ao Presidente da República, ao Supremo Tribunal Federal, aos Tribunais Superiores, ao Procurador-Geral da República e aos cidadãos, de acordo com as hipóteses previstas na Constituição.

### Conceitos
- **Iniciativa Legislativa**: Poder do Parlamento ou do Presidente da República para apresentar projetos de lei
- **Parlamentar**: Qualquer deputado ou senador pode propor a iniciativa de projeto de lei
- **Extraparlamentar**: Iniciativa que vem de fora do Parlamento, incluindo o Chefe do Executivo, Procurador-Geral da República e Tribunais
- **Geral**: Poder dos parlamentares e cidadãos para dar início a qualquer projeto de lei, ressalvadas matérias reservadas
- **Restrita**: Iniciativa que ocorre quando uma autoridade ou órgão só pode apresentar projetos de lei sobre determinada matéria
- **Reservada (exclusiva)**: Só um órgão ou autoridade pode propor lei sobre aquela matéria
- **Concorrente**: Iniciativa que pertence simultaneamente a mais de um legitimado

### Referências legais
- Art. 61, CF/88

### Dicas de prova
- Entenda as hipóteses de iniciativa legislativa e suas limitações
- Conheça as diferenças entre iniciativa geral, restrita, reservada e concorrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.451 (1)", "page_number": 451, "discipline": "Direito Constitucional", "legal_refs": ["Art. 61, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T13:57:58.925535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=451", "doc_key": "418c7b317346b82bffa0b8b177333235"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5c0b4931ec082d3121525977470865d93ea46a455dceafeb63a53726ef14b1ff'),
  ('cpiuris2025::00266255ec9eaf3cdff1620b41b8e261', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Legislativa', '## Iniciativa Legislativa

O sujeito é obrigado a dar início ao processo legislativo para o projeto de lei, como nas leis orçamentárias. A iniciativa pode ser exercida por parlamentares ou entidades extraparlamentares.

### Conceitos
- **Iniciativa Legislativa**: O ato de apresentar um projeto de lei ao Poder Legislativo
- **Casa Iniciadora**: A Câmara dos Deputados, que recebe projetos de lei propostos por entidades extraparlamentares ou comissões mistas
- **Comissão Mista**: Uma comissão composta por membros de diferentes Casas Legislativas, que pode propor projetos de leis

### Referências legais
- Art. 58 da CF
- Art. 61 da CF

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a distinção entre iniciativa parlamentar e extraparlamentar
- Conheça as regras para a apresentação de projetos de leis em diferentes Casas Legislativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.451 (2)", "page_number": 451, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF", "Art. 61 da CF"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T13:58:42.699452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=451", "doc_key": "00266255ec9eaf3cdff1620b41b8e261"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b9e963efe90cf6340ed86050bed1df51ad6eb1045196a40f6e1d2b9794021ab6'),
  ('cpiuris2025::d27c59febf339992c4ea4ccddf41c21e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Popular', '## Iniciativa Popular

A iniciativa popular é um meio de participação popular do cidadão, permitindo a apresentação de projetos de lei que não estejam previstos na legislativa privativa. É obrigatória em municípios e pode ser exercida por 1% do eleitorado nacional, distribuído por pelo menos cinco estados.

### Conceitos
- **Iniciativa Popular**: Meio de participação popular do cidadão para apresentar projetos de lei
- **Legislativa Privativa**: Matérias previstas na Constituição que não podem ser tratadas por iniciativa popular ou parlamentar
- **Capacidade Eleitoral Ativa**: Título eleitoral necessário para exercer a iniciativa popular
- **Princípio da Simetria**: Requisito de igualdade entre os poderes do Estado, garantindo que as competências sejam distribuídas de forma justa e equitativa

### Referências legais
- Art. 29, XIII da CF/88
- Art. 61, §1º da CF/88
- Súmula N do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre iniciativa popular e legislativa privativa
- Capacidade eleitoral ativa para exercer a iniciativa popular
- Princípio da simetria e sua aplicação nas competências do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.452 (1)", "page_number": 452, "discipline": "Direito Constitucional", "legal_refs": ["Art. 29, XIII da CF/88", "Art. 61, §1º da CF/88", "Súmula N do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T13:59:38.421767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=452", "doc_key": "d27c59febf339992c4ea4ccddf41c21e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1ffb2fc6679e7d2e89bdc516e8f120400447a2ca6c2ca1163b549f0a30935873'),
  ('cpiuris2025::6569a1c837ee259fa3bfeb37fa80e749', 'doutrina', 'cp_iuris', 'Direito Constitucional — Usurpação do Poder de Iniciativa', '## Usurpação do Poder de Iniciativa

A usurpação do poder de iniciativa é considerada inconstitucional quando uma lei federal cria conselhos de fiscalização profissional sem a necessidade de lei de iniciativa do Presidente da República.

### Conceitos
- **Usurpação do Poder de Iniciativa**: Ato ilegal de exercer poder que não é próprio
- **Lei de Iniciativa**: Lei que define o processo de elaboração de leis
- **Conselhos de Fiscalização Profissional**: Entidades que regulamentam a profissão

### Referências legais
- CF/1988, art. 61, § 1º, II, “a”

### Jurisprudência
- Info. 108459, STF

### Dicas de prova
- Distinção entre lei de iniciativa do Presidente da República e lei federal
- Importância da lei de iniciativa para a criação de autarquias federais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.452 (2)", "page_number": 452, "discipline": "Direito Constitucional", "legal_refs": ["CF/1988, art. 61, § 1º, II, “a”"], "jurisprudence": ["Info. 108459, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:00:12.008206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=452", "doc_key": "6569a1c837ee259fa3bfeb37fa80e749"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5563e4b89df44d07bb194cfc3b18cfe78247409d92d4ae658a9204e676e2a5a2'),
  ('cpiuris2025::91ec589a2238906a9e002f6003e0dde8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa do Poder Judiciário e Legislativo', '## Iniciativa do Poder Judiciário e Legislativo

A iniciativa é competência exclusiva do STF, Tribunais Superiores e Tribunais de Justiça para alteração do número de membros dos tribunais, criação e extinção de cargos e matéria relacionada à remuneração e subsídios. O Presidente da República tem iniciativa privativa nas matérias tributárias e administrativas, mas apenas no âmbito dos territórios federais.

### Conceitos
- **Iniciativa do Poder Judiciário**: Competência exclusiva do STF, Tribunais Superiores e Tribunais de Justiça
- **Legislativo**: Compete ao Legislativo a iniciativa de projeto de lei para alteração do número de membros dos tribunais
- **Iniciativa Privativa**: Competência exclusiva do Presidente da República nas matérias tributárias e administrativas, mas apenas no âmbito dos territórios federais
- **Prazo para exercício de iniciativa**: Não pode o Legislativo fixar prazo para que aquele que detém o poder de iniciativa exerça sua competência
- **Competência Exclusiva**: A competência é exclusiva do STF, Tribunais Superiores e Tribunais de Justiça

### Referências legais
- Art. 93 da CF/88
- Art. 102 da LOMAN (LC n.º 35/1979)

### Jurisprudência
- RE 123456
- Tema repetitivo sobre iniciativa do Poder Judiciário e Legislativo

### Dicas de prova
- Entenda a competência exclusiva do STF, Tribunais Superiores e Tribunais de Justiça
- Interprete a iniciativa privativa do Presidente da República nas matérias tributárias e administrativas
- Conheça o prazo para exercício de iniciativa reservada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.453 (1)", "page_number": 453, "discipline": "Direito Constitucional", "legal_refs": ["Art. 93 da CF/88", "Art. 102 da LOMAN (LC n.º 35/1979)"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre iniciativa do Poder Judiciário e Legislativo"], "confidence": 0.8, "extracted_at": "2026-05-26T14:01:42.459208+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=453", "doc_key": "91ec589a2238906a9e002f6003e0dde8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4551679f1f7de861c44928cecf118c3e8ca3324e490799d97a6df719ae848ae6'),
  ('cpiuris2025::c8671d568b85d6ec71a3bb5509a614d0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Legislativo e Executivo', '## Poder Legislativo e Executivo

O Poder Judiciário não pode determinar projetos de lei, mas pode declarar a inconstitucionalidade por omissão de leis. O Congresso Nacional tem a prerrogativa de dar início ao processo legislativo.

### Conceitos
- **Poder Legislativo**: O Poder que detém a iniciativa do processo legislativo.
- **Prerrogativa**: Direito exclusivo de uma entidade ou pessoa para agir em determinada área.
- **Mora**: Atraso ou demora na execução de uma tarefa ou ação.
- **Decisão do STF**: A decisão do Supremo Tribunal Federal que estabelece regras e diretrizes para o processo legislativo.

### Referências legais
- Art. 58 da Constituição de 1988
- Súmula 822 do STF

### Jurisprudência
- RE 123456/2016

### Dicas de prova
- Entenda a relação entre o Poder Legislativo e o Poder Executivo.
- Conheça a importância da prerrogativa no processo legislativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.453 (2)", "page_number": 453, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição de 1988", "Súmula 822 do STF"], "jurisprudence": ["RE 123456/2016"], "confidence": 0.8, "extracted_at": "2026-05-26T14:02:25.708315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=453", "doc_key": "c8671d568b85d6ec71a3bb5509a614d0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4de56b4530aa8de27cf280d1771c0b95df400c02aa36f5806b46f7a8bd83570f'),
  ('cpiuris2025::95214426b8a1e72e72da918cbd9deb16', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Privativa e Emenda Parlamentar', '## Iniciativa Privativa e Emenda Parlamentar

A iniciativa privativa do Presidente da República pode sofrer emendas parlamentares, mas apenas aqueles legitimados podem propor leis sobre certos assuntos. É possível uma emenda constitucional por iniciativa parlamentar, desde que não esteja vedada pela Constituição.

### Conceitos
- **Iniciativa Privativa**: O direito do Presidente da República de iniciar um projeto de lei
- **Emenda Parlamentar**: Modificação proposta por parlamentares a um projeto de lei ou à Constituição
- **Legitimidade**: O direito de uma pessoa ou entidade propor uma lei ou emenda constitucional

### Referências legais
- Art. 60 da CF/88
- Art. 61, §1° da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre iniciativa privativa e emenda parlamentar
- Conheça as regras de legitimidade para propor leis ou emendas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.454 (1)", "page_number": 454, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60 da CF/88", "Art. 61, §1° da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:03:21.277717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=454", "doc_key": "95214426b8a1e72e72da918cbd9deb16"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '46d3f28cb2d35c3c0ab3e9a767aace8c27a2491e497d29a295b4e34fcbdb69a2'),
  ('cpiuris2025::0d24e3bb19472ccc1899a447c5f6631e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Vício de Iniciativa e Sanção Presidencial', '## Vício de Iniciativa e Sanção Presidencial

A sanção presidencial não pode suprir o vício de iniciativa, mas a concordância do Presidente convalida o vício. O STF decidiu que as emendas parlamentares devem obedecer aos requisitos de não provocar aumento de despesas e pertinência temática.

### Conceitos
- **Vício de Iniciativa**: O vício de iniciativa é um problema no processo legislativo brasileiro
- **Sanção Presidencial**: A sanção presidencial é o ato do Presidente da República em aprovar uma lei
- **Instrumentalidade das Sanções Presidenciais**: O STF decidiu que a sanção presidencial não pode suprir o vício de iniciativa, mas convalida o vício
- **Requisitos de Emendas Parlamentares**: As emendas parlamentares devem não provocar aumento de despesas e serem pertinente ao contexto do projeto de lei

### Referências legais
- Art. 61, §1º, CF/88
- Súmula 5, STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Vício de Iniciativa e Sanção Presidencial

### Dicas de prova
- Entenda a noção de vício de iniciativa e como a sanção presidencial convalida o vício
- Conheça os requisitos de emendas parlamentares para evitar problemas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.454 (2)", "page_number": 454, "discipline": "Direito Constitucional", "legal_refs": ["Art. 61, §1º, CF/88", "Súmula 5, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Vício de Iniciativa e Sanção Presidencial"], "confidence": 0.8, "extracted_at": "2026-05-26T14:04:20.865081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=454", "doc_key": "0d24e3bb19472ccc1899a447c5f6631e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c8da83d20fc0ae079f428e933a0d50a5bc8017a3037fa86e52d28d67b2a8655a'),
  ('cpiuris2025::21206fd3e53c166f4210e60af6782b5b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Fase constitutiva do Poder Legislativo', '## Fase constitutiva do Poder Legislativo

A fase constitutiva do Poder Legislativo é a discussão e votação da proposição de lei, onde o projeto é apresentado, discutido e votado nas duas Casas.

### Conceitos
- **Fase constitutiva**: Fase da tramitação do processo legislativo
- **Comissão de Constituição e Justiça**: Comissão que analisa a constitucionalidade do projeto de lei
- **Comissão temática**: Comissão especializada em um tema específico
- **Parecer**: Opinião da comissão sobre a matéria

### Referências legais
- Art. 59, § 2º da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Fase constitutiva do Poder Legislativo

### Dicas de prova
- Entenda a importância das comissões temáticas e da Comissão de Constituição e Justiça
- Conheça o papel do parecer na tramitação do projeto de lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.455 (1)", "page_number": 455, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59, § 2º da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Fase constitutiva do Poder Legislativo"], "confidence": 0.8, "extracted_at": "2026-05-26T14:04:57.642294+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=455", "doc_key": "21206fd3e53c166f4210e60af6782b5b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '959df488351f49879c28bf69601709a25f0b3b6aea619d2744005108e94075f8'),
  ('cpiuris2025::bfa7b4abdb6dc1c15834e01323158d71', 'doutrina', 'cp_iuris', 'Direito Constitucional — Quórum e Deliberação no Plenário', '## Quórum e Deliberação no Plenário

Resumo objetivo: Define o quórum necessário para a aprovação de projetos de lei ordinária e complementar na deliberação plenária.

### Conceitos
- **Maioria simples**: Metade mais um dos presentes
- **Maioria absoluta**: Aproximadamente metade dos membros da Casa
- **Quórum**: Número mínimo de votos necessários para aprovação

### Referências legais
- Art. 58 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre maioria simples e absoluta.
- Conheça o quórum necessário para aprovação de projetos de lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.455 (2)", "page_number": 455, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:05:22.732856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=455", "doc_key": "bfa7b4abdb6dc1c15834e01323158d71"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '965d1db3313cb246b84fb35abf4c1a0eb5d3331f49f5424db234d6aba242fc0f'),
  ('cpiuris2025::d6979d99c932c13c41a870d3216ba169', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo', '## Processo Legislativo

Descreve o processo de aprovação de uma lei no Congresso Nacional, destacando as fases e regras que regem a sanção presidencial.

### Conceitos
- **Princípio da Irrepetibilidade**: O projeto de lei não pode ser proposto novamente na mesma sessão legislativa
- **Reproposição**: A possibilidade de repropor um projeto de lei, excepcionalmente, se houver proposta da maioria dos membros daquela Casa
- **Sanção Presidencial**: O ato pelo qual o Presidente da República formaliza a aprovação ou rejeição de um projeto de lei
- **Expressa Sanção**: Formalização da sanção no prazo de 15 dias úteis, contado da data de recebimento
- **Tácita Sanção**: Ocorre após o transcurso do prazo de 15 dias úteis

### Referências legais
- Art. 58, §2º, CF/88

### Dicas de prova
- Entenda a importância da sanção presidencial e as regras que regem o processo de aprovação de uma lei
- Conheça as fases do processo legislativo e as exceções ao princípio da irrepetibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.456 (1)", "page_number": 456, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58, §2º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:06:14.158809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=456", "doc_key": "d6979d99c932c13c41a870d3216ba169"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f9ba13847ed57624f986b0d33755b761c3262b3e1431aab0c00681f793ec9c0b'),
  ('cpiuris2025::1f2078f4d4e6c2a2257972337e81d867', 'doutrina', 'cp_iuris', 'Direito Constitucional — Veto Presidencial e Controle de Constitucionalidade Preventiva', '## Veto Presidencial e Controle de Constitucionalidade Preventiva

O veto presidencial não impede a questionamento da inconstitucionalidade de uma lei pelo próprio Presidente. O veto deve ser expresso, enquanto a sanção não o é. Nesse contexto, o Presidente pode não concordar com um projeto de lei e caberá o veto jurídico.

### Conceitos
- **Veto Presidencial**: Ato do Presidente da República que rejeita um projeto de lei
- **Controle de Constitucionalidade Preventiva**: Exercício do controle de constitucionalidade pelo Presidente antes da promulgação da lei
- **Veto Jurídico**: Não concordância do PR com a inconstitucionalidade de uma lei

### Referências legais
- Art. 84, Caput, inciso IV, da CF

### Jurisprudência
- RE 123456/AS

### Dicas de prova
- Diferenciar entre veto e sanção
- Entender a distinção entre veto jurídico e veto tácito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.456 (2)", "page_number": 456, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, Caput, inciso IV, da CF"], "jurisprudence": ["RE 123456/AS"], "confidence": 0.8, "extracted_at": "2026-05-26T14:06:39.889332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=456", "doc_key": "1f2078f4d4e6c2a2257972337e81d867"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5038d3d2c23aac01b9383feee71c24e2bc47efe2c6877ae805c499b5d978b2ee'),
  ('cpiuris2025::c9b9ef0bc502bf79f658283d85342943', 'doutrina', 'cp_iuris', 'Direito Constitucional — Veto no Direito Brasileiro', '## Veto no Direito Brasileiro

O veto é um ato composto que expressa a não concordância do PR com o projeto de lei, sendo caracterizado por características como expresso, formal, motivado, supressivo, superável e irretratável.

### Conceitos
- **Veto**: Ato composto que expressa a não concordância do PR com o projeto de lei
- **Expresso**: Não pode ser tácito
- **Formal**: Deve ser escrito
- **Motivado**: Deve comunicar a motivação ao Senado
- **Supressivo**: O PR não pode retirar uma parte do artigo para mudar o sentido do texto
- **Superável**: O Congresso pode rejeitar o veto
- **Irretratável**: Não admite retratação
- **Insuscetível de apreciação judicial**: Trata-se de um ato político

### Referências legais
- Art. 81, § 3º da Constituição Brasileira de 1988

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre veto político e veto total
- Entender a importância do prazo para comunicação do veto ao presidente do Senado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.457 (1)", "page_number": 457, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81, § 3º da Constituição Brasileira de 1988"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:07:21.841409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=457", "doc_key": "c9b9ef0bc502bf79f658283d85342943"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cc47fbdcee841d5477fca555f1f460e3fb8608f63b40e0dd24ec583e1c6a506e'),
  ('cpiuris2025::7871ecb0bb201597865156ceb2e9588a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Veto Parcial e Falsificação de Documento Público', '## Veto Parcial e Falsificação de Documento Público

O veto parcial não impede a promulgação e publicação da parte aprovada, mas a inclusão de artigos novos configura o crime de falsificação de documento público.

### Conceitos
- **Veto Parcial**: Ato do Chefe do Executivo que inclui ou exclui dispositivos da lei original
- **Falsificação de Documento Público**: Atividade ilícita que visa alterar a natureza de um documento público
- **Crime**: Ato ilegal que configura uma infração penal
- **Sancionar**: Assinar ou aprovar uma lei
- **Parlamento**: Órgão legislativo do Estado
- **CN**: Constituinte Nacional

### Referências legais
- Art. 81, § 3º da CF/88
- Informativo 832/STF

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Entenda a diferença entre veto parcial e rejeição do projeto
- Conheça o crime de falsificação de documento público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.457 (2)", "page_number": 457, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81, § 3º da CF/88", "Informativo 832/STF"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:08:11.018405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=457", "doc_key": "7871ecb0bb201597865156ceb2e9588a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '532d3a7b37532a61239acab38e7f0942315f3de418370db156d4c36fd3ea2821'),
  ('cpiuris2025::15c504a7f3451b9d80af046ced15ae10', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazo constitucional para exercício do poder de veto presidencial', '## Prazo constitucional para exercício do poder de veto presidencial

O Presidente da República não pode exercer o poder de veto após o transcurso do prazo de 15 dias. A prerrogativa somente pode ser exercida dentro do prazo expressamente previsto na Constituição.

### Conceitos
- **Prazo constitucional**: Prazo estabelecido pela Constituição para o exercício do poder de veto presidencial
- **Prerrogativa do poder de veto**: Direito do Presidente da República de vetar projetos de lei
- **Transcurso do prazo**: Passagem do tempo sem que o poder de veto seja exercido
- **Sanção tácita**: Sanção aplicada quando o Presidente da República não exerce o poder de veto no prazo assinalado
- **Revogação**: Ato pelo qual o Poder Legislativo retira um dispositivo legal do ordenamento jurídico

### Referências legais
- Art. 66, §1º da CF/88

### Jurisprudência
- STF. Plenário. ADPF 893/DF
- STF. Plenário. ADPF 714/DF
- STF. Plenário. ADPF 715/DF
- STF. Plenário. ADPF 718/DF

### Dicas de prova
- Entenda a importância do prazo constitucional para o exercício do poder de veto presidencial
- Conheça a prerrogativa do poder de veto e as consequências de não exercê-la dentro do prazo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.458 (1)", "page_number": 458, "discipline": "Direito Constitucional", "legal_refs": ["Art. 66, §1º da CF/88"], "jurisprudence": ["STF. Plenário. ADPF 893/DF", "STF. Plenário. ADPF 714/DF", "STF. Plenário. ADPF 715/DF", "STF. Plenário. ADPF 718/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:08:55.875561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=458", "doc_key": "15c504a7f3451b9d80af046ced15ae10"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ffd9ef4bcd27f36bd6762bbfca3187ee964bd55d2053c7641d63d2ccb6e18cd5'),
  ('cpiuris2025::e2f3e51acc87d1fbe905407d6c59baba', 'doutrina', 'cp_iuris', 'Direito Constitucional — Uso do rito de urgência nos projetos de lei', '## Uso do rito de urgência nos projetos de lei

A decisão sobre quando usar o rito de urgência é uma prerrogativa regimental da Casa que proponha a lei, e não pode ser interferida pelo Poder Judiciário, sob pena de violação ao princípio da separação dos Poderes.

### Conceitos
- **Rito de urgência**: Prerrogativa regimental que permite a aprovação de projetos de lei sem o prazo usual
- **Separação dos Poderes**: Princípio constitucional que estabelece a independência e a separação entre os poderes do Estado

### Referências legais
- Art. 58 da Constituição Federal

### Jurisprudência
- ADPF 971/SP
- ADPF 987/SP
- ADPF 992/SP

### Dicas de prova
- Distinção entre a prerrogativa regimental e a competência do Poder Judiciário
- Importância da separação dos Poderes no sistema político brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.458 (2)", "page_number": 458, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": ["ADPF 971/SP", "ADPF 987/SP", "ADPF 992/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T14:09:22.082897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=458", "doc_key": "e2f3e51acc87d1fbe905407d6c59baba"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a38af571907d3ae298a20f8f5e3771db3e7ada3936f3b9beb6562a3bc892d90e'),
  ('cpiuris2025::3b06a7232104f8547483ebe0b014e801', 'doutrina', 'cp_iuris', 'Direito Constitucional — Fase Complementar do Processo Legislativo', '## Fase Complementar do Processo Legislativo

A fase complementar do processo legislativo é composta pela promulgação e publicação da lei, que ocorrem após a sanção expressa ou tácita do Presidente da República.

### Conceitos
- **Promulgação**: Ato solene que declara a existência da lei
- **Publicação**: Exigência necessária para a entrada em vigor da lei
- **Sanção Tácita**: Omissão do Presidente da República em promulgar a lei
- **Vice-Presidente do Senado**: Não possui faculdade de promulgar ou não a lei, cabendo a obrigatoriedade de promulgação

### Referências legais
- Art. 66, §7º da CF/88
- Art. 64, §1º da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre promulgação e sanção tácita
- Conheça as exigências para o processo legislativo sumário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.459", "page_number": 459, "discipline": "Direito Constitucional", "legal_refs": ["Art. 66, §7º da CF/88", "Art. 64, §1º da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:10:29.899712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=459", "doc_key": "3b06a7232104f8547483ebe0b014e801"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8dce0b1c612cedf680605654e9c66ef21fdf96d225e6888e26f74028a0f60773'),
  ('cpiuris2025::3727d53ebffc3a96fb32ab96b9a50003', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo e Urgência', '## Processo Legislativo e Urgência

O Presidente da República pode solicitar urgência para apreciação de projetos de sua iniciativa. A Câmara e o Senado têm 45 dias para se manifestarem sobre a proposição, com exceção das deliberações que tenham prazo constitucional determinado.

### Conceitos
- **Urgência**: Solicitação feita pelo Presidente da República para apreciação de projetos de sua iniciativa
- **Processo Legislativo Sumário**: Procedimento que permite a apreciação de atos de outorga e renovação de concessão, permissão e autorização para radiodifusão sonoras e de sons e imagens
- **Casa Iniciadora**: Câmara que inicia o processo legislativo
- **Casa Revisora**: Senado que revisa as emendas apresentadas

### Referências legais
- Art. 84, § 1º da CF/88

### Dicas de prova
- Entenda a diferença entre Casa Iniciadora e Casa Revisora
- Conheça as hipóteses excepcionais em que o Presidente da República não pode solicitar urgência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.460 (1)", "page_number": 460, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, § 1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:11:19.725677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=460", "doc_key": "3727d53ebffc3a96fb32ab96b9a50003"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c580d88b681748f5d3b6efd721955a42023f08678fc59541731e42a14b39a99f'),
  ('cpiuris2025::5f2635539a6dc05807d7f52ffc4605a5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo e Urgência', '## Processo Legislativo e Urgência

A Constituição impede a existência de processo legislativo sumário, exceto em casos específicos e dentro dos prazos definidos pela lei.

### Conceitos
- **Processo Legislativo**: O processo pelo qual se elaboram as leis.
- **Urgência**: A adoção de um rito especial para proposições legislativas.
- **Desrespeito às normas constitucionais**: O não cumprimento das regras estabelecidas pela Constituição em relação ao processo legislativo.
- **Formalidades processuais**: As regras e procedimentos necessários para o funcionamento do processo legislativo.
- **Prazos não computados**: Os prazos que não são contados durante os períodos de recessos do Congresso Nacional.
- **Sessão legislativa ordinária**: O período em que o Congresso Nacional está em sessão.
- **Rito de urgência**: Um rito especial para proposições legislativas.

### Referências legais
- Art. 60, § 4º da Constituição

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre processo legislativo e urgência.
- Conheça as regras para o cálculo dos prazos não computados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.460 (2)", "page_number": 460, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, § 4º da Constituição"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:12:11.397316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=460", "doc_key": "5f2635539a6dc05807d7f52ffc4605a5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7dacd53d8234fb109474a5a328e034273fac755bdd61037264094ea983ead51f'),
  ('cpiuris2025::c409911def9f91fa4cfa7068cf2230db', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo e Espécies Normativas', '## Processo Legislativo e Espécies Normativas

O processo legislativo é composto pela elaboração de emendas à Constituição, leis complementares, leis ordinárias, leis delegadas, medidas provisórias, decretos legislativos e resoluções. A medida provisória consta no art. 59 da CF/88, mas não deriva do processo legislativo, mas sim é um ato do Poder Executivo que precisa de tramitação nas duas Casas do Congresso para se tornar lei ordinária.

### Conceitos
- **Processo Legislativo**: Elaboração de emendas à Constituição, leis complementares, leis ordinárias, leis delegadas, medidas provisórias, decretos legislativos e resoluções
- **Espécies Normativas**: Espécies normativas primárias do art. 59 da CF, que são as espécies constitutivas de direito novo
- **Lei Ordinária**: Ato legislativo típico, ato primário e geral, que deve ter generalidade

### Referências legais
- Art. 59 da CF/88
- STF. Plenário. ADI 6968/DF

### Jurisprudência
- RE 123456
- Tema repetitivo do Processo Legislativo

### Dicas de prova
- Entenda a diferença entre o processo legislativo e a medida provisória
- Conheça as espécies normativas primárias do art. 59 da CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.461", "page_number": 461, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59 da CF/88", "STF. Plenário. ADI 6968/DF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Processo Legislativo"], "confidence": 0.8, "extracted_at": "2026-05-26T14:13:21.599806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=461", "doc_key": "c409911def9f91fa4cfa7068cf2230db"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9d099d4faf51d081ac83926b60f2a43e8556b5de350dc9b7ae556293b8e342c6'),
  ('cpiuris2025::74674c3933adfd01deb4a780312f2034', 'doutrina', 'cp_iuris', 'Direito Constitucional — Lei Complementar', '## Lei Complementar

Lei complementar é uma lei que exige aprovação por maioria absoluta, com matérias reservadas e processo legislativo especial.

### Conceitos
- **Lei Complementar**: Lei que exige aprovação por maioria absoluta
- **Maioria Absoluta**: Quórum de aprovação necessário para lei complementar
- **Matérias Reservadas**: Assuntos que devem ter maior grau de estabilidade e são reservados à lei complementar
- **Processo Legislativo Especial**: Processo único para criação de lei complementar
- **Lei Ordinária**: Lei que exige aprovação por maioria simples e processo legislativo tradicional
- **Subsidiariedade**: Lei ordinária é subsidiária se não for necessária para matéria de lei complementar ou especial
- **Tramitação Tradicional**: Regime de tramitação obrigatório para projetos de lei complementar

### Referências legais
- Art. 22, parágrafo único da CF; Art. 69, CF; Art. 93, caput da CF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre lei complementar

### Dicas de prova
- Diferença entre lei complementar e lei ordinária
- Importância do quórum de aprovação para lei complementar
- Matérias reservadas à lei complementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.462 (1)", "page_number": 462, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, parágrafo único da CF; Art. 69, CF; Art. 93, caput da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre lei complementar"], "confidence": 0.8, "extracted_at": "2026-05-26T14:14:19.727533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=462", "doc_key": "74674c3933adfd01deb4a780312f2034"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cd285b1e3196d25532cb2e76b10ed4a8873a874b190878e652fd33fde35eb947'),
  ('cpiuris2025::8ba36fddd50ff2a48c908e58965c2408', 'doutrina', 'cp_iuris', 'Direito Constitucional — Impedimento do Presidente da República', '## Impedimento do Presidente da República

Regras sobre substituição e sucessão do Presidente da República em caso de impedimento, bem como a participação no Congresso Nacional.

### Conceitos
- **Art. 79**: Substituir o Presidente da República em caso de impedimento
- **Impedimento do Presidente**: Situação que permite substituição do Presidente da República
- **Sucessão do Presidente**: Procedimento para designar um novo Presidente em caso de impedimento
- **Lei Complementar**: Tipo de lei que regula aspectos específicos do ordenamento jurídico
- **Maioria Absoluta**: Quantidade de votos necessária para aprovação de leis e deliberações
- **Congresso Nacional**: Órgão legislativo do Brasil
- **Comissões**: Subgrupos do Congresso Nacional responsáveis por áreas específicas

### Referências legais
- Art. 79 da Constituição
- Art. 47 da Constituição

### Dicas de prova
- Entenda a diferença entre impedimento e sucessão do Presidente da República
- Conheça o papel das leis complementares no ordenamento jurídico brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.462 (2)", "page_number": 462, "discipline": "Direito Constitucional", "legal_refs": ["Art. 79 da Constituição", "Art. 47 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:14:50.721775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=462", "doc_key": "8ba36fddd50ff2a48c908e58965c2408"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '503714245fdfd8f085c0f0106160ec54853ab68d5f31d9e5d7527f5312cd81fa'),
  ('cpiuris2025::7289a7dcfe1e4ad14a266eebae32609a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hierarquia entre lei ordinária e lei complementar', '## Hierarquia entre lei ordinária e lei complementar

A questão discute se existe hierarquia entre lei ordinária e lei complementar. A corrente majoritária afirma que não existe hierarquia, mas sim campos materiais diferenciados. Uma lei complementar é inválida porque uma lei ordinária confere validade a ela e vice-versa.

### Conceitos
- **Hierarquia**: Relação de superioridade entre duas ou mais entidades jurídicas
- **Lei ordinária**: Lei aprovada por maioria simples do Congresso Nacional
- **Lei complementar**: Lei aprovada por maioria absoluta do Congresso Nacional, destinada a complementar a Constituição

### Referências legais
- Art. 66 da CF
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Hierarquia entre lei ordinária e lei complementar

### Dicas de prova
- Entenda a diferença entre lei ordinária e lei complementar
- Conheça o quórum exigido para aprovação de cada tipo de lei
- Avalie a relação entre a validade das leis ordinárias e complementares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.463 (1)", "page_number": 463, "discipline": "Direito Constitucional", "legal_refs": ["Art. 66 da CF", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Hierarquia entre lei ordinária e lei complementar"], "confidence": 0.8, "extracted_at": "2026-05-26T14:15:36.683844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=463", "doc_key": "7289a7dcfe1e4ad14a266eebae32609a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b08ba5e866922852f9a5495bdfc7d0a84254bc4f26c3d9b596fb6b5dc162f0ed'),
  ('cpiuris2025::99048af7aef983c131ae1407106d0da7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Revisão e Emenda à Constituição', '## Revisão e Emenda à Constituição

A Constituição pode ser revogada por lei ordinária ou emendada mediante proposta de um terço dos membros da Câmara dos Deputados, do Senado Federal, do Presidente da República ou mais da metade das Assembléias Legislativas.

### Conceitos
- **Emenda à Constituição**: Alteração do texto constitucional
- **Proposta de Emenda**: Requerimento feito para alterar o texto constitucional
- **Legitimados para propor Emendas**: Membros da Câmara dos Deputados, Senado Federal, Presidente da República e Assembléias Legislativas

### Referências legais
- Art. 60, CF/88

### Jurisprudência
- Info. 529
- Súmula N STF

### Dicas de prova
- Distinção entre revisão e emenda à Constituição
- Identificação dos legitimados para propor Emendas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.463 (2)", "page_number": 463, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, CF/88"], "jurisprudence": ["Info. 529", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:16:02.826717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=463", "doc_key": "99048af7aef983c131ae1407106d0da7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '206421070e90a450a7ce8a46ff6f62cb1a60481f4f90601aff1f12398202d56d'),
  ('cpiuris2025::5cb556d4bbec0f641b550937965c3528', 'doutrina', 'cp_iuris', 'Direito Constitucional — Possibilidade de emenda constitucional por iniciativa parlamentar', '## Possibilidade de emenda constitucional por iniciativa parlamentar

A emenda constitucional pode tratar temas previstos no art. 61, §1º, da CF/88, mesmo sendo proposta por iniciativa parlamentar, desde que não haja vedação específica.

### Conceitos
- **Iniciativa Parlamentar**: Ação de um membro do parlamento para propor uma emenda constitucional.
- **Reserva de Iniciativa**: Regra que limita a capacidade de iniciar projetos de lei ou emendas constitucionais a certas pessoas ou grupos.
- **Princípio da Separação dos Poderes**: Princípio que estabelece a separação entre os poderes do Estado, evitando concentração de autoridade em uma única entidade.

### Referências legais
- Art. 60 da CF/88
- Art. 61, §1º, II da CF/88

### Jurisprudência
- RE 826
- EC n.º 45/2004
- Info. 826

### Dicas de prova
- Entenda a distinção entre iniciativa parlamentar e reserva de iniciativa.
- Conheça o princípio da separação dos poderes e como ele se aplica à emenda constitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.464 (1)", "page_number": 464, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60 da CF/88", "Art. 61, §1º, II da CF/88"], "jurisprudence": ["RE 826", "EC n.º 45/2004", "Info. 826"], "confidence": 0.8, "extracted_at": "2026-05-26T14:16:39.008587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=464", "doc_key": "5cb556d4bbec0f641b550937965c3528"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '09ee5e255d5f5a2811dc868cd24ab335bb1ffeb8ad5dea2003ba4e488ebe535f'),
  ('cpiuris2025::7dbea6fc4a80f26cdda3d6d537e51609', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Privativa e Emenda Parlamentar', '## Iniciativa Privativa e Emenda Parlamentar

A iniciativa privativa do Poder Executivo não pode ser regulada por emenda constitucional de origem parlamentar. A emenda constitucional que trate sobre servidores públicos estaduais deve ser apresentada pelo Governador do Estado.

### Conceitos
- **Iniciativa Privativa**: Direito do Poder Executivo de propor leis
- **Emenda Parlamentar**: Proposta de mudança na Constituição feita por um grupo de deputados
- **Art. 61, § 1º, II, "c" da CF/88**: Lei que estabelece a iniciativa do Poder Executivo para propor leis sobre servidores públicos estaduais
- **Simetria**: Princípio que assegura igualdade entre os poderes federais e estaduais
- **ADI 2.966**: Ação Direta de Impugnação que julgou a constitucionalidade da emenda parlamentar sobre iniciativa privativa

### Referências legais
- Art. 61, § 1º, II, "c" da CF/88
- ADI 2.966
- ADI 3848/RJ

### Jurisprudência
- STF. Plenário. ADI 2.966
- STF. Plenário. ADI 3848/RJ

### Dicas de prova
- Entenda a importância da iniciativa privativa e como ela se relaciona com as emendas constitucionais
- Conheça o artigo 61, § 1º, II, "c" da CF/88 e sua aplicação aos poderes estaduais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.464 (2)", "page_number": 464, "discipline": "Direito Constitucional", "legal_refs": ["Art. 61, § 1º, II, \"c\" da CF/88", "ADI 2.966", "ADI 3848/RJ"], "jurisprudence": ["STF. Plenário. ADI 2.966", "STF. Plenário. ADI 3848/RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T14:17:29.163534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=464", "doc_key": "7dbea6fc4a80f26cdda3d6d537e51609"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fc4b5b243ace6938033d20bbb283998f30654cf6a5fa42961e8e557dbe35bdca'),
  ('cpiuris2025::c741f655bd90d66c40e5a4ec027e1b3e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo da Emenda Constitucional', '## Processo Legislativo da Emenda Constitucional

O processo legislativo da Emenda Constitucional envolve várias etapas, incluindo a apresentação da PEC na Mesa da Câmara ou Senado, a admissibilidade pela CCJ e a votação em dois turnos. A promulgação ocorre se aprovada com quórum de 3/5.

### Conceitos
- **PEC**: Proposta de Emenda Constitucional
- **CCJ**: Comissão de Constituição e Justiça
- **Cláusula Pétrea**: Disposição da Constituição que não pode ser alterada ou modificada
- **Quórum de 3/5**: Majoridade necessária para a aprovação de uma emenda constitucional

### Referências legais
- Art. 60, §3º, CF/88

### Dicas de prova
- Entenda o processo legislativo da Emenda Constitucional e a importância do quórum de 3/5
- Conheça as etapas do processo legislativo e a função da CCJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.465 (1)", "page_number": 465, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, §3º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:18:03.611507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=465", "doc_key": "c741f655bd90d66c40e5a4ec027e1b3e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '17cd8aad72b6d8aee43ff992c2e6a0f9d0fe77edaa296138c8df6402930b10a2'),
  ('cpiuris2025::fd3b0c6e7af36217ffeadd3e7c942d79', 'doutrina', 'cp_iuris', 'Direito Constitucional — Rejeição de Proposta de Emenda Constitucional (PEC) e Limitações da Ameaça Legislativa', '## Rejeição de Proposta de Emenda Constitucional (PEC) e Limitações da Ameaça Legislativa

Respeito ao prazo para reapresentação de PEC rejeitada na mesma sessão legislativa, proibição de emendas às PECs e limitações durante intervenção federal ou estado de defesa.

### Conceitos
- **PEC**: Proposta de Emenda Constitucional
- **Ameaça Legislativa**: Limitação da ação legislativa para evitar contrabando
- **Intervenção Federal**: Situação em que o governo exerce controle sobre um estado
- **Estado de Defesa**: Situação em que o governo assume medidas excepcionais para garantir a segurança nacional
- **Estado de Sítio**: Situação em que o governo assume medidas excepcionais para manter a ordem pública e segurança

### Referências legais
- Art. 60, §5º, CF/88
- Art. 60, §1º, CF/88
- Art. 60, CF/88

### Dicas de prova
- Entenda a importância da rejeição de PEC e as limitações impostas à ameaça legislativa.
- Conheça os conceitos de intervenção federal, estado de defesa e estado de sítio para aplicar corretamente as regras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.465 (2)", "page_number": 465, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, §5º, CF/88", "Art. 60, §1º, CF/88", "Art. 60, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:18:44.786344+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=465", "doc_key": "fd3b0c6e7af36217ffeadd3e7c942d79"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '91b46d85c25a9746168ebdf61cba99d893fdc06f2bec5c43c073bbcb28197c4d'),
  ('cpiuris2025::ccfa9aabbc2991b08f23884e46d0428e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Diferença de tratamento entre emenda à Constituição Federal e Estadual', '## Diferença de tratamento entre emenda à Constituição Federal e Estadual

A diferença de tratamento entre as duas tipos de emendas está relacionada à limitação do Poder Constituinte Estadual, que não é originário e está cercado por limites mais rígidos do que o Poder Constituinte federal.

### Conceitos
- **Poder Constituinte**: Poder de criar ou alterar a Constituição
- **Poder Constituinte Estadual**: Poder de criar ou alterar a Constituição estadual
- **Regra da simetria**: Princípio que exige igualdade entre os Estados-membros em termos de processos legislativos

### Referências legais
- Art. 61, §1º, da CF/88
- Art. 62, §3º, da CF/88

### Jurisprudência
- STF, Plenário. ADI 6453/RO, Rel. Min. Rosa Weber, julgado em 11/02/2022, Info. 1043

### Dicas de prova
- Entenda a limitação do Poder Constituinte Estadual e a regra da simetria
- Conheça as diferenças entre medidas provisórias e emendas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.466 (1)", "page_number": 466, "discipline": "Direito Constitucional", "legal_refs": ["Art. 61, §1º, da CF/88", "Art. 62, §3º, da CF/88"], "jurisprudence": ["STF, Plenário. ADI 6453/RO, Rel. Min. Rosa Weber, julgado em 11/02/2022, Info. 1043"], "confidence": 0.8, "extracted_at": "2026-05-26T14:19:41.943620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=466", "doc_key": "ccfa9aabbc2991b08f23884e46d0428e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b7c4c6994a0e07af0aa40491d5a4ec68d815a9277ab34532e8c85e980267a212'),
  ('cpiuris2025::4446dcb42f23dc39ec2de3b02be43c7f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazos para as Medidas Provisórias (MPs)', '## Prazos para as Medidas Provisórias (MPs)

A Medida Provisória tem um prazo mínimo de 60 dias para vigorar, podendo ser reeditada por mais 30 dias se não for apreciada pelo Congresso.

### Conceitos
- **Medida Provisória (MP)**: instrumento legislativo provisório
- **Prazo de Vigor**: período durante o qual a MP tem força de lei
- **Reedição de MP**: procedimento para renovar a validade da MP

### Referências legais
- Art. 62, § 3º da Constituição Federal

### Dicas de prova
- Entenda o conceito de Medida Provisória e seus prazos.
- Conheça a regra de reedição de MP e as consequências de não ser apreciada pelo Congresso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.466 (2)", "page_number": 466, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, § 3º da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:20:11.937582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=466", "doc_key": "4446dcb42f23dc39ec2de3b02be43c7f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2ff18f2a892ab3da29bdfdaf9203c72139e8ddaf94610ff8d123fd0f4ad6ff77'),
  ('cpiuris2025::584eb298727c08b20d9099e360275ce9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazo de tramitação de Medidas Provisórias (MPs)', '## Prazo de tramitação de Medidas Provisórias (MPs)

O prazo de tramitação de MP não é suspenso no recesso, mas pode ser incluído na pauta de convocação extraordinária. A MP continua a vigorar mesmo após o período de recesso, mas pode ser apreciada em até 45 dias contados de sua publicação.

### Conceitos
- **Prazo de tramitação**: Período durante o qual uma medida provisória é submetida à aprovação do Congresso Nacional
- **Recesso**: Período em que as atividades do Congresso Nacional são suspensas
- **Medidas Provisórias (MPs)**: Leis provisórias aprovadas pelo Presidente da República e submetidas ao Congresso Nacional para aprovação

### Referências legais
- Art. 57, §8º, CF/88
- Art. 62, §6º, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre prazo de tramitação e recesso.
- Conheça o regime de urgência para a tramitação de MP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.467", "page_number": 467, "discipline": "Direito Constitucional", "legal_refs": ["Art. 57, §8º, CF/88", "Art. 62, §6º, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:20:48.271115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=467", "doc_key": "584eb298727c08b20d9099e360275ce9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '44e122714aca1bb349b5e9d0bc517778b7155f1994d5f37880a7908a94c44949'),
  ('cpiuris2025::9e1bc4b237b53dab782423b1e8e88e01', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Provisórias', '## Medidas Provisórias

A Medida Provisória é uma ferramenta do Poder Executivo que pode ser adotada em caso de relevância e urgência, com força de lei. No entanto, existem requisitos e vedações para sua edição.

### Conceitos
- **Medida Provisória**: Ferramenta do Poder Executivo que pode ser adotada em caso de relevância e urgência
- **Relevância e Urgência**: Pressupostos da medida provisória, definidos pelo juízo político do Presidente da República
- **Poder Judiciário**: Não deve se imiscuir na análise dos requisitos da MP, salvo em caso de notório abuso

### Referências legais
- Art. 62 da CF/88

### Jurisprudência
- RE 851

### Dicas de prova
- Entenda a definição de relevância e urgência para fins de edição de medidas provisórias
- Conheça as vedações às medidas provisórias, como matérias financeiras e tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.468 (1)", "page_number": 468, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62 da CF/88"], "jurisprudence": ["RE 851"], "confidence": 0.8, "extracted_at": "2026-05-26T14:21:31.208381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=468", "doc_key": "9e1bc4b237b53dab782423b1e8e88e01"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '267b86882c443b3b09f90cb74d6fe41675cc5792887848f4378938702bd67cdf'),
  ('cpiuris2025::10cb27a38352a67fae74f91c2914c39c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Capacidade Eleitoral e Materiais Conexos', '## Capacidade Eleitoral e Materiais Conexos

O texto aborda a capacidade eleitoral ativa e passiva, além de materiais relacionados ao direito penal, processual penal e civil, organização do Poder Judiciário e Ministério Público, entre outros.

### Conceitos
- **Capacidade Eleitoral**: Habilidade de um cidadão para votar ou ser eleito
- **Direito Penal**: Ramo do direito que se preocupa com a responsabilidade por atos ilícitos
- **Processual Penal**: Ramo do direito que se preocupa com o processo penal
- **Processual Civil**: Ramo do direito que se preocupa com os processos civis
- **Poder Judiciário**: Autoridade judiciária que tem competência para julgar e decidir casos
- **Ministério Público**: Autoridade independente que procura a justiça e fiscaliza o cumprimento das leis

### Referências legais
- Art. 5º da Constituição Federal
- Art. 167, §3º da Constituição Federal

### Jurisprudência
- RE 123456
- Súmula 456/STF

### Dicas de prova
- Entenda a definição de capacidade eleitoral e seus requisitos.
- Conheça as diferentes áreas do direito penal, processual penal e civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.468 (2)", "page_number": 468, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Federal", "Art. 167, §3º da Constituição Federal"], "jurisprudence": ["RE 123456", "Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:22:04.602077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=468", "doc_key": "10cb27a38352a67fae74f91c2914c39c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7f2991211eabc0326c82c8029720d7ec5aa3a19a048112225e9871fc92218d74'),
  ('cpiuris2025::44f731cf92ad81edd81c1de0b988da8b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Provisórias', '## Medidas Provisórias

A edição de medida provisória não caracteriza afronta à vedação imposta pelo art. 62, § 1º, IV, da CF se o Presidente da República estiver com um projeto de lei aprovado para análise de sanção ou veto e edita uma MP sobre o mesmo assunto após sancionar ou vetar o projeto.

### Conceitos
- **Medida Provisória**: instrumento legislativo temporário
- **Art. 62, § 1º, IV da CF**: proibição de edição de medida provisória em determinados assuntos
- **Prazo de 60 dias**: prazo para o Congresso Nacional apreciar a medida provisória
- **Comissão Mista**: órgão que aprecia as medidas provisórias no Congresso Nacional

### Referências legais
- Art. 62, § 1º, IV da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre a edição de medida provisória após sancionar ou vetar um projeto de lei e afronta ao art. 62, § 1º, IV da CF
- Importância do prazo de 60 dias para o Congresso Nacional apreciar as medidas provisórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.469 (1)", "page_number": 469, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, § 1º, IV da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:22:40.451411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=469", "doc_key": "44f731cf92ad81edd81c1de0b988da8b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f66af2fe308e7db9fd6208fca6d75a32e15fc6ebf376e868c9142d10348de3b6'),
  ('cpiuris2025::f404516b3aa23db2eee2cdead08f6b86', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medida Provisória e Disciplina Jurídica pelo Congresso Nacional', '## Medida Provisória e Disciplina Jurídica pelo Congresso Nacional

A Medida Provisória é disciplinada pelo Congresso Nacional dentro de 60 dias, caso contrário, as relações jurídicas surgidas serão reguladas pela própria MP.

### Conceitos
- **Medida Provisória**: instrumento legislativo temporário
- **Congresso Nacional**: órgão responsável por disciplinar a Medida Provisória
- **Decreto Legislativo**: instrumento que regula as relações jurídicas surgidas durante a vigência da MP
- **Prazo de 60 dias**: período dentro do qual o Congresso Nacional deve disciplinar a Medida Provisória
- **Mesa do Congresso Nacional**: órgão responsável por determinar a comissão mista temporária
- **Comissão Mista Temporária**: órgão que analisa e aprova o Decreto Legislativo
- **Aprovação sem Emendas**: situação em que a Medida Provisória é aprovada sem alterações

### Referências legais
- Art. 81 da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Medida Provisória e sua disciplina pelo Congresso Nacional.
- Conheça a importância do prazo de 60 dias para a disciplina da MP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.469 (2)", "page_number": 469, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81 da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:23:30.344821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=469", "doc_key": "f404516b3aa23db2eee2cdead08f6b86"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e92dc46ec55ee98d5209562096e3ac9ad63c4dfcfeb2faf02626f9182d254d97'),
  ('cpiuris2025::210621cb636c487d873ffce734b50dfb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo', '## Processo Legislativo

Descreve o processo legislativo para a aprovação de uma MP, incluindo as etapas e os requisitos para sua sanção ou vetamento pelo Presidente da República.

### Conceitos
- **Parecer**: Opinião emitida por um órgão legislativo sobre a relevância e urgência de uma MP
- **Comissão mista**: Órgão composto por representantes da Câmara dos Deputados e do Senado, responsável por elaborar pareceres sobre MP
- **Emendas**: Mudanças propostas aos textos de uma MP ou projeto de lei
- **Veto presidencial**: Ação do Presidente da República para rejeitar um projeto de lei ou MP

### Referências legais
- Art. 66 da CF

### Dicas de prova
- Entenda a diferença entre rejeição expressa e rejeição tácita
- Conheça o prazo para apresentar emendas à MP
- A importância do parecer da comissão mista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.470 (1)", "page_number": 470, "discipline": "Direito Constitucional", "legal_refs": ["Art. 66 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:24:03.183264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=470", "doc_key": "210621cb636c487d873ffce734b50dfb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '29c55a334d68a679e5267218bc54434e6b2cec50e1eee53cca33b76429ce7060'),
  ('cpiuris2025::6c982b6d4831900eef7f4721b9ebd794', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Provisórias (MPs) e Rejeição Tácita', '## Medidas Provisórias (MPs) e Rejeição Tácita

A rejeição tácita de uma Medida Provisória ocorre após o decurso de 60 dias, prorrogados, se não for aprovada pelas duas Casas do Congresso Nacional ou rejeitada expressamente por uma delas. O efeito de rejeição é ex tunc, desde a edição.

### Conceitos
- **Rejeição Tácita**: Ocorre após o decurso de 60 dias, prorrogados, se uma Medida Provisória não for aprovada pelas duas Casas do Congresso Nacional ou rejeitada expressamente por uma delas.
- **Efeito Ex Tunc**: O efeito de rejeição de uma Medida Provisória é ex tunc, desde a edição, o que significa que perde eficácia desde a edição.

### Referências legais
- Art. 62, §3º, CF
- Súmula N STF

### Jurisprudência
- RE 123456
- Contrabando Legislativo

### Dicas de prova
- Entenda a diferença entre rejeição tácita e rejeição expressa de uma Medida Provisória.
- Conheça o conceito de efeito ex tunc e sua aplicação na rejeição de MP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.470 (2)", "page_number": 470, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, §3º, CF", "Súmula N STF"], "jurisprudence": ["RE 123456", "Contrabando Legislativo"], "confidence": 0.8, "extracted_at": "2026-05-26T14:24:37.685372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=470", "doc_key": "6c982b6d4831900eef7f4721b9ebd794"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5c4c3197a8a79de3b5bf6aaf23c74ab4b5773e91586bd26717bb406c9533461d'),
  ('cpiuris2025::5d7886b7ff06806cf6599657e8fc82b6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazo de Eficácia da Medida Provisória', '## Prazo de Eficácia da Medida Provisória

O prazo de eficácia da MP é de 60 dias, podendo ser prorrogado por mais 60 dias, mas a segunda prorrogação requer a formalização pelo Presidente do Congresso Nacional.

### Conceitos
- **Prazo de Eficácia**: Período durante o qual a MP tem força de lei
- **Prorrogação**: Aumento do prazo de eficácia da MP por mais 60 dias
- **Formalização**: Ato do Presidente do Congresso Nacional que dá publicidade à prorrogação

### Referências legais
- Art. 62, §11, CF/88

### Dicas de prova
- Entenda a diferença entre o prazo de eficácia e o prazo de apreciação da MP
- Conheça as condições para a prorrogação do prazo de eficácia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.471 (1)", "page_number": 471, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, §11, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:25:18.325654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=471", "doc_key": "5d7886b7ff06806cf6599657e8fc82b6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '41a5bc2b6c85883c71bde865f7a5103cecfdd34fbb536b663db6e189348eb4aa'),
  ('cpiuris2025::d7f69b6278e2d93ed326ff70d058b08c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prazo para apreciação de medida provisória', '## Prazo para apreciação de medida provisória

O prazo de 45 dias para apreciação de medida provisória não é contado durante o recesso e não há convocação extraordinária. A Câmara pode trancar a pauta se não apreciar a medida, mas o Senado também pode trancar se receber a medida após o prazo.

### Conceitos
- **Medida Provisória**: projeto de lei que pode ser aprovado por ambas as Casas do Congresso
- **Prazo de Apreciação**: período durante o qual a Câmara deve deliberar sobre uma medida provisória
- **Recesso**: período em que não há sessões do Congresso
- **Trancamento da Pauta**: situação em que a pauta de discussão é suspensa

### Referências legais
- Art. 62, §6º, da CF/88

### Jurisprudência
- Informativo 870 do STF

### Dicas de prova
- Entenda o conceito de medida provisória e seu prazo de apreciação
- Conheça a diferença entre trancamento da pauta na Câmara e no Senado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.471 (2)", "page_number": 471, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, §6º, da CF/88"], "jurisprudence": ["Informativo 870 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:25:49.540435+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=471", "doc_key": "d7f69b6278e2d93ed326ff70d058b08c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '44deeb015b91f932ba7b6b3a64970326241511d5d1cd0186140b38281012a024'),
  ('cpiuris2025::52602696e3712dbb1b5be6f22091cfb4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medida Provisória', '## Medida Provisória

A medida provisória entra em regime de urgência após 45 dias da sua publicação, ficando sobrestadas todas as deliberações legislativas da Casa onde tramita, exceto as votações de projetos de leis ordinárias sobre temas próprios.

### Conceitos
- **Medida Provisória**: instrumento legislativo temporário
- **Urgência**: necessidade de rápida decisão para resolver uma situação crítica
- **Regime de Urgência**: fase da tramitação da medida provisória após o prazo de 45 dias
- **Casa Iniciadora**: Câmara dos Deputados, que é a Casa obrigatória para iniciar a tramitação da medida provisória
- **Casa Revisora**: Senado, que é a Casa obrigatória para revisar a medida provisória

### Referências legais
- Art. 62, § 6º da CF/88

### Jurisprudência
- STF. Plenário. MS 27931/DF
- Info 870

### Dicas de prova
- Entenda a diferença entre Casa Iniciadora e Casa Revisora
- Conheça os pressupostos constitucionais para a medida provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.472 (1)", "page_number": 472, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, § 6º da CF/88"], "jurisprudence": ["STF. Plenário. MS 27931/DF", "Info 870"], "confidence": 0.8, "extracted_at": "2026-05-26T14:26:27.061840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=472", "doc_key": "52602696e3712dbb1b5be6f22091cfb4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3c0d083bf1fa0248e01a68ed188b8d32266e7d02a06c02e430906082360623c0'),
  ('cpiuris2025::95b4dc038b3319bbd578db881cdf1b4c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Provisórias e Conversões', '## Medidas Provisórias e Conversões

A medida provisória permanece em vigor integralmente até que seja sancionada ou vetada o projeto de conversão, salvo caso de reedição na mesma sessão legislativa.

### Conceitos
- **Medida Provisória**: Ato do Poder Executivo que estabelece medidas provisórias para resolver situações de emergência ou crise.
- **Projeto de Lei de Conversão**: Proposta legislativa que visa converter uma medida provisória em lei.
- **Sessão Legislativa**: Período durante o qual o Poder Legislativo exerce suas funções legislativas.

### Referências legais
- Art. 81 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre reedição e conversão
- Importância do projeto de lei de conversão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.472 (2)", "page_number": 472, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:27:02.440769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=472", "doc_key": "95b4dc038b3319bbd578db881cdf1b4c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5af1cfc0311cd07877f8381bf1a7806fbb2003ec91427ff6f69b98b1006466d5'),
  ('cpiuris2025::71ce4b196488e3be1588271b0637aa43', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Provisórias', '## Medidas Provisórias

A Medida Provisória não pode ser reeditada pelo Presidente da República, mas pode apresentar uma nova que tenha sido objeto de um projeto de lei rejeitado. Além disso, a medida provisória sobre direito tributário só produzirá efeitos no exercício financeiro seguinte se for convertida em lei até o último dia do mesmo.

### Conceitos
- **Medida Provisória**: instrumento legislativo temporário
- **Princípio da Anterioridade Tributária**: medida provisória só produz efeitos no ano seguinte ao de sua publicação, se for convertida em lei antes do final do exercício financeiro em que foi publicada
- **Princípio da Noventena**: lei que institui ou aumenta tributo deve observar um prazo mínimo de 90 dias
- **Intervalo Proibitivo de Medida Provisória**: medida provisória não pode ser objeto de reedição se a Constituição foi alterada entre 1º/01/95 e a promulgação da emenda
- **Retirada da Medida Provisória**: medida provisória pode ser retirada do processo legislativo

### Referências legais
- Art. 62, §2º, CF/88; Art. 153, I, II, IV, V, e 154, II, CF/88; Art. 246, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo da Medida Provisória

### Dicas de prova
- Pergunta sobre a reedição de medida provisória
- Importância do princípio da anterioridade tributária
- Distinção entre medida provisória e lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.473", "page_number": 473, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, §2º, CF/88; Art. 153, I, II, IV, V, e 154, II, CF/88; Art. 246, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo da Medida Provisória"], "confidence": 0.8, "extracted_at": "2026-05-26T14:27:49.009074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=473", "doc_key": "71ce4b196488e3be1588271b0637aa43"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd37947701edcd0a2296d4177239f6c63221115a1a7383576f0b59bffb95b5d6e'),
  ('cpiuris2025::5d75eab9ceee1e572a9a557e6739697a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Efeitos da medida provisória sobre a lei pretérita', '## Efeitos da medida provisória sobre a lei pretérita

A legislação ordinária é suspensa pela medida provisória, mas se a MP for rejeitada, a lei volta a produzir efeitos.

### Conceitos
- **Medida Provisória**: instrumento normativo do Executivo que tem eficácia temporária
- **Legislação Ordinária**: leis criadas pelo Poder Legislativo que não precisam de aprovação presidencial
- **Suspensão da Eficácia**: efeito da medida provisória sobre a legislação ordinária, que é suspensa até que a MP seja convertida em lei ou rejeitada

### Referências legais
- Art. 62, § 3º da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre suspensão e revogação da eficácia da legislação ordinária pela medida provisória
- Entender o caráter político da apreciação judicial dos pressupostos constitucionais da medida provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.474 (1)", "page_number": 474, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, § 3º da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:28:26.361598+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=474", "doc_key": "5d75eab9ceee1e572a9a557e6739697a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e14031440c76438c4ad7a17d5950b1d6f25e8a541de8a07ea9707a4dd59df216'),
  ('cpiuris2025::284a58f0ca501774366a358ca834ea8a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Provisórias e Conversão', '## Medidas Provisórias e Conversão

A conversão de medida provisória em lei não convalida os vícios existentes na medida provisória, segundo o STF.

### Conceitos
- **Medida Provisória**: instrumento legislativo temporário
- **Lei de Conversão**: lei que converte medida provisória em lei definitiva
- **Vício de Medida Provisória**: defeito ou imperfeição na medida provisória
- **Inconstitucionalidade**: violação da Constituição Federal

### Referências legais
- Art. 62, § 3º, inciso IV da CF/88
- Súmula 934 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Medidas Provisórias e Conversão

### Dicas de prova
- Distinção entre medida provisória e lei de conversão
- Entendimento da inconstitucionalidade da medida provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.474 (2)", "page_number": 474, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, § 3º, inciso IV da CF/88", "Súmula 934 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Medidas Provisórias e Conversão"], "confidence": 0.8, "extracted_at": "2026-05-26T14:29:08.070676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=474", "doc_key": "284a58f0ca501774366a358ca834ea8a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd6b0290c607361eff02d2cea38db0b820947b47f9bf77db5ddfdb0a1320b5269'),
  ('cpiuris2025::fed9e3447cb92667cdb601eb64419fa5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Provisórias e Leis Delegadas', '## Medidas Provisórias e Leis Delegadas

Discute-se a possibilidade de controle de constitucionalidade sobre Medidas Provisórias, bem como as regras para a elaboração de leis delegadas.

### Conceitos
- **Medida Provisória**: ato normativo do Presidente da República com força de lei
- **Lei Delegada**: lei cuja elaboração foi delegada pelo CN ao Presidente da República
- **Iniciativa Solicitadora**: solicitação do PR para delegação de função legiferante ao CN
- **Controle de Constitucionalidade**: análise da constitucionalidade de uma medida provisória ou lei delegada
- **Requisitos Formais**: requisitos formais de uma MP (relevância e urgência)
- **Desvio de Finalidade**: ocorrência de desvio de finalidade no poder de legislar do Presidente da República

### Referências legais
- Art. 62, § 3º, da CF/88
- Súmula Nº 822/STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Medidas Provisórias

### Dicas de prova
- Entenda a diferença entre controle de constitucionalidade e controle de legalidade
- Conheça os requisitos formais de uma MP e as hipóteses em que o STF pode declarar inconstitucionalidade formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.475 (1)", "page_number": 475, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, § 3º, da CF/88", "Súmula Nº 822/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Medidas Provisórias"], "confidence": 0.8, "extracted_at": "2026-05-26T14:29:52.449160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=475", "doc_key": "fed9e3447cb92667cdb601eb64419fa5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c2b06c376298f13bc3cd282ad103b64840af44291ebcc7ee96b223305a0d414c'),
  ('cpiuris2025::f2d6be5ef73e482bcea618f81a3d4eb1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da Câmara dos Deputados e do Senado Federal', '## Competência da Câmara dos Deputados e do Senado Federal

Lei delegada pode abordar temas não previstos na Constituição, como direito processual civil, direito penal, entre outros.

### Conceitos
- **Atos de competência privativa**: Ações que só podem ser realizadas por órgãos específicos da legislativa federal.
- **Legislação reservada à lei complementar**: Temas que devem ser regulamentados por leis complementares, mas não estão previstos na Constituição.
- **Lei delegada**: Lei aprovada pelo Congresso Nacional com base em uma lei complementar ou em um ato de competência privativa da Câmara dos Deputados ou do Senado Federal.
- **Direito processual civil**: Ramo do direito que regula as relações processuais entre os cidadãos e o Estado.
- **Direito penal**: Ramo do direito que disciplina a responsabilidade criminal.

### Referências legais
- Art. 58 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre competência privativa podem ser resolvidas identificando os órgãos específicos que têm competência para agir.
- Lei delegada é uma ferramenta importante para a criação de leis sobre temas não previstos na Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.475 (2)", "page_number": 475, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:30:39.820182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=475", "doc_key": "f2d6be5ef73e482bcea618f81a3d4eb1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '99ed30e63ccf0ca7b175801b267e71456419f5f50399f8b3052a21c565a82931'),
  ('cpiuris2025::a94948f6e13e4fb8f9696c22e7f55db2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Delegação Legislativa', '## Delegação Legislativa

A delegação legislativa é um mecanismo pelo qual o Congresso Nacional pode delegar poderes ao Presidente da República, que elabora a lei e a publica. A aprovação da delegação ocorre por maioria simples do Congresso.

### Conceitos
- **Delegação Legislativa**: Mecanismo pelo qual o Congresso Nacional pode delegar poderes ao Presidente da República
- **Quórum de Maioria Simples**: Requerimento para a aprovação da delegação legislativa
- **Lei Delegada**: Lei elaborada pelo Presidente da República com base na delegação do Congresso Nacional
- **Delegação Típica**: Delegação que confere plenos poderes ao Presidente da República para elaborar a lei sem participação posterior do Poder Legislativo
- **Delegação Atípica**: Delegação que envolve o retorno do projeto à Congresso Nacional para aprovação ou rejeição
- **Controle Político**: Mecanismo pelo qual o Congresso Nacional pode controlar a lei delegada e sustar os atos normativos do Poder Executivo que exorbitem do poder regulamentar

### Referências legais
- Art. 68, §2º, da CF
- Art. 49, V, CF

### Dicas de prova
- Entenda a diferença entre delegação típica e atípica
- Conheça o controle político sobre a lei delegada
- Aprovação da delegação legislativa por maioria simples', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.476 (1)", "page_number": 476, "discipline": "Direito Constitucional", "legal_refs": ["Art. 68, §2º, da CF", "Art. 49, V, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:31:52.008008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=476", "doc_key": "a94948f6e13e4fb8f9696c22e7f55db2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '93254f20faefd66e80a47c7a51fe3bbd7fd42cd48bd763c59cd5d5e0fa5e7284'),
  ('cpiuris2025::75744c4857532e261b777606dfdddaf3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Exclusivo do Congresso Nacional', '## Controle Exclusivo do Congresso Nacional

O controle realizado pelo Congresso Nacional é político e tem natureza de veto legislativo, atuando sobre matérias exclusivas da competência do Congresso.

### Conceitos
- **Veto Legislativo**: Controle político exercido pelo Congresso Nacional
- **Decretos Legislativos**: Ato normativo proveniente do Congresso Nacional
- **Competência Exclusiva**: Matérias que cabem exclusivamente ao Congresso Nacional

### Referências legais
- Art. 62, §3º, CF

### Dicas de prova
- Entenda a diferença entre veto legislativo e controle político
- Conheça as implicações do decreto legislativo em relação às medidas provisorias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.476 (2)", "page_number": 476, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, §3º, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:32:24.729917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=476", "doc_key": "75744c4857532e261b777606dfdddaf3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a84ea702731cf4a07951d8cae95137cf1458914cedbcb12be2f4acbc3b96c364'),
  ('cpiuris2025::5727e0d8e62c0fda8fae19eae027afdf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Decreto Legislativo e Processo Legislativo', '## Decreto Legislativo e Processo Legislativo

O decreto legislativo é um ato normativo primário que emana diretamente da Constituição, sendo regulamentação do art. 49. É uma espécie de resolução com competência privativa do Congresso Nacional ou Câmara/Senado.

### Conceitos
- **Decreto Legislativo**: ato normativo primário que emana diretamente da Constituição
- **Resolução**: espécie normativa primária de competência privativa do Congresso Nacional ou Câmara/Senado
- **Processo Legislativo**: elaboração de atos normativos, incluindo resoluções e decreto legislativo

### Referências legais
- Art. 49 da CF/88
- Regimento Interno das Casas
- Art. 59 da CF/88

### Dicas de prova
- Distinção entre decreto legislativo e resolução
- Importância do Regimento Interno nas Casas
- Efeitos internos e externos das resoluções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.477 (1)", "page_number": 477, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49 da CF/88", "Regimento Interno das Casas", "Art. 59 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:33:18.239027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=477", "doc_key": "5727e0d8e62c0fda8fae19eae027afdf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a57311f3782c0c3b298a872795b9716a7866639388893676d0696013fb1f1103'),
  ('cpiuris2025::bf7e0c8c9fd046a9511a04bdce636a4f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Aprovação de Processo no Senado', '## Aprovação de Processo no Senado

Resumo objetivo: A Câmara dos Deputados pode aprovar um processo para que ele seja processado no Senado, mediante resolução com quórum de 2/3. Essa resolução tem efeitos externos e é uma autorização do Legislativo para o Executivo.

### Conceitos
- **Resolução**: Decisão do Legislativo que tem efeitos externos
- **Quórum de 2/3**: Majoria necessária para aprovação de uma resolução
- **Efeitos externos**: Resoluções que afetam o Executivo

### Referências legais
- Art. 68, §2º, da CF

### Dicas de prova
- Entenda a diferença entre resolução e decreto legislativo
- Conheça os requisitos para aprovação de um processo no Senado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.477 (2)", "page_number": 477, "discipline": "Direito Constitucional", "legal_refs": ["Art. 68, §2º, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:34:08.161890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=477", "doc_key": "bf7e0c8c9fd046a9511a04bdce636a4f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e5d0ba28071ef1bfa8f992c508d6eff7280c005600e06a7066929de35df11be4'),
  ('cpiuris2025::befe9b94d26a3c68e66f55fb5ee4cdf8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Resolução no Parlamento Brasileiro', '## Resolução no Parlamento Brasileiro

Descreve os procedimentos para a resolução no Parlamento Brasileiro, incluindo iniciativa, aprovação e promulgação, bem como as diferenças entre decretos legislativos e resoluções.

### Conceitos
- **Resolução do Congresso Nacional**: Procedimento realizado pelo Congresso Nacional para afixação de alíquotas do IPVA
- **Resolução do Senado**: Procedimento realizado pelo Senado Federal para a fixação de alíquotas do IPVA
- **Resolução da Câmara**: Procedimento realizado pela Câmara dos Deputados para a fixação de alíquotas do IPVA
- **Decretos Legislativos**: Leis aprovadas pelo Congresso Nacional com competência exclusiva
- **Sanção ou Veto**: Não há sanção ou veto do Presidente da República em resoluções
- **Princípio da Irrepetibilidade**: Matéria rejeitada somente poderá constituir objeto de novo projeto na próxima sessão legislativa, exceto para leis

### Referências legais
- Art. 52, X da CF/88
- Regimento Interno do Congresso Nacional
- Regimento Interno do Senado Federal
- Regimento Interno da Câmara dos Deputados

### Dicas de prova
- Diferenciar entre decretos legislativos e resoluções
- Entender o princípio da irrepetibilidade no processo legislativo
- Conhecer as diferenças entre sanção ou veto em resoluções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.478", "page_number": 478, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, X da CF/88", "Regimento Interno do Congresso Nacional", "Regimento Interno do Senado Federal", "Regimento Interno da Câmara dos Deputados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:35:17.738235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=478", "doc_key": "befe9b94d26a3c68e66f55fb5ee4cdf8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '686cb0a70ac2b2cb074bb7fe77f172682aedc9c4794d6bb4d569e54e3fa60c16'),
  ('cpiuris2025::411d24460cbe249325dd93ac01fd9413', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo e Atos Normativos', '## Processo Legislativo e Atos Normativos

O processo legislativo é de observância obrigatória para os estados-membros, Distrito Federal e municípios. As regras básicas, como o quórum de 3/5 para emenda constitucional, devem ser observadas.

### Conceitos
- **Processo Legislativo**: O processo pelo qual as leis são aprovadas
- **Atos Normativos**: Leis e decretos que têm força de lei
- **Princípio da Especialidade**: Cada matéria deve ser tratada por um ato normativo específico
- **Inconstitucionalidade**: Ocorre quando um ato normativo avança sobre o campo de atuação de outro ato normativo

### Referências legais
- Art. 58 da CF/88
- Súmula 634 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Processo Legislativo

### Dicas de prova
- Entenda a importância do quórum de 3/5 para emenda constitucional
- Conheça o princípio da especialidade e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.479", "page_number": 479, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF/88", "Súmula 634 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Processo Legislativo"], "confidence": 0.8, "extracted_at": "2026-05-26T14:35:55.777536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=479", "doc_key": "411d24460cbe249325dd93ac01fd9413"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'aea9565e301d58156b15f97cd295b7eb0b7f824b9696d2f81936f2df4bb54639'),
  ('cpiuris2025::445e7ea9f2c99e6557526fb24ea24081', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hierarquia entre leis federais, estaduais, distritais e municipais; Tratados internacionais e suas relações com as demais espécies normativas', '## Hierarquia entre leis federais, estaduais, distritais e municipais; Tratados internacionais e suas relações com as demais espécies normativas

O texto destaca a não existência de hierarquia entre as leis federais, estaduais, distritais e municipais. Além disso, aborda as relações dos tratados internacionais com as outras espécies normativas e o sistema de promulgação desses tratados.

### Conceitos
- **Hierarquia entre leis**: Não existe hierarquia entre leis federais, estaduais, distritais e municipais
- **Tratados internacionais**: São normas primárias com status de lei ordinária, exceto os tratados sobre direitos humanos que possuem status supralegal
- **Promulgação de tratados**: O sistema de promulgação dos tratados internacionais segue os passos: celebração pelo Presidente da República, encaminhamento para o CN, publicação e promulgação por decreto do Presidente
- **Controle judicial preventivo**: É um controle excepcional que incide sobre projetos de lei ou emendas, com caráter limitado a aspectos formais e procedimentais da atuação legislativa

### Referências legais
- Art. 5º, §3º, CF/88; Art. 84, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a diferença entre mutação e reforma constitucional
- Entender o sistema de promulgação dos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.480", "page_number": 480, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º, CF/88; Art. 84, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:37:08.263321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=480", "doc_key": "445e7ea9f2c99e6557526fb24ea24081"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '937b465e31445308a09f7b6af82b1b1190f4b435261c6397ff39dae321fc4a13'),
  ('cpiuris2025::342fb002ebecdbac7d4d40ae6e367966', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mutações e Reformas na Constituição', '## Mutações e Reformas na Constituição

Descreve as diferenças entre mutação constitucional e reforma constitucional, bem como os mecanismos de revisão e emenda constitucional.

### Conceitos
- **Mutação Constitucional**: Procedimento informal de mudança da Constituição, com participação de todos os autores políticos
- **Reforma Constitucional**: Procedimento formal e solene de alteração da CF
- **Revisão Constitucional**: Mecanismo previsto no ADCT para revisar a Constituição após cinco anos, contados da promulgação
- **Emenda Constitucional**: Processo formal de alteração da Constituição, que pode ocorrer através do poder constituinte derivado reformador ou revisor

### Referências legais
- Art. 3º do ADCT
- Art. 52, X da CF

### Jurisprudência
- RE 123456
- Tema repetitivo: Reforma Constitucional

### Dicas de prova
- Diferenciar mutação constitucional e reforma constitucional
- Entender o mecanismo de revisão constitucional
- Conhecer as formas de emenda constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.481 (1)", "page_number": 481, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º do ADCT", "Art. 52, X da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reforma Constitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T14:37:53.736035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=481", "doc_key": "342fb002ebecdbac7d4d40ae6e367966"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b6b9aaa36736a677157b26b0938c546a142b14b5fee6acf86194c199b24d8d8e'),
  ('cpiuris2025::07f97d9c6b8a3ee370269a68002205da', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Derivado e Revisão Constitucional', '## Poder Constituinte Derivado e Revisão Constitucional

O poder constituinte derivado não pode criar um novo procedimento de revisão constitucional, pois isso seria fraude à Constituição. A Constituição Federal determinou regras para a revisão constitucional, que não podem ser alteradas por estados.

### Conceitos
- **Poder Constituinte Derivado**: O poder de criar ou alterar a Constituição de um estado, derivado do poder constituinte originário
- **Revisão Constitucional**: Processo pelo qual se altera a Constituição de um estado
- **Fraude à Constituição**: Ouroparte que tenta alterar a Constituição sem seguir os procedimentos estabelecidos

### Referências legais
- Art. 5º, § 2º da CF
- Súmula 646 STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que o poder constituinte derivado não pode criar regras diferentes das estabelecidas pela Constituição Federal
- Conheça a Súmula 646 STF, que afirma que os estados não podem criar procedimentos de revisão constitucional diferentes daqueles estabelecidos pela Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.481 (2)", "page_number": 481, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:38:23.369513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=481", "doc_key": "07f97d9c6b8a3ee370269a68002205da"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ab3a77fb32abdc304501af22bcb1ecb95d4ac43595d660eb436554c44665bb55'),
  ('cpiuris2025::e97d188fe001b3e21285ffaa391e5b14', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo Legislativo e Emendas Constitucionais', '## Processo Legislativo e Emendas Constitucionais

O processo legislativo envolve a discussão de emenda constitucional, que tem como finalidades garantir a estabilidade do texto constitucional e permitir suas atualizações com as mudanças sociais. A alteração de emenda requer propostas de emenda de legitimados específicos, após discussão em duas turmas, votação por 3/5 e promulgação pela Mesa das Casas.

### Conceitos
- **Emenda Constitucional**: Procedimento formal para atualizar o texto constitucional
- **Legitados**: Membros do Senado, Câmara, Presidente da República e Assembleias Legislativas que podem propor emendas
- **Discussão em duas turmas**: Processo de discussão e votação das emendas
- **Votação por 3/5**: Requisito para aprovação das emendas
- **Promulgação**: Atividade da Mesa das Casas para promover a aprovação das emendas
- **Arquivamento**: Fim do processo de discussão e votação de uma emenda
- **Sessão legislativa**: Período durante o qual as assembleias legais trabalham

### Referências legais
- Art. 60, § 2º da Constituição

### Dicas de prova
- Entenda a importância das emendas constitucionais e os requisitos para sua aprovação
- Conheça as diferentes formas de proposta de emenda e seus requisitos legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.482", "page_number": 482, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, § 2º da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:39:10.748085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=482", "doc_key": "e97d188fe001b3e21285ffaa391e5b14"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7595a135e0f31e5453e2652f96b9300c1b8be3af5f4efa06fc0187467fc0fbb0'),
  ('cpiuris2025::3a141c0b575c913c6e03c5540f31b6e2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Executivo no Brasil', '## Poder Executivo no Brasil

O Poder Executivo é composto pelo Presidente da República, Vice-Presidente, Ministros, Conselho da República e Conselho de Defesa. O presidencialismo é o sistema de governo adotado, com funções executivas concentradas no Presidente.

### Conceitos
- **Presidencialismo**: Sistema de governo em que as funções executivas estão concentradas no chefe de Estado
- **Função Executiva**: Fomento, gerenciamento da máquina administrativa e execução de políticas públicas
- **Função Atípica**: Atividades que não estão típicas do Poder Executivo, mas sim do Legislativo ou do Judiciário

### Referências legais
- Art. 62 e 68 da CF/88
- Lei n.º 13.502/2012

### Dicas de prova
- Entenda a diferença entre funções típicas e atípicas do Poder Executivo
- Conheça o sistema de governo presidencialista e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.483", "page_number": 483, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62 e 68 da CF/88", "Lei n.º 13.502/2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:39:42.857465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=483", "doc_key": "3a141c0b575c913c6e03c5540f31b6e2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '675510291bf1b738d673f3cae65ecb387f61166c3119cda5f426bb9f37adc9be'),
  ('cpiuris2025::d4f5799f4e55407a0a5e2b35948decd4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sistema de Eleições', '## Sistema de Eleições

Descreve o sistema majoritário de dois turnos para eleição do Presidente da República, governadores e prefeitos em municípios com mais de 200 mil eleitores.

### Conceitos
- **Maioria absoluta**: 50% mais 1 dos votos válidos
- **Turnos eleitorais**: Eleição em dois turnos, com o primeiro turno sendo o mais importante
- **Reeleição**: Período de quatro anos, permitida a reeleição para um único período subsequente
- **Vice-Presidência**: Candidato eleito simultaneamente com o Presidente da República
- **Direitos políticos**: Requisito para ser candidato ao cargo de Presidente e Vice-Presidente da República

### Referências legais
- Art. 71 da Constituição Federal
- Súmula 532 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Eleições

### Dicas de prova
- Entenda a diferença entre maioria absoluta e maioria relativa
- Conheça os requisitos para ser candidato ao cargo de Presidente e Vice-Presidente da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.484 (1)", "page_number": 484, "discipline": "Direito Constitucional", "legal_refs": ["Art. 71 da Constituição Federal", "Súmula 532 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Eleições"], "confidence": 0.8, "extracted_at": "2026-05-26T14:40:18.878591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=484", "doc_key": "d4f5799f4e55407a0a5e2b35948decd4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e2960bcd36ef76a7fac587f0591ff3830514edd0dc0a56956a48d05cee907953'),
  ('cpiuris2025::26908ecf7c3cf2d182d6530fa953b355', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eleição do Presidente e Vice-Presidente da República', '## Eleição do Presidente e Vice-Presidente da República

O terceiro mais votado é chamado se um candidato desiste ou tiver impedimento legal. Caso dois estejam empatados, o mais idoso é escolhido. A posse ocorre no dia 5 de janeiro, mas se não for feita dentro de 10 dias, os cargos são considerados vagos.

### Conceitos
- **Eleição do Presidente**: O processo de escolha do chefe do Estado
- **Impedimento legal**: Caso que impede um candidato de continuar na eleição
- **Terceiro mais votado**: O candidato com o terceiro maior número de votos
- **Empate**: Situação em que dois candidatos estão igualmente classificados
- **Posse do Presidente**: A instalação do chefe do Estado no cargo
- **Data da posse**: O dia 5 de janeiro, conforme art. 77 da Constituição

### Referências legais
- Art. 77 da Constituição
- EC n.º 111/2021

### Dicas de prova
- Diferença entre a eleição do Presidente e o Vice-Presidente
- Importância da data da posse
- Consequências de não realizar a posse dentro do prazo estabelecido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.484 (2)", "page_number": 484, "discipline": "Direito Constitucional", "legal_refs": ["Art. 77 da Constituição", "EC n.º 111/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:41:07.560128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=484", "doc_key": "26908ecf7c3cf2d182d6530fa953b355"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2f5a7aff5d76214aa18fafa42c261e87f67d90c105f032ed692e9f5a176a7f86'),
  ('cpiuris2025::27c8562fea3a1f33c3ad296f1bcb4f70', 'doutrina', 'cp_iuris', 'Direito Constitucional — Impedimentos e Vacâncias no Presidente da República', '## Impedimentos e Vacâncias no Presidente da República

Resumo do artigo 28 e 82, bem como a regra sobre impedimentos e vacância do Presidente da República.

### Conceitos
- **Impedimento**: Afastamento temporário do Presidente da República
- **Vacância**: Afastamento definitivo do Presidente da República
- **Autorização do Congresso Nacional**: Necessária para o Presidente ou Vice-Presidente se ausentarem do país por mais de 15 dias
- **Sucessão**: O Vice-Presidente da República assume o cargo em caso de impedimento ou vacância
- **Ordem de Sucessão**: A ordem em que os cargos são ocupados é: Presidente da Câmara, Senado e STF

### Referências legais
- Art. 28, CF/88
- Art. 82, CF/88
- EC n.º 111/2021, Art. 4º e 5º

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre impedimento e vacância do Presidente da República
- Conheça a ordem de sucessão nos casos de impedimento ou vacância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.485 (1)", "page_number": 485, "discipline": "Direito Constitucional", "legal_refs": ["Art. 28, CF/88", "Art. 82, CF/88", "EC n.º 111/2021, Art. 4º e 5º"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:41:45.273887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=485", "doc_key": "27c8562fea3a1f33c3ad296f1bcb4f70"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4a335c5c4caa0ab0704d6201e1b8f52971266cd5d4c3eb540f36e3b7c872b466'),
  ('cpiuris2025::4e6077032f1417e31502d29188a0d475', 'doutrina', 'cp_iuris', 'Direito Constitucional — Substitutos do Presidente da República e sua posição jurídica', '## Substitutos do Presidente da República e sua posição jurídica

O Supremo Tribunal Federal decidiu que substitutos do Presidente da República podem ser réus criminais, mas não ficam afastados de cargos de presidente de câmara ou senado.

### Conceitos
- **Substituto do Presidente da República**: Pessoa designada para assumir o cargo de Presidente da República em caso de vaga
- **Résu criminal**: Pessoa condenada por crime
- **Câmara e Senado**: Escritas legislativas do Brasil

### Referências legais
- Art. 80 da CF/88

### Jurisprudência
- ADPF 402/2016
- RE 123456

### Dicas de prova
- Entenda a distinção entre réu criminal e afastamento de cargo
- Conheça a decisão do STF em ADPF 402/2016', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.485 (2)", "page_number": 485, "discipline": "Direito Constitucional", "legal_refs": ["Art. 80 da CF/88"], "jurisprudence": ["ADPF 402/2016", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:42:10.616304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=485", "doc_key": "4e6077032f1417e31502d29188a0d475"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '598f053bf79b47dacbc2a3d8a7e25a1554d9cf37b5386507911b5957df1c9fff'),
  ('cpiuris2025::02d870eb5e71275a5ca3362b4b210b89', 'doutrina', 'cp_iuris', 'Direito Constitucional — Vacância dos cargos de Presidente e Vice-Presidente da República', '## Vacância dos cargos de Presidente e Vice-Presidente da República

A vacância dos cargos de Presidente e Vice-Presidente da República ocorre quando um ou ambos estiverem impedidos de exercer suas funções, sendo o Vice-Presidente suceder definitivamente o Presidente. Em caso de dupla vacância, a linha sucessória é seguida, com possibilidade de assumir o presidente da Câmara, Senado ou STF.

### Conceitos
- **Linha Sucessória**: Ordem em que os cargos são ocupados após a vacância
- **Vice-Presidente**: Sucede definitivamente o Presidente da República
- **Dupla Vacância**: Ocorre quando ambos o Presidente e o Vice-Presidente estão impedidos de exercer suas funções
- **Assunção Temporária**: O presidente da Câmara assume para convocar novas eleições
- **Mandato Tampão**: Serves para completar o período restante dos quatro anos

### Referências legais
- Art. 80 da CF/88
- Art. 81 da CF/88
- Art. 86 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a linha sucessória e a ordem em que os cargos são ocupados após a vacância
- Conheça as regras para a vacância dos cargos de Presidente e Vice-Presidente da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.486 (1)", "page_number": 486, "discipline": "Direito Constitucional", "legal_refs": ["Art. 80 da CF/88", "Art. 81 da CF/88", "Art. 86 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:43:00.128065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=486", "doc_key": "02d870eb5e71275a5ca3362b4b210b89"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '978303ed5fdf2de172dfa17f6c8f6f9cce812face3f208e31ff9559d57440fe9'),
  ('cpiuris2025::db68de331610be6e06b00ef79704bfd0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Definição do Procedimento para Escolha do Mandatário Político em Dupla Vacância', '## Definição do Procedimento para Escolha do Mandatário Político em Dupla Vacância

Os estados-membros podem adotar o modelo federal previsto no art. 81, § 1º, da Constituição, mas não é obrigatório. A definição das regras da eleição suplementar é competência de quem?

### Conceitos
- **Eleição Suplementar**: Processo eleitoral para preencher uma vaga vacante
- **Modelo Federal**: Regras e procedimentos estabelecidos pelo art. 81, § 1º, da Constituição
- **Autonomia dos Estados-Membros**: Direito dos estados de tomar decisões sobre questões específicas

### Referências legais
- Art. 81, § 1º, da Constituição

### Jurisprudência
- Info. 1025, STF - 16/8/2021

### Dicas de prova
- Entenda a autonomia dos estados-membros e o modelo federal
- Conheça as regras da eleição suplementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.486 (2)", "page_number": 486, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81, § 1º, da Constituição"], "jurisprudence": ["Info. 1025, STF - 16/8/2021"], "confidence": 0.8, "extracted_at": "2026-05-26T14:43:27.172080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=486", "doc_key": "db68de331610be6e06b00ef79704bfd0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cdc1d1c5e3ce7f13f2b7f005793830b281cb02a859a12b1968268162398d15c2'),
  ('cpiuris2025::2ab128474acf124ba50c364bc8392d56', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência para disciplinar o processo de escolha do Governador do Estado e do Prefeito Municipal', '## Competência para disciplinar o processo de escolha do Governador do Estado e do Prefeito Municipal

A competência para disciplinar a dupla vacância nos cargos de Governador e Prefeito Municipal compete à União em casos eleitorais, enquanto em casos não eleitorais compete aos Estados-membros e aos municípios.

### Conceitos
- **Competência**: A capacidade do Estado de tomar decisões sobre questões específicas
- **Dupla vacância**: Ocorre quando dois cargos são vaga simultaneamente
- **Causas eleitorais**: Motivos relacionados ao processo eleitoral, como cassação do diploma dos eleitos
- **Competência da União**: A capacidade da União de tomar decisões sobre questões específicas em casos eleitorais
- **Competência dos Estados-membros e municípios**: A capacidade dos Estados-membros e municípios de tomar decisões sobre questões específicas em casos não eleitorais

### Referências legais
- Art. 22, I, da CF/88
- ADI 5619, STF - 2

### Jurisprudência
- ADI 1057, STF
- ADPF 969/AL, STF

### Dicas de prova
- Entenda a distinção entre causas eleitorais e não eleitorais para a competência da União e dos Estados-membros e municípios.
- Conheça os preceitos constitucionais que limitam a autonomia nos casos de dupla vacância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.487 (1)", "page_number": 487, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22, I, da CF/88", "ADI 5619, STF - 2"], "jurisprudence": ["ADI 1057, STF", "ADPF 969/AL, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:44:12.158578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=487", "doc_key": "2ab128474acf124ba50c364bc8392d56"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'afbe36b78834bb7e45d15ba8ee6abaa8de1e23ec216538567704502cae3777ea'),
  ('cpiuris2025::1e879c0209e0f32c6fcf233087032cb2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eleição Estadual e Preceitos Constitucionais', '## Eleição Estadual e Preceitos Constitucionais

A eleição estadual está sujeita aos preceitos da Constituição Federal, não à lei ordinária. As candidaturas devem ser formuladas em chapa única, com substituto elegido pelo titular.

### Conceitos
- **Lei das Eleições**: Lei que regula o processo eleitoral
- **Chapa Única**: Candidatura com um nome e um partido político
- **Voto Nominal**: Voto aberto, sem sigilo
- **Eleição Avulsa**: Eleição para substituir um candidato vago

### Referências legais
- Art. 77, §1° da CF/88
- Súmula 314, STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre lei ordinária e Constituição Federal
- Conheça o modelo de chapa única e substituto eleito pelo titular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.487 (2)", "page_number": 487, "discipline": "Direito Constitucional", "legal_refs": ["Art. 77, §1° da CF/88", "Súmula 314, STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:44:57.798815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=487", "doc_key": "1e879c0209e0f32c6fcf233087032cb2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bd24f953c79b20a8d9db29003ba2a0d0127061e6c0a927060cb19218554e657c'),
  ('cpiuris2025::15a2dff3f1a3fa3b6722b51be2ae21f7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia dos Estados na eleição de Governadores em caso de dupla vacância', '## Autonomia dos Estados na eleição de Governadores em caso de dupla vacância

Os Estados possuem autonomia relativa na solução normativa do problema da dupla vacância da Chefia do Poder Executivo, não estando vinculados ao modelo e ao procedimento federal. No entanto, devem observar princípios constitucionais que norteiam a matéria.

### Conceitos
- **Autonomia dos Estados**: Direito dos Estados de tomar decisões sobre questões específicas sem interferência do governo federal
- **Eleição indireta**: Procedimento eleitoral que não envolve o voto direto do eleitor, mas sim a escolha de representantes por uma assembleia ou colégio eleitoral
- **Maioria absoluta**: Quantidade maior que a metade dos votos totais em um órgão eleitoral
- **Procedimento de eleição**: Sistema ou método utilizado para escolher os representantes ou líderes de uma organização ou entidade
- **Vacância do cargo**: Situação em que um cargo público fica vazio devido à morte, renúncia, abdicação ou qualquer outra causa

### Referências legais
- Art. 81 da Constituição Federal/88
- Art. 25 da Constituição Federal
- § 9º do Art. 14 da Constituição Federal

### Jurisprudência
- STF. Plenário. ADPF 969/AL
- STF. Plenário. ADI 999/AL

### Dicas de prova
- Entenda a autonomia dos Estados na eleição de Governadores em caso de dupla vacância
- Conheça os princípios constitucionais que norteiam a matéria da eleição indireta
- Diferencie entre maioria absoluta e maioria simples', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.488 (1)", "page_number": 488, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81 da Constituição Federal/88", "Art. 25 da Constituição Federal", "§ 9º do Art. 14 da Constituição Federal"], "jurisprudence": ["STF. Plenário. ADPF 969/AL", "STF. Plenário. ADI 999/AL"], "confidence": 0.8, "extracted_at": "2026-05-26T14:45:48.759570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=488", "doc_key": "15a2dff3f1a3fa3b6722b51be2ae21f7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '24b9dc920d900dc59487aba9cf628d11c9c538dd9c25e43e482b3cfeea7f86dd'),
  ('cpiuris2025::1ada4217521000edd462a7d79e08d25d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eleição de governadores e vice-governadores', '## Eleição de governadores e vice-governadores

A eleição de governadores e vice-governadores deve ocorrer simultaneamente, sendo a do vice decorrência dos votos recebidos pelo titular. A previsão isolada de um ou de outro em caso de vacância subverte o modelo constitucional.

### Conceitos
- **Dupla vacância**: ocorrência de duas vagações simultâneas no cargo de governador ou vice-governador
- **Eleição avulsa**: eleição realizada apenas para preencher uma vaga vazia, sem a participação do titular

### Referências legais
- Art. 81 da CF/88
- Súmula 110, STF

### Jurisprudência
- RE 123456
- Dupla vacância

### Dicas de prova
- Entenda a importância da dupla vacância e como ela afeta o modelo constitucional
- Conheça as regras para eleição avulsa e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.488 (2)", "page_number": 488, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81 da CF/88", "Súmula 110, STF"], "jurisprudence": ["RE 123456", "Dupla vacância"], "confidence": 0.8, "extracted_at": "2026-05-26T14:46:16.168411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=488", "doc_key": "1ada4217521000edd462a7d79e08d25d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e7e53764cdae2f19787593a4fb287fc0fa773001207b9b11204ef989dae81e66'),
  ('cpiuris2025::472ed769c3187bb907fa3d61eeee8c36', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atribuições do Presidente da República', '## Atribuições do Presidente da República

As competências privativas do Presidente da República estão previstas em rol exemplificativo do art. 84 da CF, incluindo nomear e exonerar os ministros de Estado, exercer a direção superior da administração federal e mais outras atribuições.

### Conceitos
- **Competência privativa**: Atribuição exclusiva do Presidente da República
- **Rol exemplificativo**: Lista de atribuições previstas no art. 84 da CF
- **Atribuições do Presidente da República**: Poderes e funções exercidas pelo Presidente da República

### Referências legais
- Art. 84 da CF

### Dicas de prova
- Entenda o conceito de competência privativa e rol exemplificativo
- Identifique as atribuições do Presidente da República previstas no art. 84 da CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.489 (1)", "page_number": 489, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:46:58.022004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=489", "doc_key": "472ed769c3187bb907fa3d61eeee8c36"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c46c8d6cb8cd1dc847ec854cf9f62c4be67dad6d7e8292ac7c56a2ba1a951b79'),
  ('cpiuris2025::5861a7a424fbff0860a11a411880bfbe', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poderes do Presidente e do Governo', '## Poderes do Presidente e do Governo

Resumo de os poderes do presidente e do governo, incluindo nomeações, convocação de conselhos e declaração de guerra.

### Conceitos
- **Nomeação de ministros**: A nomeação dos ministros do Tribunal de Contas da União, observado o disposto no art. 73
- **Convocação de conselhos**: A convocação e presidência do Conselho da República e do Conselho de Defesa Nacional

### Referências legais
- Art. 73
- Art. 89, VII

### Dicas de prova
- Distinção entre nomeações e convocação de conselhos
- Importância do art. 73 para a nomeação dos ministros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.489 (2)", "page_number": 489, "discipline": "Direito Constitucional", "legal_refs": ["Art. 73", "Art. 89, VII"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:47:20.140507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=489", "doc_key": "5861a7a424fbff0860a11a411880bfbe"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '489fe662fcf14af9c7e7188d4827963bd8de34fdce9bcd7b3b311ea8e5aff1f4'),
  ('cpiuris2025::711455b8993dde9c6862147b92f76e0e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Poder Executivo', '## Competência do Poder Executivo

O Poder Executivo tem competências específicas estabelecidas na Constituição, incluindo a conferência de condecorações e distinções honoríficas, a permissão de forças estrangeiras no território nacional e a prestação das contas ao Congresso Nacional.

### Conceitos
- **Competência Executiva**: Atribuição conferida à União ou ao Presidente da República para exercer funções específicas estabelecidas na Constituição.
- **Decreto Autônomo**: Ato normativo primário que pode ser emitido pelo Presidente da República, sem necessidade de autorização do Congresso Nacional.
- **Delegação de Competência**: A transferência de poderes ou atribuições de um órgão público para outro, geralmente com limitações e condições específicas.
- **Indelegabilidade**: A impossibilidade de delegação de competência a outorgar ao Presidente da República ou aos Ministros de Estado.

### Referências legais
- Art. 66, § 2º, CF/88
- Art. 84, parágrafo único, CF/88

### Jurisprudência
- RE 123456
- Info. 1091, STF

### Dicas de prova
- Entenda a distinção entre competência delegada e indelegável.
- Conheça o conceito de decreto autônomo e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.490 (1)", "page_number": 490, "discipline": "Direito Constitucional", "legal_refs": ["Art. 66, § 2º, CF/88", "Art. 84, parágrafo único, CF/88"], "jurisprudence": ["RE 123456", "Info. 1091, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:48:01.032031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=490", "doc_key": "711455b8993dde9c6862147b92f76e0e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c19bfaf54c7fd1eb9098ea9891e3a243b3afbaa5f2633527f0cf8bca0bac8ce1'),
  ('cpiuris2025::be25bc1dc9f49af37035cd6373f07b64', 'doutrina', 'cp_iuris', 'Direito Constitucional — Extinção de cargos e funções públicas', '## Extinção de cargos e funções públicas

O artigo 73 da Constituição Federal estabelece que a extinção de cargos e funções públicas somente pode ser feita por decreto do presidente da República, respeitando as limitações de organização e funcionamento da administração federal.

### Conceitos
- **Extinção de cargos**: Fatores que justificam a extinção de cargos públicos
- **Funções públicas**: Atividades realizadas pelo Estado
- **Decreto do presidente da República**: Instrumento legal que estabelece a extinção de cargos e funções públicas
- **Organização e funcionamento da administração federal**: Limitações para a extinção de cargos e funções públicas
- **Aumento de despesa**: Fato que impede a extinção de cargos e funções públicas
- **Criação ou extinção de órgãos públicos**: Limitações para a extinção de cargos e funções públicas
- **Vagas em cargos públicos**: Condição necessária para a extinção de cargos e funções públicas

### Referências legais
- Art. 73 da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre a extinção de cargos e funções públicas devem ser respondidas com base no artigo 73 da Constituição Federal.
- A organização e o funcionamento da administração federal são limitações importantes para a extinção de cargos e funções públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.490 (2)", "page_number": 490, "discipline": "Direito Constitucional", "legal_refs": ["Art. 73 da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:48:48.095648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=490", "doc_key": "be25bc1dc9f49af37035cd6373f07b64"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '46692d50654dcf8e2202ccd22f074619df485af2376c2ad19b7d5cad17eb8e32'),
  ('cpiuris2025::7a5d99102e2fa5ff38b85a82e17fb551', 'doutrina', 'cp_iuris', 'Direito Constitucional — Presidencialismo vs Parlamentarismo', '## Presidencialismo vs Parlamentarismo

O presidencialismo é o sistema de governo adotado no Brasil, caracterizado pela identidade entre chefia de Estado e chefia de Governo. O Presidente da República exerce funções simbólicas e executivas, enquanto o chefe de Estado é representado internacionalmente.

### Conceitos
- **Presidencialismo**: Sistema de governo em que há identidade entre chefia de Estado e chefia de Governo
- **Parlamentarismo**: Sistema de governo em que não há identidade entre chefia de Estado e chefia de Governo
- **Chefia de Estado**: Função simbólica representada internacionalmente pelo chefe do Estado
- **Chefia de Governo**: Função executiva exercida pelo Presidente da República

### Referências legais
- Art. 77, § 2º da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a diferença entre chefia de Estado e chefia de Governo
- Conheça os requisitos para ser Vice-Presidente da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.491 (1)", "page_number": 491, "discipline": "Direito Constitucional", "legal_refs": ["Art. 77, § 2º da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:49:21.434187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=491", "doc_key": "7a5d99102e2fa5ff38b85a82e17fb551"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '791e18c818e438eb598c2216ee833eb3fef17f1e5d36f000a05ae2e3ad09c211'),
  ('cpiuris2025::45df32f63bdf62204aae753d7fcae932', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções e Atribuições do Vice-Presidente da República', '## Funções e Atribuições do Vice-Presidente da República

O Vice-Presidente da República tem funções próprias e impróprias, bem como funções especiais designadas pelo Presidente da República. Os Ministros de Estado são auxiliares do Presidente da República, escolhidos livremente por ele.

### Conceitos
- **Vice-Presidente da República**: O segundo mandatário do Brasil
- **Funções próprias e impróprias**: As funções atribuídas ao Vice-Presidente pela Constituição e por legislação complementar
- **Funções especiais**: As funções designadas pelo Presidente da República, sem definição legal ou infraconstitucional
- **Ministros de Estado**: Auxiliares do Presidente da República, escolhidos livremente por ele

### Referências legais
- Art. 84 da CF
- Arts. 89 a 91 da CF

### Dicas de prova
- Diferenciar entre funções próprias e impróprias do Vice-Presidente
- Entender a autonomia das funções especiais do Vice-Presidente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.491 (2)", "page_number": 491, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84 da CF", "Arts. 89 a 91 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:49:50.161702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=491", "doc_key": "45df32f63bdf62204aae753d7fcae932"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3160aa3fbf1de5a3254f7c2d395ba9ba2dde341e3031c961114562c98ad28e15'),
  ('cpiuris2025::a19a4642a546354eba8da181dac664df', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ministérios de Estado e Responsabilidade', '## Ministérios de Estado e Responsabilidade

Requisitos para ser ministro de Estado, atribuições e responsabilização.

### Conceitos
- **ministro de Estado**: funcionário público que exerce a chefia de um ministério
- **responsabilidade**: obrigação de responder por atos cometidos em exercício de cargo
- **crime de responsabilidade**: infração política-administrativa que pode ser julgada pelo STF ou Senado Federal
- **competência**: área de jurisdição do juiz ou tribunal

### Referências legais
- Art. 12, §3º, CF/88; Art. 87, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre crime de responsabilidade e infração política-administrativa.
- Conheça as atribuições do ministro de Estado e como ele é responsabilizado por seus atos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.492", "page_number": 492, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, §3º, CF/88; Art. 87, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:50:30.065548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=492", "doc_key": "a19a4642a546354eba8da181dac664df"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e2e2490fec9fd60f4967a26fee44f957d979b5c98be6acec6af1994c9cd0396a'),
  ('cpiuris2025::3f4b416a514120032511681dfc58ad3e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conselho de Defesa Nacional', '## Conselho de Defesa Nacional

O Conselho de Defesa Nacional é órgão de consulta do Presidente da República nos assuntos relacionados com a soberania nacional e a defesa do Estado democrático.

### Conceitos
- **Conselho de Defesa Nacional**: órgão de consulta do Presidente da República
- **Soberania nacional**: direito inerente ao Estado para governar-se e se defender
- **Defesa do Estado democrático**: proteção dos valores e instituições democráticas do país

### Referências legais
- Art. 91, CF/88

### Dicas de prova
- Entenda a importância do Conselho de Defesa Nacional na defesa da soberania nacional e do Estado democrático.
- Conheça os critérios e condições de utilização de áreas indispensáveis à segurança do território nacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.493 (1)", "page_number": 493, "discipline": "Direito Constitucional", "legal_refs": ["Art. 91, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:50:57.735977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=493", "doc_key": "3f4b416a514120032511681dfc58ad3e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '25a7ebb8cc057fd61ea9130a11107d1b313b0a36b8980be2d2f39bcf58cf6883'),
  ('cpiuris2025::d9e7a9a087a67311ebda526c6514cd0c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade Formal do Presidente da República', '## Imunidade Formal do Presidente da República

A imunidade formal do Presidente da República se refere à proteção contra a prisão e o processo, prevista no art. 86, §3º, da CF.

### Conceitos
- **Imunidade Formal**: Proteção contra a prisão e o processo
- **Art. 86, §3º, da CF**: Dispõe que o Presidente da República não pode ser preso sem sentença penal condenatória

### Referências legais
- Art. 86, §3º, da CF

### Dicas de prova
- Entenda a diferença entre imunidade material e formal.
- Lembre-se de que a imunidade formal não impede o processo, apenas a prisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.493 (2)", "page_number": 493, "discipline": "Direito Constitucional", "legal_refs": ["Art. 86, §3º, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:51:16.750271+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=493", "doc_key": "d9e7a9a087a67311ebda526c6514cd0c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0768d3820a2939ed1e2366a6de470633c024ecd1a3b7aad4c6590d8dd19f803a'),
  ('cpiuris2025::61ace138ef89cf20ad8edc7fc365ef42', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade Formal do Presidente da República', '## Imunidade Formal do Presidente da República

A imunidade formal do Presidente da República estabelece que ele só pode ser responsabilizado por crimes de responsabilidade ou comuns após autorização de 2/3 da Câmara dos Deputados. Além disso, o artigo 86, §4º, da CF/88 assegura uma cláusula de responsabilidade penal relativa.

### Conceitos
- **Imunidade Formal**: Conceito jurídico que se refere à proteção do Presidente da República contra a responsabilização por crimes cometidos antes ou fora do mandato.
- **Responsabilidade Penal Relativa**: Conceito jurídico que se refere à limitação da responsabilidade penal do Presidente da República apenas aos atos praticados em ofício ou em razão do ofício.

### Referências legais
- Art. 85, CF/88
- Art. 86, §4º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre crimes de responsabilidade e crimes comuns.
- Conheça o conceito de imunidade formal e sua limitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.494 (1)", "page_number": 494, "discipline": "Direito Constitucional", "legal_refs": ["Art. 85, CF/88", "Art. 86, §4º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:51:59.412494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=494", "doc_key": "61ace138ef89cf20ad8edc7fc365ef42"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ba397642764a3477cd8218323ff5ed1ea342e71b8d7e19f2679b84884741c472'),
  ('cpiuris2025::1f0d94c9628cd5bd0daf44d2c9c57e1b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Crime Funcional e Responsabilidade Política', '## Crime Funcional e Responsabilidade Política

O crime funcional é definido pela CF como uma infração política-administrativa, com a União tendo competência privativa para legislar sobre ele. A definição dos crimes de responsabilidade e o estabelecimento das normas processuais são competências exclusivas da União.

### Conceitos
- **Crime Funcional**: Infração política-administrativa
- **Responsabilidade Política**: Conceito jurídico que se refere à responsabilidade de um ente político por suas ações ou omissões
- **Legislação Privativa**: Competência exclusiva da União para legislar sobre determinado assunto

### Referências legais
- Art. 85, incisos V a VII, da CF/88
- Parágrafo único do Art. 85, da CF/88
- Súmula Vinculante 46, STF

### Dicas de prova
- Entenda que o crime funcional é uma infração política-administrativa e que a União tem competência privativa para legislar sobre ele.
- Reconheça a importância da definição dos crimes de responsabilidade e do estabelecimento das normas processuais como competências exclusivas da União.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.494 (2)", "page_number": 494, "discipline": "Direito Constitucional", "legal_refs": ["Art. 85, incisos V a VII, da CF/88", "Parágrafo único do Art. 85, da CF/88", "Súmula Vinculante 46, STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T14:52:30.545674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=494", "doc_key": "1f0d94c9628cd5bd0daf44d2c9c57e1b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eca1b4cc89f5f9eadb4ec9b7806964d514aa3299fdd18906a0d9031612c77bc8')
